window.ANSWER_TERMS = {"necrose":{"title":"Necrose","short":"Ongecontroleerde celdood door schade, waarbij de cel opzwelt, openbarst en een ontstekingsreactie uitlokt.","definition":"<p><b>Necrose</b> is celdood door acute schade (zuurstoftekort, toxinen, trauma). De cel zwelt op en de membraan scheurt.</p><p>De vrijkomende celinhoud lokt een ontstekingsreactie uit — anders dan bij de 'nette' apoptose.</p>","image_url":"","wiki_title":"Necrosis","match":"necrose"},"lymfeklier":{"title":"Lymfeklier","short":"Filterstation in de lymfebaan waar antigenen worden gepresenteerd en de afweerreactie op gang komt.","definition":"<p>De <b>lymfeklier</b> filtert de lymfe en is een ontmoetingsplaats voor antigeenpresenterende cellen en lymfocyten.</p><p>Hier worden T- en B-cellen geactiveerd; bij infectie zwellen lymfeklieren op doordat de lymfocyten zich vermenigvuldigen.</p>","image_url":"","wiki_title":"Lymph node","match":"lymfeklier|lymfeklieren|lymfklier|lymfklieren"},"nodulus":{"title":"Nodulus","short":"Vaste, verheven en voelbare knobbel die dieper in de huid reikt dan een papel (> ~1 cm).","definition":"<p>Een <b>nodulus</b> (nodus, knobbel) is een stevige, verheven laesie die groter is dan een papel en dieper in de dermis of subcutis reikt.</p><p>Voorbeelden zijn een dermatofibroom of sommige huidtumoren.</p>","image_url":"","wiki_title":"Nodule (medicine)","match":"nodulus|nodus|noduli|nodi"},"ulcus":{"title":"Ulcus","short":"Diep huiddefect tot in de dermis of dieper, dat met een litteken geneest (een 'zweer').","definition":"<p>Een <b>ulcus</b> (zweer) is een dieper weefselverlies dat tot in de dermis of subcutis reikt.</p><p>Doordat de dermis is aangetast, geneest het met littekenvorming. Een ulcus cruris (open been) is een bekend voorbeeld.</p>","image_url":"","wiki_title":"Ulcer (dermatology)","match":"ulcus|ulcera"},"atrofie":{"title":"Atrofie","short":"Verdunning of afname van weefsel; bij de huid een dunnere, kwetsbaardere epidermis en/of dermis.","definition":"<p><b>Atrofie</b> is het slinken van een weefsel of orgaan doordat de cellen krimpen of in aantal afnemen.</p><p>Huidatrofie (bijv. na langdurig sterk corticosteroïdgebruik of door veroudering) geeft een dunne, doorschijnende, kwetsbare huid.</p>","image_url":"","wiki_title":"Atrophy","match":"atrofie"},"allergisch contacteczeem":{"title":"Allergisch contacteczeem","short":"Vertraagde (type IV) allergische huidreactie op een stof waarvoor men gevoelig is geworden, zoals nikkel.","definition":"<p><b>Allergisch contacteczeem</b> is een type IV (vertraagde) allergische reactie: na eerdere sensibilisatie geven T-cellen bij hernieuwd contact een eczeemreactie.</p><p>Bekende allergenen zijn nikkel, parfums en conserveermiddelen. Het eczeem verschijnt 1–3 dagen na contact op de blootgestelde plek.</p>","image_url":"","wiki_title":"Contact dermatitis","match":"allergisch contacteczeem"},"excisie":{"title":"Excisie","short":"Chirurgisch wegsnijden van een huidafwijking, meestal met een marge gezond weefsel.","definition":"<p>Een <b>excisie</b> is het operatief wegsnijden van een laesie, doorgaans met een randje gezonde huid (marge).</p><p>Bij een diagnostische excisie wordt de hele afwijking verwijderd voor onderzoek; bij huidkanker is de marge afhankelijk van het type en de dikte.</p>","image_url":"","wiki_title":"Wide local excision","match":"excisie|diagnostische excisie"},"tetanus":{"title":"Tetanus","short":"Tetanus is een vergiftiging door het toxine van Clostridium tetani uit een wond, met pijnlijke spierkrampen en kaakklem.","definition":"<p><strong>Tetanus</strong> wordt veroorzaakt door <em>Clostridium tetani</em>, een anaerobe, sporenvormende grampositieve staaf die in de bodem voorkomt en via wonden binnenkomt.</p><p>Het toxine tetanospasmine blokkeert in het ruggenmerg de afgifte van remmende neurotransmitters (glycine, GABA). Daardoor ontstaan aanhoudende spiercontracties: kaakklem (trismus), risus sardonicus, opisthotonus en ademhalingsproblemen. Preventie: vaccinatie en wondverzorging.</p>","image_url":"","wiki_title":"Tetanus","match":"tetanus|clostridium tetani","option_only":true},"hepatitis a":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a|hav|hepatitis a-virus","option_only":true},"malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria|plasmodium|plasmodium falciparum","option_only":true},"tuberculose":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose|tbc|tb","option_only":true},"n. musculocutaneus":{"title":"N. musculocutaneus","short":"De n. musculocutaneus (C5–C7) innerveert de flexoren van de bovenarm (m. biceps, m. brachialis, m. coracobrachialis) en de huid van de laterale onderarm.","definition":"<p>De <strong>n. musculocutaneus</strong> komt uit de fasciculus lateralis van de plexus brachialis (C5–C7). Hij doorboort de m. coracobrachialis en loopt tussen de m. biceps brachii en de m. brachialis.</p><p>Motorisch innerveert hij de voorste spiergroep van de bovenarm: <em>m. coracobrachialis, m. biceps brachii en m. brachialis</em> (flexie in de elleboog, supinatie). Zijn sensibele eindtak (n. cutaneus antebrachii lateralis) verzorgt de huid van de laterale onderarm.</p>","image_url":"","wiki_title":"Musculocutaneous nerve","match":"n. musculocutaneus|nervus musculocutaneus|n musculocutaneus","option_only":true},"n. axillaris":{"title":"N. axillaris","short":"De n. axillaris (C5–C6) innerveert de m. deltoideus en m. teres minor en de huid over de deltoideus; kwetsbaar bij een schouderluxatie of collum chirurgicum-fractuur.","definition":"<p>De <strong>n. axillaris</strong> ontspringt uit de fasciculus posterior van de plexus brachialis (C5–C6). Hij loopt door de laterale okselspleet (spatium quadrangulare) samen met de a. circumflexa humeri posterior, rond het collum chirurgicum van de humerus.</p><p>Hij innerveert de <em>m. deltoideus</em> (abductie van de arm voorbij ±15°) en de <em>m. teres minor</em> (exorotatie), en sensibel de huid over het onderste deel van de deltoideus (‘regimental badge area’). Letsel bij schouderluxatie of fractuur van het collum chirurgicum.</p>","image_url":"","wiki_title":"Axillary nerve","match":"n. axillaris|nervus axillaris|n axillaris","option_only":true},"n. ulnaris":{"title":"N. ulnaris","short":"De n. ulnaris (C8–T1) loopt achter de epicondylus medialis (‘telefoonbotje’) en innerveert de meeste intrinsieke handspieren en de huid van de pink.","definition":"<p>De <strong>n. ulnaris</strong> komt uit de fasciculus medialis van de plexus brachialis (C8–T1). Hij loopt achter de epicondylus medialis van de humerus door de sulcus nervi ulnaris en via het kanaal van Guyon naar de hand.</p><p>In de onderarm innerveert hij de m. flexor carpi ulnaris en het ulnaire deel van de m. flexor digitorum profundus; in de hand de meeste intrinsieke spieren (mm. interossei, hypothenar, mm. lumbricales III–IV, m. adductor pollicis). Sensibel: de pink en ulnaire helft van de ringvinger. Uitval geeft een klauwhand en een positief teken van Froment.</p>","image_url":"","wiki_title":"Ulnar nerve","match":"n. ulnaris|nervus ulnaris|n ulnaris","option_only":true},"n. radialis":{"title":"N. radialis","short":"De n. radialis (C5–T1) innerveert alle extensoren van boven- en onderarm; letsel (bijv. bij een humerusschachtfractuur) geeft een dropshand.","definition":"<p>De <strong>n. radialis</strong> is de grootste tak van de fasciculus posterior van de plexus brachialis (C5–T1). Hij loopt in de sulcus nervi radialis spiraalsgewijs om de achterkant van de humerusschacht.</p><p>Motorisch innerveert hij de <em>extensoren</em>: m. triceps brachii, m. brachioradialis, en via de r. profundus de extensoren van pols en vingers en de m. supinator. Sensibel verzorgt hij de achterzijde van arm en onderarm en de dorsale zijde van de radiale hand (eerste webspace). Letsel geeft een <em>dropshand</em>.</p>","image_url":"","wiki_title":"Radial nerve","match":"n. radialis|nervus radialis|n radialis","option_only":true},"n. suprascapularis":{"title":"N. suprascapularis","short":"De n. suprascapularis (C5–C6) innerveert de m. supraspinatus en m. infraspinatus.","definition":"<p>De <strong>n. suprascapularis</strong> komt uit de truncus superior van de plexus brachialis (C5–C6). Hij loopt over de schouder naar dorsaal en gaat door de incisura scapulae onder het lig. transversum scapulae superius.</p><p>Hij innerveert twee spieren van de rotator cuff: de <em>m. supraspinatus</em> (start van abductie) en de <em>m. infraspinatus</em> (exorotatie), en geeft sensibele takjes aan het schoudergewricht.</p>","image_url":"","wiki_title":"Suprascapular nerve","match":"n. suprascapularis|nervus suprascapularis","option_only":true},"a. axillaris":{"title":"A. axillaris","short":"De a. axillaris is de voortzetting van de a. subclavia vanaf de buitenrand van de eerste rib tot de onderrand van de m. teres major.","definition":"<p>De <strong>a. axillaris</strong> begint aan de laterale rand van de <em>eerste rib</em> als voortzetting van de a. subclavia en eindigt aan de onderrand van de m. teres major, waarna zij a. brachialis heet.</p><p>De m. pectoralis minor verdeelt haar in drie delen, die samen zes takken afgeven: a. thoracica superior, a. thoracoacromialis, a. thoracica lateralis, a. subscapularis en de aa. circumflexae humeri anterior en posterior. De fasciculi van de plexus brachialis liggen om haar heen.</p>","image_url":"","wiki_title":"Axillary artery","match":"a. axillaris|arteria axillaris","option_only":true},"a. subclavia":{"title":"A. subclavia","short":"De a. subclavia voorziet de arm, een deel van de hals en het brein (via de a. vertebralis) van bloed; rechts uit de truncus brachiocephalicus, links direct uit de aortaboog.","definition":"<p>De <strong>a. subclavia</strong> ontspringt rechts uit de truncus brachiocephalicus en links direct uit de aortaboog. Zij loopt over de eerste rib achter de m. scalenus anterior (scalenusspleet, samen met de plexus brachialis).</p><p>Belangrijke takken: <em>a. vertebralis</em> (naar het brein), a. thoracica interna, truncus thyrocervicalis en truncus costocervicalis. Aan de buitenrand van de eerste rib gaat zij over in de a. axillaris.</p>","image_url":"","wiki_title":"Subclavian artery","match":"a. subclavia|arteria subclavia","option_only":true},"hypersensitivity pneumonitis":{"title":"Extrinsieke allergische alveolitis","short":"Extrinsieke allergische alveolitis is een immuunreactie (type III/IV) in de alveoli op ingeademde organische stoffen, zoals schimmelsporen of vogeleiwitten.","definition":"<p>Bij <strong>hypersensitivity pneumonitis</strong> (extrinsieke allergische alveolitis) reageert het immuunsysteem op herhaald ingeademde organische antigenen: schimmelsporen uit hooi (boerenlong), vogeleiwitten (duivenmelkerslong) of bevochtigerwater.</p><p>Het mechanisme is een type III- (immuuncomplex) en type IV- (T-cel) reactie met lymfocytaire alveolitis en kleine granulomen. Acuut: koorts, hoesten en kortademigheid enkele uren na blootstelling; chronisch kan longfibrose ontstaan. Behandeling: blootstelling vermijden, eventueel corticosteroïden.</p>","image_url":"","wiki_title":"Hypersensitivity pneumonitis","match":"hypersensitivity pneumonitis|extrinsieke allergische alveolitis|eaa|boerenlong|vogelhoudersziekte","option_only":true},"artrose (osteoarthritis)":{"title":"Artrose","short":"Artrose is degeneratie van gewrichtskraakbeen met botreactie; het geeft startpijn en pijn bij belasting, vooral in knieën, heupen en handen bij ouderen.","definition":"<p>Bij <strong>artrose</strong> slijt en verdwijnt het gewrichtskraakbeen, met reactieve veranderingen van het bot: <em>osteofyten</em>, subchondrale sclerose en cysten, en versmalling van de gewrichtsspleet op de röntgenfoto.</p><p>Risicofactoren: leeftijd, overgewicht, eerder letsel en aanleg. Klachten: pijn bij belasting, startpijn en korte ochtendstijfheid (&lt;30 minuten), soms crepitaties en verminderde beweeglijkheid. Typische plaatsen: knie, heup, DIP- en PIP-gewrichten (Heberden- en Bouchardknobbels) en het CMC-1-gewricht.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"artrose (osteoarthritis)|artrose|osteoarthritis|osteoartrose","option_only":true},"septische artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"septische artritis|bacteriële artritis|septische arthritis","option_only":true},"maligniteit":{"title":"Maligniteit","short":"Een maligniteit is een kwaadaardige tumor: ongecontroleerd groeiende cellen die omliggend weefsel binnendringen en kunnen uitzaaien.","definition":"<p>Een <strong>maligniteit</strong> (kanker) is een tumor waarvan de cellen ongeremd delen, het omliggende weefsel <em>infiltreren</em> en via bloed- of lymfevaten kunnen <em>metastaseren</em>. Dat onderscheidt ze van goedaardige (benigne) tumoren, die expansief groeien zonder invasie.</p><p>Maligniteiten ontstaan door een opeenstapeling van genetische veranderingen (activatie van oncogenen, uitschakeling van tumorsuppressorgenen). Systemische verschijnselen kunnen zijn: gewichtsverlies, moeheid, nachtzweten, anemie, trombose en paraneoplastische syndromen.</p>","image_url":"","wiki_title":"","match":"maligniteit|maligne tumor|kanker|kwaadaardige tumor","option_only":true},"gedragsbehoud":{"title":"Gedragsbehoud (stages of change)","short":"Gedragsbehoud is de fase in het model van Prochaska en DiClemente waarin het nieuwe gedrag al langer (meestal >6 maanden) wordt volgehouden.","definition":"<p>Het <strong>transtheoretisch model</strong> (stages of change) van Prochaska en DiClemente beschrijft fasen van gedragsverandering: precontemplatie, contemplatie, preparatie, actie en <strong>gedragsbehoud</strong>; terugval kan op elk moment optreden.</p><p>In de fase van gedragsbehoud heeft iemand het nieuwe gedrag (bijvoorbeeld gestopt met roken) al langer dan ongeveer zes maanden volgehouden. Het accent ligt dan op het voorkomen van terugval.</p>","image_url":"","wiki_title":"","match":"gedragsbehoud|maintenance","option_only":true},"preparatie":{"title":"Preparatie (stages of change)","short":"Preparatie is de fase in het model van Prochaska en DiClemente waarin iemand van plan is binnenkort (binnen ±1 maand) te veranderen en al voorbereidingen treft.","definition":"<p>In het <strong>transtheoretisch model</strong> van gedragsverandering volgt de <strong>preparatiefase</strong> op contemplatie. De persoon heeft besloten om te veranderen, meestal binnen een maand, en zet al kleine stappen: een stopdatum kiezen, informatie zoeken, hulp regelen.</p><p>De volgende fase is actie, waarin het gedrag daadwerkelijk wordt veranderd.</p>","image_url":"","wiki_title":"","match":"preparatie|voorbereidingsfase","option_only":true},"actie":{"title":"Actie (stages of change)","short":"Actie is de fase in het model van Prochaska en DiClemente waarin iemand het gedrag daadwerkelijk heeft veranderd, korter dan ongeveer zes maanden geleden.","definition":"<p>In het <strong>transtheoretisch model</strong> van gedragsverandering is de <strong>actiefase</strong> de periode waarin iemand het nieuwe gedrag actief uitvoert, bijvoorbeeld net gestopt is met roken. Deze fase duurt tot ongeveer zes maanden na de verandering.</p><p>Het risico op terugval is in deze fase groot; ondersteuning richt zich op volhouden en omgaan met verleidingen. Daarna volgt de fase van gedragsbehoud.</p>","image_url":"","wiki_title":"","match":"actie|actiefase","option_only":true},"sociale leertheorie":{"title":"Sociale leertheorie","short":"De sociale leertheorie (Bandura) stelt dat mensen gedrag leren door anderen te observeren en na te doen, en benadrukt eigen-effectiviteit.","definition":"<p>Volgens de <strong>sociale leertheorie</strong> van Albert Bandura leren mensen niet alleen door eigen ervaring en beloning, maar ook door <em>observatie en modeling</em>: het zien van gedrag bij anderen en de gevolgen daarvan.</p><p>Een kernbegrip is <em>eigen-effectiviteit</em> (self-efficacy): het vertrouwen dat je het gedrag zelf kunt uitvoeren. Daarnaast spelen uitkomstverwachtingen en wederzijdse beïnvloeding van persoon, gedrag en omgeving een rol.</p>","image_url":"","wiki_title":"Social learning theory","match":"sociale leertheorie|sociaal-cognitieve theorie|sociale cognitieve theorie","option_only":true},"coping theorie":{"title":"Copingtheorie","short":"Copingtheorie (Lazarus en Folkman) beschrijft hoe mensen een stressor beoordelen en ermee omgaan, probleemgericht of emotiegericht.","definition":"<p>Volgens het <strong>stress-copingmodel</strong> van Lazarus en Folkman hangt de stressreactie af van de <em>beoordeling</em> van een situatie: is het een bedreiging (primaire beoordeling) en heb ik de middelen om ermee om te gaan (secundaire beoordeling)?</p><p><em>Coping</em> zijn de pogingen om met de stressor om te gaan: probleemgericht (de situatie aanpakken) of emotiegericht (de emoties reguleren, bijv. door afleiding of steun zoeken).</p>","image_url":"","wiki_title":"","match":"coping theorie|copingtheorie|coping","option_only":true},"sociale omgeving":{"title":"Sociale omgeving (determinant)","short":"De sociale omgeving als gezondheidsdeterminant omvat de invloed van familie, vrienden, sociale normen, sociaal netwerk en sociaaleconomische positie.","definition":"<p>In modellen van <strong>determinanten van gezondheid</strong> (zoals het model van Lalonde of Dahlgren en Whitehead) is de <strong>sociale omgeving</strong> een van de factoren die gezondheid beïnvloeden, naast biologische factoren, leefstijl, fysieke omgeving en gezondheidszorg.</p><p>Het gaat om sociale steun en netwerken, normen en gewoonten in de omgeving, opleiding, werk, inkomen en woonsituatie. Deze factoren verklaren een belangrijk deel van de sociaaleconomische gezondheidsverschillen.</p>","image_url":"","wiki_title":"","match":"sociale omgeving|sociale omgevingsfactoren","option_only":true},"fysieke omgeving":{"title":"Fysieke omgeving (determinant)","short":"De fysieke omgeving als gezondheidsdeterminant omvat de natuurlijke en gebouwde omgeving: lucht, water, geluid, woning en de inrichting van de wijk.","definition":"<p>In modellen van <strong>determinanten van gezondheid</strong> is de <strong>fysieke omgeving</strong> alles buiten de persoon dat niet sociaal is: luchtverontreiniging, waterkwaliteit, geluid, straling, de kwaliteit van de woning, en de inrichting van de omgeving (groen, fietspaden, voedselaanbod).</p><p>Deze factoren beïnvloeden gezondheid direct (bijv. fijnstof en longziekten) en indirect via gedrag (bijv. een beweegvriendelijke wijk).</p>","image_url":"","wiki_title":"","match":"fysieke omgeving|fysieke omgevingsfactoren|materiële omgeving","option_only":true},"secundaire preventie":{"title":"Secundaire preventie","short":"Secundaire preventie is het vroeg opsporen van een ziekte voordat er klachten zijn, zodat behandeling eerder kan beginnen, zoals bij bevolkingsonderzoek.","definition":"<p><strong>Secundaire preventie</strong> richt zich op het vroegtijdig opsporen van ziekte bij mensen zonder klachten, in een stadium waarin behandeling nog meer effect heeft. Voorbeelden zijn bevolkingsonderzoek naar borst-, baarmoederhals- en darmkanker, de hielprik en bloeddrukmetingen.</p><p>Primaire preventie voorkomt dat ziekte ontstaat (vaccinatie, stoppen met roken); tertiaire preventie beperkt de gevolgen van bestaande ziekte (revalidatie, voorkomen van complicaties).</p>","image_url":"","wiki_title":"","match":"secundaire preventie","option_only":true},"ziektepreventie":{"title":"Ziektepreventie","short":"Ziektepreventie omvat alle maatregelen om het ontstaan, de verergering of de gevolgen van ziekte te voorkomen.","definition":"<p><strong>Ziektepreventie</strong> wordt ingedeeld naar het moment van ingrijpen: <em>primair</em> (voorkomen dat ziekte ontstaat), <em>secundair</em> (vroege opsporing) en <em>tertiair</em> (gevolgen van ziekte beperken). Een andere indeling is naar doelgroep: universeel, selectief (risicogroepen), geïndiceerd (mensen met beginnende klachten) en zorggerelateerd.</p><p>Het is een onderdeel van gezondheidsbevordering, dat breder is en ook het versterken van gezondheid omvat.</p>","image_url":"","wiki_title":"","match":"ziektepreventie|preventie","option_only":true},"gezondheidsvoorlichting":{"title":"Gezondheidsvoorlichting","short":"Gezondheidsvoorlichting is het planmatig geven van informatie om kennis, houding en gedrag rond gezondheid te beïnvloeden.","definition":"<p><strong>Gezondheidsvoorlichting</strong> is een methode binnen gezondheidsbevordering. Het richt zich op het overdragen van kennis en het beïnvloeden van attitudes, zodat mensen gezondere keuzes maken — bijvoorbeeld campagnes over roken, alcohol of veilig vrijen.</p><p>Voorlichting alleen verandert gedrag vaak beperkt; het werkt beter in combinatie met maatregelen in de omgeving en regelgeving.</p>","image_url":"","wiki_title":"","match":"gezondheidsvoorlichting|voorlichting","option_only":true},"strafrechter":{"title":"Strafrechter","short":"De strafrechter beoordeelt of iemand een strafbaar feit heeft gepleegd en legt een straf op; het initiatief ligt bij het Openbaar Ministerie.","definition":"<p>Het <strong>strafrecht</strong> gaat over gedragingen die de wet strafbaar stelt, zoals mishandeling of dood door schuld. Het Openbaar Ministerie besluit of iemand wordt vervolgd; de <strong>strafrechter</strong> beslist over schuld en straf (bijv. geldboete, taakstraf, gevangenisstraf).</p><p>Het doel is vergelding en bescherming van de samenleving, niet het vergoeden van de schade aan het slachtoffer (al kan een slachtoffer zich in het strafproces voegen).</p>","image_url":"","wiki_title":"","match":"strafrechter|strafrecht","option_only":true},"bestuursrechter":{"title":"Bestuursrechter","short":"De bestuursrechter beoordeelt geschillen tussen burgers en de overheid, bijvoorbeeld over een besluit van een gemeente of ziektekostenregeling.","definition":"<p>De <strong>bestuursrechter</strong> beslist over geschillen tussen een burger (of bedrijf) en een <em>overheidsorgaan</em>. Het gaat om besluiten zoals een vergunning, een uitkering, een indicatie voor zorg (Wlz, Wmo) of een maatregel van de inspectie.</p><p>Voordat iemand naar de bestuursrechter kan, moet meestal eerst bezwaar worden gemaakt bij het bestuursorgaan zelf.</p>","image_url":"","wiki_title":"","match":"bestuursrechter|bestuursrecht","option_only":true},"binaire perceptie":{"title":"Binaire risicoperceptie","short":"Bij binaire risicoperceptie vertalen mensen een kans naar ‘het gebeurt wel’ of ‘het gebeurt niet’, in plaats van in percentages te denken.","definition":"<p>Bij <strong>binaire perceptie</strong> van risico denken mensen in twee categorieën: <em>ja of nee</em>, ‘ik krijg het’ of ‘ik krijg het niet’. Een kans van bijvoorbeeld 30% wordt dan niet als een getal ervaren, maar omgezet in een verwachting dat iets wel of niet zal gebeuren.</p><p>Het is een van de manieren waarop mensen in de praktijk met risico-informatie omgaan, naast heuristieken zoals de beschikbaarheids- en representativiteitsheuristiek.</p>","image_url":"","wiki_title":"","match":"binaire perceptie|binaire risicoperceptie","option_only":true},"astma":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma|asthma|astma bronchiale","option_only":true},"fibula":{"title":"Fibula","short":"De fibula (kuitbeen) is het dunne, laterale bot van het onderbeen; het draagt weinig gewicht maar vormt de laterale malleolus van de enkel.","definition":"<p>De <strong>fibula</strong> ligt lateraal van de tibia. Het caput fibulae articuleert met de tibia onder de knie, maar maakt geen deel uit van het kniegewricht. Distaal vormt de fibula de <em>malleolus lateralis</em>, onderdeel van de enkelvork.</p><p>Het bot is vooral een aanhechtingsplaats voor spieren en draagt weinig lichaamsgewicht. De n. fibularis communis loopt vlak om het collum fibulae heen en is daar kwetsbaar (klapvoet bij letsel of druk).</p>","image_url":"","wiki_title":"Fibula","match":"fibula|kuitbeen","option_only":true},"articulatio coxae":{"title":"Heupgewricht (articulatio coxae)","short":"Het heupgewricht is een kogelgewricht tussen de femurkop en het acetabulum van het bekken.","definition":"<p>De <strong>articulatio coxae</strong> verbindt de caput femoris met het acetabulum. Het diepe acetabulum, het labrum en sterke banden (lig. iliofemorale, pubofemorale en ischiofemorale) maken het een zeer stabiel gewricht. De femurkop wordt vooral doorbloed via de aa. circumflexae femoris; bij een mediale collumfractuur dreigt daardoor avasculaire necrose.</p>","image_url":"","wiki_title":"Hip","match":"articulatio coxae|heupgewricht","option_only":true},"tibia":{"title":"Tibia (scheenbeen)","short":"De tibia is het grote, gewichtdragende bot aan de mediale zijde van het onderbeen.","definition":"<p>De <strong>tibia</strong> vormt met de femur het kniegewricht (via de condylus medialis en lateralis van het tibiaplateau) en met de talus het bovenste spronggewricht; distaal vormt zij de malleolus medialis. De voorrand ligt direct onder de huid. Aan de tuberositas tibiae hecht de patellapees.</p>","image_url":"","wiki_title":"Tibia","match":"tibia|scheenbeen","option_only":true},"femur":{"title":"Femur (dijbeen)","short":"De femur is het langste en sterkste bot van het lichaam, tussen heup en knie.","definition":"<p>De <strong>femur</strong> heeft proximaal de femurkop, het collum en de trochanter major en minor, en distaal de condylus medialis en lateralis. Het collum maakt een hoek met de schacht (collodiafysaire hoek). Collumfracturen komen veel voor bij ouderen met osteoporose; de bloedvoorziening van de kop kan daarbij in gevaar komen.</p>","image_url":"","wiki_title":"Femur","match":"femur|dijbeen","option_only":true},"ulna":{"title":"Ulna (ellepijp)","short":"De ulna is het mediale bot van de onderarm (aan de pinkzijde); proximaal vormt het de punt van de elleboog.","definition":"<p>De <strong>ulna</strong> heeft proximaal het olecranon en het processus coronoideus, die samen de incisura trochlearis vormen voor het scharniergewricht met de humerus. Distaal heeft zij een kop en een processus styloideus. Samen met de radius maakt zij pro- en supinatie mogelijk via de proximale en distale radio-ulnaire gewrichten.</p>","image_url":"","wiki_title":"Ulna","match":"ulna|ellepijp","option_only":true},"radius":{"title":"Radius (spaakbeen)","short":"De radius is het laterale bot van de onderarm (aan de duimzijde) dat distaal het grootste deel van het polsgewricht vormt.","definition":"<p>De <strong>radius</strong> heeft proximaal een schijfvormige kop die draait in het lig. anulare, en distaal een brede basis die articuleert met de handwortel. Bij pronatie draait de radius om de ulna heen. Een distale radiusfractuur is een van de meest voorkomende fracturen, vaak na een val op de uitgestrekte hand.</p>","image_url":"","wiki_title":"Radius (bone)","match":"radius|spaakbeen","option_only":true},"os lunatum":{"title":"Os lunatum","short":"Het os lunatum is het maanvormige handwortelbeentje in het midden van de proximale rij.","definition":"<p>Het <strong>os lunatum</strong> ligt tussen het os scaphoideum en het os triquetrum en articuleert met de radius. Het kan na een hyperextensietrauma naar palmair luxeren en dan de n. medianus in de carpale tunnel comprimeren. Avasculaire necrose van het lunatum heet de ziekte van Kienböck.</p>","image_url":"","wiki_title":"Lunate bone","match":"os lunatum|maanvormig been","option_only":true},"os pisiforme":{"title":"Os pisiforme","short":"Het os pisiforme is een klein, erwtvormig handwortelbeentje aan de pinkzijde, een sesambeen in de pees van de m. flexor carpi ulnaris.","definition":"<p>Het <strong>os pisiforme</strong> ligt palmair op het os triquetrum en is goed voelbaar aan de ulnaire zijde van de pols. Het is een sesambeentje in de pees van de m. flexor carpi ulnaris en vormt een begrenzing van het kanaal van Guyon, waardoor de n. en a. ulnaris lopen.</p>","image_url":"","wiki_title":"Pisiform bone","match":"os pisiforme|erwtvormig been","option_only":true},"os hamatum":{"title":"Os hamatum","short":"Het os hamatum is een handwortelbeentje in de distale rij aan de pinkzijde, met een haakvormig uitsteeksel (hamulus).","definition":"<p>Het <strong>os hamatum</strong> articuleert met de vierde en vijfde middenhandsbeentjes. De <em>hamulus</em> is een aanhechtingspunt voor het retinaculum flexorum en begrenst het kanaal van Guyon. Een fractuur van de hamulus komt voor bij golf-, tennis- en honkbalspelers.</p>","image_url":"","wiki_title":"Hamate bone","match":"os hamatum|haakvormig been","option_only":true},"os sacrum":{"title":"Os sacrum (heiligbeen)","short":"Het os sacrum is het driehoekige bot uit vijf vergroeide sacrale wervels dat de achterwand van het bekken vormt.","definition":"<p>Het <strong>os sacrum</strong> articuleert boven met de vijfde lendenwervel, aan beide zijden met de ossa ilia (sacro-iliacale gewrichten) en onder met het stuitbeen. Door de foramina sacralia treden de sacrale zenuwen uit. Het promontorium is een belangrijk oriëntatiepunt in de verloskunde.</p>","image_url":"","wiki_title":"Sacrum","match":"os sacrum|heiligbeen|sacrum","option_only":true},"os cuneiforme":{"title":"Os cuneiforme","short":"De ossa cuneiformia zijn drie wigvormige voetwortelbeentjes tussen het os naviculare en de eerste drie middenvoetsbeentjes.","definition":"<p>Er zijn drie <strong>ossa cuneiformia</strong> (mediale, intermediale en laterale). Door hun wigvorm helpen ze de dwarse voetboog te vormen. Ze articuleren met het os naviculare, met elkaar, met het os cuboideum en met de basis van metatarsale I–III (onderdeel van het gewricht van Lisfranc).</p>","image_url":"","wiki_title":"Cuneiform bones","match":"os cuneiforme|ossa cuneiformia|wigvormig been","option_only":true},"a. femoralis":{"title":"A. femoralis","short":"De a. femoralis is de grote slagader van het bovenbeen, de voortzetting van de a. iliaca externa onder het ligamentum inguinale.","definition":"<p>De <strong>a. femoralis</strong> loopt vanaf het ligamentum inguinale door de trigonum femorale, lateraal van de v. femoralis en mediaal van de n. femoralis. In de lies is de pols goed voelbaar. Ze geeft de a. profunda femoris af en loopt verder door het kanaal van Hunter, waarna ze in de knieholte a. poplitea heet. Ze wordt gebruikt als toegang voor katheterisaties.</p>","image_url":"","wiki_title":"Femoral artery","match":"a. femoralis|arteria femoralis","option_only":true},"a. iliaca communis":{"title":"A. iliaca communis","short":"De aa. iliacae communes ontstaan uit de splitsing van de aorta abdominalis ter hoogte van L4.","definition":"<p>De <strong>a. iliaca communis</strong> loopt aan weerszijden schuin naar beneden en splitst zich ter hoogte van het sacro-iliacale gewricht in de a. iliaca externa (naar het been) en de a. iliaca interna (naar het bekken). De ureter kruist de iliacale vaten ongeveer bij deze splitsing.</p>","image_url":"","wiki_title":"Common iliac artery","match":"a. iliaca communis|arteria iliaca communis","option_only":true},"a. iliaca interna":{"title":"A. iliaca interna","short":"De a. iliaca interna voorziet de bekkenorganen, de bilspieren en het perineum van bloed.","definition":"<p>De <strong>a. iliaca interna</strong> ontstaat uit de a. iliaca communis en loopt het kleine bekken in. Ze heeft een voorste en achterste stam, met takken naar blaas, uterus (a. uterina), rectum, bilspieren (aa. gluteae) en perineum (a. pudenda interna). Bij de foetus lopen de navelarteriën vanuit deze arterie naar de placenta.</p>","image_url":"","wiki_title":"Internal iliac artery","match":"a. iliaca interna|arteria iliaca interna|a. hypogastrica","option_only":true},"m. deltoideus":{"title":"M. deltoideus","short":"De m. deltoideus is de driehoekige schouderspier die de arm abduceert; geïnnerveerd door de n. axillaris.","definition":"<p>De <strong>m. deltoideus</strong> ontspringt van de clavicula, het acromion en de spina scapulae en hecht aan op de tuberositas deltoidea van de humerus. Het middelste deel abduceert de arm (vooral boven ±15°), het voorste deel helpt bij anteflexie en endorotatie, het achterste deel bij retroflexie en exorotatie. Innervatie: n. axillaris (C5–C6).</p>","image_url":"","wiki_title":"Deltoid muscle","match":"m. deltoideus|musculus deltoideus|deltaspier","option_only":true},"m. pectoralis minor":{"title":"M. pectoralis minor","short":"De m. pectoralis minor is een dunne borstspier die van de ribben naar het processus coracoideus loopt en de scapula naar voren-onder trekt.","definition":"<p>De <strong>m. pectoralis minor</strong> ontspringt van ribben 3–5 en hecht aan het processus coracoideus. Hij stabiliseert de scapula tegen de thorax en helpt bij geforceerde inademing. De spier ligt over de a. axillaris en verdeelt die in drie delen. Innervatie: n. pectoralis medialis.</p>","image_url":"","wiki_title":"Pectoralis minor","match":"m. pectoralis minor|musculus pectoralis minor|kleine borstspier","option_only":true},"m. subclavius":{"title":"M. subclavius","short":"De m. subclavius is een kleine spier onder de clavicula die het sternoclaviculaire gewricht stabiliseert.","definition":"<p>De <strong>m. subclavius</strong> loopt van de eerste rib naar de onderzijde van de clavicula. Hij trekt de clavicula naar mediaal-beneden en stabiliseert zo het sternoclaviculaire gewricht. Bij een claviculafractuur beschermt hij enigszins de onderliggende vaten en de plexus brachialis. Innervatie: n. subclavius (C5–C6).</p>","image_url":"","wiki_title":"Subclavius muscle","match":"m. subclavius|musculus subclavius","option_only":true},"m. latissimus dorsi":{"title":"M. latissimus dorsi","short":"De m. latissimus dorsi is de brede rugspier die de arm adduceert, endoroteert en naar achteren trekt.","definition":"<p>De <strong>m. latissimus dorsi</strong> ontspringt van de onderste borst- en lendenwervels, de fascia thoracolumbalis, de crista iliaca en de onderste ribben, en hecht aan in de bodem van de sulcus intertubercularis van de humerus. Hij is belangrijk bij klimmen, roeien en zwemmen. Innervatie: n. thoracodorsalis (C6–C8).</p>","image_url":"","wiki_title":"Latissimus dorsi muscle","match":"m. latissimus dorsi|musculus latissimus dorsi|brede rugspier","option_only":true},"m. levator scapulae":{"title":"M. levator scapulae","short":"De m. levator scapulae heft de scapula en kantelt haar; hij loopt van de bovenste halswervels naar de bovenhoek van de scapula.","definition":"<p>De <strong>m. levator scapulae</strong> ontspringt van de processus transversi van C1–C4 en hecht aan de angulus superior en de mediale rand van de scapula. Hij heft het schouderblad en draait de cavitas glenoidalis naar beneden; bij een gefixeerde scapula buigt hij de nek opzij. Innervatie: n. dorsalis scapulae en cervicale takken.</p>","image_url":"","wiki_title":"Levator scapulae muscle","match":"m. levator scapulae|musculus levator scapulae","option_only":true},"pees van de m. supraspinatus":{"title":"Pees van de m. supraspinatus","short":"De m. supraspinatus is een rotatorcuffspier die de abductie van de arm inzet; de pees loopt onder het acromion door.","definition":"<p>De <strong>m. supraspinatus</strong> ligt in de fossa supraspinata van de scapula en hecht via een pees aan op de bovenkant van het tuberculum majus. Hij start de abductie en drukt de humeruskop in de kom. Omdat de pees door de nauwe subacromiale ruimte loopt, raakt deze vaak geïrriteerd of gescheurd (impingement, cuffruptuur). Innervatie: n. suprascapularis.</p>","image_url":"","wiki_title":"Supraspinatus muscle","match":"pees van de m. supraspinatus|m. supraspinatus|supraspinatuspees","option_only":true},"pees van de m. infraspinatus":{"title":"Pees van de m. infraspinatus","short":"De m. infraspinatus is een rotatorcuffspier aan de achterkant van de scapula die de arm naar buiten draait.","definition":"<p>De <strong>m. infraspinatus</strong> ligt in de fossa infraspinata en hecht aan het middelste facet van het tuberculum majus. Het is de belangrijkste exorotator van de schouder en stabiliseert samen met de andere cuffspieren de humeruskop. Innervatie: n. suprascapularis.</p>","image_url":"","wiki_title":"Infraspinatus muscle","match":"pees van de m. infraspinatus|m. infraspinatus|infraspinatuspees","option_only":true},"n. cutaneus antebrachii medialis":{"title":"N. cutaneus antebrachii medialis","short":"De n. cutaneus antebrachii medialis is een sensibele zenuw uit de fasciculus medialis voor de huid van de mediale onderarm.","definition":"<p>De <strong>n. cutaneus antebrachii medialis</strong> (C8–T1) komt rechtstreeks uit de fasciculus medialis van de plexus brachialis. Hij loopt met de v. basilica mee en verzorgt de huid aan de mediale (ulnaire) zijde van de onderarm tot de pols. Het is een zuiver sensibele zenuw.</p>","image_url":"","wiki_title":"Medial cutaneous nerve of forearm","match":"n. cutaneus antebrachii medialis","option_only":true},"syfilis":{"title":"Syfilis (lues)","short":"Syfilis is een seksueel overdraagbare infectie door Treponema pallidum, die in stadia verloopt.","definition":"<p><strong>Syfilis</strong> begint (primair) met een pijnloos ulcus (sjanker) op de plek van besmetting. Weken later volgt het secundaire stadium met huiduitslag (ook op handpalmen en voetzolen), condylomata lata en algemene klachten. Na een latente fase kan na jaren tertiaire syfilis ontstaan (gummata, cardiovasculaire en neurosyfilis). Congenitale syfilis wordt voorkomen door screening in de zwangerschap.</p>","image_url":"","wiki_title":"Syphilis","match":"syfilis|lues|syphilis","option_only":true},"hiv":{"title":"Hiv (humaan immunodeficiëntievirus)","short":"Hiv is een retrovirus dat CD4-T-helpercellen infecteert; zonder behandeling ontstaat aids.","definition":"<p><strong>Hiv</strong> bindt met gp120 aan CD4 en een co-receptor (CCR5 of CXCR4), schrijft zijn RNA via reverse transcriptase om naar DNA en bouwt dat in het genoom in. Het aantal CD4-cellen daalt geleidelijk; onder ±200/µl ontstaan opportunistische infecties en tumoren (aids). Overdracht via seks, bloed en van moeder op kind. Combinatietherapie (cART) onderdrukt het virus volledig.</p>","image_url":"","wiki_title":"HIV","match":"hiv|humaan immunodeficiëntievirus|aids","option_only":true},"ebola":{"title":"Ebola","short":"Ebola is een zeer ernstige virale hemorragische koorts, overgedragen via lichaamsvloeistoffen van besmette mensen of dieren.","definition":"<p>Het <strong>ebolavirus</strong> is een filovirus. Na 2–21 dagen ontstaan koorts, zwakte, spierpijn, braken en diarree; in een deel van de gevallen volgen bloedingen en multi-orgaanfalen. De sterfte is hoog. Overdracht gebeurt via direct contact met bloed en lichaamsvloeistoffen, ook van overledenen; strikte isolatie is nodig. Er is inmiddels een vaccin tegen het Zaïre-type.</p>","image_url":"","wiki_title":"Ebola","match":"ebola|ebolavirus|ebolakoorts","option_only":true},"vaccinatie":{"title":"Vaccinatie","short":"Vaccinatie is het toedienen van een antigeen om een beschermende, langdurige afweerreactie op te wekken zonder de ziekte door te maken.","definition":"<p>Bij <strong>actieve immunisatie</strong> wordt een verzwakt of gedood micro-organisme, een onderdeel ervan (eiwit, polysacharide, toxoïd) of een mRNA/vector die het antigeen laat aanmaken toegediend. Het lichaam maakt geheugen-B- en T-cellen. Voldoende vaccinatiegraad geeft ook groepsimmuniteit. Passieve immunisatie (antistoffen toedienen) geeft directe maar tijdelijke bescherming.</p>","image_url":"","wiki_title":"Vaccination","match":"vaccinatie|vaccin|vaccineren|immunisatie","option_only":true},"copd":{"title":"COPD","short":"COPD is een chronische longziekte met niet volledig omkeerbare luchtwegobstructie, meestal door roken.","definition":"<p>Bij <strong>COPD</strong> leiden chronische ontsteking van de kleine luchtwegen en afbraak van alveolewanden (emfyseem) tot een blijvende obstructie: FEV1/FVC &lt; 0,7 na bronchodilatatie. Klachten zijn kortademigheid bij inspanning, chronische hoest en sputum, met periodes van verergering (exacerbaties). Belangrijkste behandeling: stoppen met roken, luchtwegverwijders, beweegprogramma's en vaccinaties.</p>","image_url":"","wiki_title":"Chronic obstructive pulmonary disease","match":"copd|chronic obstructive pulmonary disease|chronisch obstructieve longziekte","option_only":true},"overgewicht":{"title":"Overgewicht","short":"Overgewicht is een te hoog lichaamsgewicht ten opzichte van de lengte, gedefinieerd als een BMI tussen 25 en 30 kg/m².","definition":"<p>Bij <strong>overgewicht</strong> (BMI 25–30) en vooral bij obesitas (BMI ≥30) neemt het risico op diabetes type 2, hart- en vaatziekten, artrose en sommige kankers toe. De verdeling van het vet is belangrijk: buikvet (gemeten met de middelomtrek) is metabool ongunstiger dan vet op heupen en bovenbenen.</p>","image_url":"","wiki_title":"Overweight","match":"overgewicht","option_only":true},"mri":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri|mri-scan|magnetic resonance imaging","option_only":true},"reumatoïde artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoïde artritis|reumatoide artritis|reumatoïde arthritis","option_only":true},"artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"artritis|arthritis|gewrichtsontsteking","option_only":true},"bursitis":{"title":"Bursitis","short":"Bursitis is een ontsteking van een slijmbeurs, bijvoorbeeld bij elleboog, knie of heup.","definition":"<p>Een <strong>bursa</strong> is een met vocht gevuld zakje dat wrijving tussen pees, spier, bot en huid vermindert. <strong>Bursitis</strong> ontstaat door overbelasting, druk, trauma, jicht of infectie. Oppervlakkige bursae (bij olecranon en patella) zwellen zichtbaar op; bij een rood, warm en pijnlijk beeld moet aan een septische bursitis worden gedacht.</p>","image_url":"","wiki_title":"Bursitis","match":"bursitis|slijmbeursontsteking","option_only":true},"polymyalgia reumatica":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica|polymyalgia rheumatica|pmr","option_only":true},"contemplatie":{"title":"Contemplatie (stages of change)","short":"Contemplatie is de fase in het model van Prochaska en DiClemente waarin iemand overweegt het gedrag te veranderen, maar nog twijfelt.","definition":"<p>In het <strong>transtheoretisch model</strong> volgt contemplatie op precontemplatie. De persoon ziet de nadelen van het huidige gedrag, maar weegt die af tegen de voordelen; er is ambivalentie. Een arts kan in deze fase helpen de voor- en nadelen te verkennen, bijvoorbeeld met motiverende gespreksvoering. Daarna volgen preparatie, actie en gedragsbehoud.</p>","image_url":"","wiki_title":"Transtheoretical model","match":"contemplatie","option_only":true},"precontemplatie":{"title":"Precontemplatie (stages of change)","short":"Precontemplatie is de eerste fase in het transtheoretisch model van gedragsverandering (Prochaska en DiClemente).","definition":"<p>Het <strong>transtheoretisch model</strong> beschrijft de fasen precontemplatie, contemplatie, preparatie, actie en gedragsbehoud; terugval kan op elk moment optreden. In de fase van precontemplatie ziet de persoon (nog) geen reden om het eigen gedrag te veranderen. Een arts richt zich in deze fase vooral op informeren en bewustwording.</p>","image_url":"","wiki_title":"Transtheoretical model","match":"precontemplatie","option_only":true},"diagnose-recept model":{"title":"Diagnose-receptmodel","short":"Het diagnose-receptmodel is een arts-gecentreerde manier van consultvoeren waarin de arts diagnose en behandeling bepaalt.","definition":"<p>In het <strong>diagnose-receptmodel</strong> stelt de arts vragen, onderzoekt, stelt een diagnose en schrijft een behandeling voor; de patiënt heeft een vooral passieve rol. Het staat tegenover patiëntgerichte modellen zoals gedeelde besluitvorming, waarin de waarden en voorkeuren van de patiënt meewegen.</p>","image_url":"","wiki_title":"","match":"diagnose-recept model|diagnose-receptmodel|paternalistisch model","option_only":true},"informed decision making model":{"title":"Informed decision making-model","short":"In het informed decision making-model geeft de arts alle informatie en neemt de patiënt zelf de beslissing.","definition":"<p>Bij <strong>informed decision making</strong> is de arts vooral informatieverstrekker en ligt de beslissing volledig bij de goed geïnformeerde patiënt. Het staat tussen het paternalistische model (de arts beslist) en gedeelde besluitvorming (arts en patiënt beslissen samen na uitwisseling van informatie en voorkeuren).</p>","image_url":"","wiki_title":"","match":"informed decision making model|informed decision making|geïnformeerde besluitvorming","option_only":true},"capability model":{"title":"Capability-model","short":"Het capability-model kijkt bij werk en gezondheid naar wat iemand waardevol vindt en wat hij of zij daadwerkelijk kan realiseren.","definition":"<p>Het <strong>capability-model</strong> (Sen, Nussbaum) gaat niet alleen uit van beperkingen, maar van de mogelijkheden en waarden van een persoon. In de arbeids- en verzekeringsgeneeskunde wordt het gebruikt om samen met de werknemer te bepalen welke aspecten van werk belangrijk zijn en wat nodig is om die te realiseren.</p>","image_url":"","wiki_title":"","match":"capability model|capability-benadering","option_only":true},"medisch tuchtcollege":{"title":"Medisch tuchtcollege","short":"Het tuchtcollege beoordeelt of een BIG-geregistreerde zorgverlener zich heeft gehouden aan de normen voor goede beroepsuitoefening.","definition":"<p>Het <strong>tuchtrecht</strong> in de gezondheidszorg is geregeld in de Wet BIG. Klagers (patiënten, nabestaanden, de inspectie) kunnen een klacht indienen tegen een individuele zorgverlener. Het doel is de kwaliteit van de beroepsuitoefening te bewaken; het college kan maatregelen opleggen, van een waarschuwing tot doorhaling van de registratie, maar kent geen schadevergoeding toe.</p>","image_url":"","wiki_title":"","match":"medisch tuchtcollege|tuchtcollege|tuchtrechter|tuchtrecht","option_only":true},"klachtencommissie":{"title":"Klachtencommissie","short":"Een klachtencommissie behandelt klachten van patiënten over een zorginstelling of zorgverlener, als laagdrempelige route.","definition":"<p>Op grond van de Wet kwaliteit, klachten en geschillen zorg (Wkkgz) moet elke zorgaanbieder een <strong>klachtenregeling</strong> hebben met een klachtenfunctionaris en aansluiting bij een geschillencommissie. Het doel is vooral het herstellen van de relatie en het verbeteren van de zorg; een geschillencommissie kan een (beperkte) schadevergoeding toekennen.</p>","image_url":"","wiki_title":"","match":"klachtencommissie|klachtenfunctionaris","option_only":true},"gezondheidsraad (gr)":{"title":"Gezondheidsraad","short":"De Gezondheidsraad is een onafhankelijk wetenschappelijk adviesorgaan dat de regering en het parlement adviseert over volksgezondheid.","definition":"<p>De <strong>Gezondheidsraad</strong> brengt gevraagd en ongevraagd advies uit op basis van de stand van de wetenschap, bijvoorbeeld over vaccinaties, bevolkingsonderzoeken, voedingsrichtlijnen en beweegrichtlijnen. De overheid beslist daarna zelf over beleid.</p>","image_url":"","wiki_title":"","match":"gezondheidsraad (gr)|gezondheidsraad","option_only":true},"zorginstituut nederland (zin)":{"title":"Zorginstituut Nederland","short":"Zorginstituut Nederland beoordeelt welke zorg in het basispakket hoort en bevordert de kwaliteit van de zorg.","definition":"<p><strong>Zorginstituut Nederland</strong> is een zelfstandig bestuursorgaan. Het adviseert over de inhoud van het verzekerde pakket (pakketbeheer), beheert kwaliteitsstandaarden en voert de financiering van de risicoverevening tussen zorgverzekeraars uit.</p>","image_url":"","wiki_title":"","match":"zorginstituut nederland (zin)|zorginstituut nederland","option_only":true},"wmo":{"title":"Wet maatschappelijke ondersteuning (Wmo)","short":"De Wmo maakt gemeenten verantwoordelijk voor ondersteuning, zelfredzaamheid en participatie van hun inwoners.","definition":"<p>De <strong>Wet maatschappelijke ondersteuning</strong> regelt dat gemeenten zorgen voor ondersteuning van burgers die dat nodig hebben om zelfstandig te wonen en mee te doen, zoals huishoudelijke hulp, woningaanpassingen, begeleiding, mantelzorgondersteuning en maatschappelijke opvang.</p>","image_url":"","wiki_title":"","match":"wmo|wet maatschappelijke ondersteuning","option_only":true},"participatiewet":{"title":"Participatiewet","short":"De Participatiewet regelt via de gemeente bijstand en ondersteuning naar werk voor mensen die kunnen werken maar dat zonder hulp niet lukt.","definition":"<p>De <strong>Participatiewet</strong> (2015) verving o.a. de Wet werk en bijstand en een deel van de Wajong. Gemeenten zijn verantwoordelijk voor de bijstandsuitkering en voor het begeleiden van mensen met een afstand tot de arbeidsmarkt naar (beschut of regulier) werk.</p>","image_url":"","wiki_title":"","match":"participatiewet","option_only":true},"civiele rechter":{"title":"Civiele rechter","short":"De civiele rechter beslecht geschillen tussen burgers en/of organisaties, zoals over aansprakelijkheid en schadevergoeding.","definition":"<p>De <strong>civiele rechter</strong> behandelt privaatrechtelijke geschillen. De procedure start op initiatief van een partij. Daarnaast bestaan de strafrechter (strafbare feiten), de bestuursrechter (geschillen met de overheid) en in de zorg het tuchtrecht, elk met een eigen doel.</p>","image_url":"","wiki_title":"","match":"civiele rechter|civiel recht","option_only":true},"een sociaal verzekeringsstelsel":{"title":"Sociaal verzekeringsstelsel (Bismarck)","short":"Een sociaal verzekeringsstelsel financiert de zorg via verplichte, inkomensafhankelijke premies aan verzekeraars of fondsen.","definition":"<p>Bij een <strong>sociaal verzekeringsstelsel</strong> (Bismarckmodel, bijv. Duitsland, Nederland) betalen werkgevers en werknemers verplichte premies; zorg wordt vaak door private aanbieders geleverd. Het staat tegenover een genationaliseerd stelsel (Beveridgemodel), dat via belastingen wordt gefinancierd met overheidsaanbieders.</p>","image_url":"","wiki_title":"","match":"een sociaal verzekeringsstelsel|sociaal verzekeringsstelsel|bismarckmodel","option_only":true},"een genationaliseerd stelsel":{"title":"Genationaliseerd zorgstelsel (Beveridge)","short":"Een genationaliseerd zorgstelsel wordt gefinancierd uit belastingen en de zorg wordt grotendeels door de overheid geleverd.","definition":"<p>Bij een <strong>genationaliseerd stelsel</strong> (Beveridgemodel, bijv. de NHS in het Verenigd Koninkrijk) is zorg in principe voor iedereen toegankelijk en grotendeels gratis bij gebruik. De overheid bepaalt het budget en organiseert de zorg; wachtlijsten zijn een bekend nadeel.</p>","image_url":"","wiki_title":"","match":"een genationaliseerd stelsel|genationaliseerd stelsel|beveridgemodel|nationale gezondheidsdienst","option_only":true},"sociaal-culturele omgeving":{"title":"Sociaal-culturele omgeving","short":"De sociaal-culturele omgeving omvat normen, waarden, gewoonten en sociale netwerken die gezondheid en gedrag beïnvloeden.","definition":"<p>In modellen van <strong>determinanten van gezondheid</strong> gaat het bij de sociaal-culturele omgeving om sociale steun, de invloed van familie en vrienden, groepsnormen, religie en culturele gewoonten (bijv. rond voeding, alcohol of hulp zoeken).</p>","image_url":"","wiki_title":"","match":"sociaal-culturele omgeving|sociaal culturele omgeving","option_only":true},"economische omgeving":{"title":"Economische omgeving","short":"De economische omgeving omvat factoren zoals inkomen, werkgelegenheid, prijzen en armoede die gezondheid beïnvloeden.","definition":"<p>De <strong>economische omgeving</strong> bepaalt mede welke keuzes mensen kunnen maken, bijvoorbeeld via de prijs van gezond voedsel en tabak, werkloosheid en schulden. Een lage sociaaleconomische status hangt samen met een kortere (gezonde) levensverwachting.</p>","image_url":"","wiki_title":"","match":"economische omgeving","option_only":true},"politieke omgeving":{"title":"Politieke omgeving","short":"De politieke omgeving omvat wetten, regels en beleid die gezondheid beïnvloeden, zoals accijnzen, rookverboden en zorgfinanciering.","definition":"<p>De <strong>politieke omgeving</strong> is een determinant van gezondheid op macroniveau. Voorbeelden zijn tabaks- en alcoholwetgeving, verkeersveiligheid, arbeidsomstandigheden, sociale zekerheid en de organisatie en toegankelijkheid van de gezondheidszorg.</p>","image_url":"","wiki_title":"","match":"politieke omgeving","option_only":true},"prostaatcarcinoom":{"title":"Prostaatcarcinoom","short":"Het prostaatcarcinoom is een kwaadaardige tumor van de prostaat, meestal een adenocarcinoom uitgaand van de perifere zone.","definition":"<p><strong>Prostaatkanker</strong> komt vooral voor bij oudere mannen en groeit vaak langzaam. Vroege stadia geven meestal geen klachten; gevorderde stadia kunnen plasklachten en botmetastasen (botpijn) geven. Diagnostiek met rectaal toucher, PSA, MRI en biopten (Gleason-score). Behandeling varieert van actief volgen tot operatie, radiotherapie en hormonale therapie.</p>","image_url":"","wiki_title":"Prostate cancer","match":"prostaatcarcinoom|prostaatkanker","option_only":true},"iliotibiaal frictiesyndroom":{"title":"Iliotibiaal frictiesyndroom","short":"Bij het iliotibiaal frictiesyndroom ontstaat pijn aan de buitenkant van de knie door wrijving van de tractus iliotibialis over de laterale femurcondyl.","definition":"<p>Het <strong>iliotibiaal frictiesyndroom</strong> is een overbelastingsblessure, vooral bij hardlopers en fietsers. De pijn zit lateraal boven het kniegewricht en neemt toe tijdens het lopen, vooral bergaf. Er is drukpijn op de laterale epicondyl. Behandeling: belasting aanpassen, rekken en versterken van de heupspieren.</p>","image_url":"","wiki_title":"Iliotibial band syndrome","match":"iliotibiaal frictiesyndroom|itbs|runner's knee","option_only":true},"carpaal tunnel syndroom":{"title":"Carpaletunnelsyndroom","short":"Bij het carpaletunnelsyndroom is de n. medianus bekneld in de carpale tunnel, met tintelingen in duim, wijs- en middelvinger.","definition":"<p>Het <strong>carpaletunnelsyndroom</strong> is de meest voorkomende zenuwbeknelling. Klachten: tintelingen en doofheid in het gebied van de n. medianus, vaak ’s nachts, verbeterend door schudden met de hand; later zwakte en atrofie van de duimmuis. Risicofactoren zijn zwangerschap, diabetes, hypothyreoïdie, reumatoïde artritis en repetitieve bewegingen. Behandeling met spalk, injectie of klieving van het lig. carpi transversum.</p>","image_url":"","wiki_title":"Carpal tunnel syndrome","match":"carpaal tunnel syndroom|carpaletunnelsyndroom|cts","option_only":true},"n. medianus":{"title":"N. medianus","short":"De n. medianus (C6–T1) loopt door de carpale tunnel en innerveert o.a. de duimmuis en het gevoel van duim, wijs- en middelvinger.","definition":"<p>De <strong>n. medianus</strong> ontstaat uit de fasciculus lateralis en medialis van de plexus brachialis. Hij innerveert de meeste flexoren van de onderarm, de spieren van de duimmuis en de laterale mm. lumbricales, en sensibel de palmaire zijde van duim, wijs-, middel- en de radiale helft van de ringvinger. Bij een hoog letsel ontstaat een ‘eedhand’.</p>","image_url":"","wiki_title":"Median nerve","match":"n. medianus|nervus medianus","option_only":true},"n. thoracicus longus":{"title":"N. thoracicus longus","short":"De n. thoracicus longus (C5–C7) innerveert de m. serratus anterior.","definition":"<p>De <strong>n. thoracicus longus</strong> loopt over de laterale borstwand naar beneden, oppervlakkig op de m. serratus anterior. Daardoor is hij kwetsbaar bij okselklierdissectie, trauma en zware belasting van de schouder. Uitval geeft een scapula alata, vooral zichtbaar bij duwen tegen een muur.</p>","image_url":"","wiki_title":"Long thoracic nerve","match":"n. thoracicus longus|nervus thoracicus longus","option_only":true},"os scaphoideum":{"title":"Os scaphoideum","short":"Het os scaphoideum is het bootvormige handwortelbeentje aan de duimzijde van de proximale rij.","definition":"<p>Het <strong>os scaphoideum</strong> overbrugt de proximale en distale handwortelrij en breekt vaak na een val op de uitgestrekte hand. Omdat de bloedvoorziening van distaal naar proximaal loopt, kan het proximale fragment na een fractuur afsterven (avasculaire necrose) en ontstaat gemakkelijk een pseudartrose. Een fractuur is op de eerste foto soms niet zichtbaar.</p>","image_url":"","wiki_title":"Scaphoid bone","match":"os scaphoideum|scafoïd|naviculare van de hand","option_only":true},"inversie":{"title":"Inversie (voet)","short":"Inversie is het kantelen van de voetzool naar binnen (mediaal); de tegenovergestelde beweging is eversie.","definition":"<p><strong>Inversie</strong> vindt vooral plaats in het onderste spronggewricht (subtalair) en de gewrichten van de middenvoet. Ze maakt deel uit van supinatie (inversie, adductie en plantairflexie). Een inversietrauma (omslaan van de enkel) belast vooral de laterale enkelbanden.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"inversie","option_only":true},"concentrische contractie":{"title":"Concentrische contractie","short":"Bij een concentrische contractie verkort de spier terwijl hij kracht levert, bijvoorbeeld de biceps bij het optillen van een gewicht.","definition":"<p>Bij <strong>concentrische</strong> spierarbeid is de spierkracht groter dan de externe belasting en verkort de spier. Bij <em>excentrische</em> arbeid verlengt de spier onder spanning (bijv. remmend bij het neerzetten van een gewicht); dat geeft de meeste spierpijn. Bij <em>isometrische</em> arbeid blijft de lengte gelijk.</p>","image_url":"","wiki_title":"Muscle contraction","match":"concentrische contractie|concentrische spierwerking","option_only":true},"isometrische contracie":{"title":"Isometrische contractie","short":"Bij een isometrische contractie ontwikkelt de spier kracht zonder van lengte te veranderen, bijvoorbeeld bij het vasthouden van een houding.","definition":"<p>Bij <strong>isometrische</strong> spierarbeid is de spierkracht even groot als de externe belasting, zodat er geen beweging ontstaat. Voorbeelden zijn duwen tegen een muur of een houding vasthouden. Het geeft een flinke stijging van de bloeddruk.</p>","image_url":"","wiki_title":"Muscle contraction","match":"isometrische contracie|isometrische contractie|isometrische spierwerking","option_only":true},"arthrodese":{"title":"Artrodese","short":"Een artrodese is het operatief vastzetten van een gewricht, zodat de botten aan elkaar vastgroeien.","definition":"<p>Bij een <strong>artrodese</strong> worden de gewrichtsvlakken verwijderd en de botten in een functionele stand gefixeerd tot ze vergroeien. Het gewricht wordt daardoor pijnvrij en stabiel, maar verliest zijn beweeglijkheid. Het wordt o.a. toegepast bij ernstige artrose of instabiliteit van enkel, pols, duim of wervelkolom.</p>","image_url":"","wiki_title":"Arthrodesis","match":"arthrodese|artrodese|gewrichtsfusie","option_only":true},"tibiafractuur":{"title":"Tibiafractuur","short":"Een tibiafractuur is een breuk van het scheenbeen, vaak door hoog-energetisch trauma.","definition":"<p>Omdat de voorzijde van de tibia direct onder de huid ligt, zijn <strong>tibiafracturen</strong> relatief vaak open. Ze hebben een verhoogd risico op een compartimentsyndroom (toenemende pijn, vooral bij passief rekken) en vertraagde genezing door de beperkte bekleding met weke delen.</p>","image_url":"","wiki_title":"Tibial fracture","match":"tibiafractuur|scheenbeenbreuk","option_only":true},"calcaneusfractuur":{"title":"Calcaneusfractuur","short":"Een calcaneusfractuur is een breuk van het hielbeen, meestal na een val van hoogte op de voeten.","definition":"<p>Bij een <strong>calcaneusfractuur</strong> wordt de calcaneus door de talus ingedrukt. Er zijn vaak bijkomende letsels, zoals wervelfracturen (axiale belasting) of een fractuur van de andere hiel. Er is risico op een compartimentsyndroom van de voet en later artrose van het subtalaire gewricht.</p>","image_url":"","wiki_title":"Calcaneal fracture","match":"calcaneusfractuur|hielbeenbreuk","option_only":true},"patellafractuur":{"title":"Patellafractuur","short":"Een patellafractuur is een breuk van de knieschijf, door een directe val op de knie of door een krachtige contractie van de m. quadriceps.","definition":"<p>Bij een <strong>patellafractuur</strong> is de strekfunctie van de knie vaak gestoord als het strekapparaat is doorbroken. Een dislocatie van de fragmenten wordt operatief gefixeerd (bijv. met tension-band-wiring). Een bipartiete patella is een normvariant die met een fractuur verward kan worden.</p>","image_url":"","wiki_title":"Patella fracture","match":"patellafractuur|knieschijfbreuk","option_only":true},"capitatumfractuur":{"title":"Fractuur van het os capitatum","short":"Een fractuur van het os capitatum is een zeldzame handwortelfractuur, soms samen met een scaphoïdfractuur.","definition":"<p>Het <strong>os capitatum</strong> is het grootste handwortelbeentje, centraal in de distale rij. Fracturen zijn zeldzaam, ontstaan bij hyperextensie van de pols en gaan soms samen met een scaphoïdfractuur. Net als bij het scaphoïd kan de proximale pool door de bloedvoorziening afsterven.</p>","image_url":"","wiki_title":"Capitate bone","match":"capitatumfractuur|fractuur os capitatum","option_only":true},"luxatie os lunatum":{"title":"Lunatumluxatie","short":"Bij een lunatumluxatie schiet het os lunatum naar palmair uit de handwortel, meestal na een val op de gestrekte pols.","definition":"<p>Bij een <strong>lunatumluxatie</strong> en de verwante perilunaire luxatie zijn de banden rond het lunatum gescheurd. Het verplaatste lunatum kan de n. medianus in de carpale tunnel comprimeren. Op een laterale röntgenfoto is het lunatum gekanteld (‘gekanteld theekopje’). Snelle repositie en operatief herstel zijn nodig.</p>","image_url":"","wiki_title":"Lunate dislocation","match":"luxatie os lunatum|lunatumluxatie|perilunaire luxatie","option_only":true},"pseudoartrose cmc-i":{"title":"Pseudartrose","short":"Een pseudartrose is een fractuur die niet is geheeld, waardoor er een beweeglijke ‘vals gewricht’-verbinding ontstaat.","definition":"<p>Bij een <strong>pseudartrose</strong> is de botgenezing na ongeveer 6–9 maanden uitgebleven. Risicofactoren zijn een slechte doorbloeding (bijv. scaphoïd), onvoldoende stabiliteit, infectie, roken en diabetes. Behandeling bestaat meestal uit chirurgische stabilisatie, eventueel met bottransplantaat.</p>","image_url":"","wiki_title":"Nonunion","match":"pseudoartrose cmc-i|pseudartrose|pseudoartrose","option_only":true},"marginalisatie":{"title":"Marginalisatie (acculturatie)","short":"Marginalisatie is een van de vier acculturatiestrategieën uit het model van Berry.","definition":"<p>Het <strong>acculturatiemodel van Berry</strong> beschrijft hoe migranten omgaan met twee culturen, op basis van twee vragen: wil iemand de eigen cultuur behouden, en wil iemand contact met de nieuwe cultuur? Dat geeft vier strategieën: integratie, assimilatie, separatie en marginalisatie. Marginalisatie gaat vaak samen met meer stress en psychische problemen.</p>","image_url":"","wiki_title":"","match":"marginalisatie","option_only":true},"separatie":{"title":"Separatie (acculturatie)","short":"Separatie is een van de vier acculturatiestrategieën uit het model van Berry.","definition":"<p>Het <strong>acculturatiemodel van Berry</strong> beschrijft hoe migranten omgaan met twee culturen, op basis van twee vragen: wil iemand de eigen cultuur behouden, en wil iemand contact met de nieuwe cultuur? Dat geeft vier strategieën: integratie, assimilatie, separatie en marginalisatie.</p>","image_url":"","wiki_title":"","match":"separatie","option_only":true},"geïndiceerde preventie":{"title":"Geïndiceerde preventie","short":"Geïndiceerde preventie richt zich op mensen met beginnende klachten of duidelijke risicofactoren, om een volledige aandoening te voorkomen.","definition":"<p>Preventie wordt naar doelgroep ingedeeld in <strong>universele</strong> (hele bevolking), <strong>selectieve</strong> (risicogroepen), <strong>geïndiceerde</strong> (mensen met vroege signalen of klachten, zonder diagnose) en <strong>zorggerelateerde</strong> preventie (mensen met een ziekte). Een andere indeling is primair, secundair en tertiair.</p>","image_url":"","wiki_title":"","match":"geïndiceerde preventie|geindiceerde preventie","option_only":true},"tertiaire preventie":{"title":"Tertiaire preventie","short":"Tertiaire preventie richt zich op mensen die al een ziekte hebben, om complicaties, verergering en functieverlies te beperken.","definition":"<p><strong>Tertiaire preventie</strong> omvat bijvoorbeeld revalidatie, leefstijlbegeleiding en goede controle van chronische ziekten. Primaire preventie voorkomt dat ziekte ontstaat, secundaire preventie spoort ziekte vroeg op.</p>","image_url":"","wiki_title":"Preventive healthcare","match":"tertiaire preventie","option_only":true},"echo":{"title":"Echografie","short":"Echografie maakt met hoogfrequente geluidsgolven beelden van weke delen en organen, zonder straling.","definition":"<p>Bij <strong>echografie</strong> zendt een transducer geluidsgolven uit en vangt de echo's op. Vocht is zwart, weefsel grijs; bot en lucht houden het geluid tegen. Het is goedkoop, snel en direct beschikbaar, en geschikt voor o.a. galblaas, nieren, schildklier, zwangerschap, hart (echocardiografie), vaten (duplex) en gewrichten. De kwaliteit hangt af van de onderzoeker en de patiënt.</p>","image_url":"","wiki_title":"Medical ultrasound","match":"echo|echografie|echoscopie|ultrageluid","option_only":true},"ct scan":{"title":"CT-scan","short":"Een CT-scan maakt met röntgenstraling dwarsdoorsneden van het lichaam.","definition":"<p>Bij <strong>computertomografie</strong> draait een röntgenbuis rond de patiënt en wordt een driedimensionaal beeld berekend. CT is snel en zeer geschikt voor trauma, bloedingen in het hoofd, longen, buik en bot; met contrast ook voor vaten. Nadelen zijn de stralingsbelasting en het contrastmiddel (nierfunctie, allergie).</p>","image_url":"","wiki_title":"CT scan","match":"ct scan|ct-scan|computertomografie","option_only":true},"shared decision making model":{"title":"Gedeelde besluitvorming (shared decision making)","short":"Bij gedeelde besluitvorming kiezen arts en patiënt samen een behandeling, op basis van medische informatie en de waarden van de patiënt.","definition":"<p>Bij <strong>shared decision making</strong> doorlopen arts en patiënt stappen: bespreken dat er een keuze is, de opties met voor- en nadelen uitleggen, de voorkeuren en waarden van de patiënt verkennen en samen tot een besluit komen. Het staat tussen het paternalistische model (arts beslist) en het informatieve model (patiënt beslist alleen). Keuzehulpen kunnen het ondersteunen.</p>","image_url":"","wiki_title":"Shared decision-making in medicine","match":"shared decision making model|shared decision making|gedeelde besluitvorming|overlegmodel","option_only":true},"wet langdurige zorg":{"title":"Wet langdurige zorg (Wlz)","short":"De Wet langdurige zorg regelt zorg voor mensen die blijvend 24 uur per dag zorg in de nabijheid of toezicht nodig hebben.","definition":"<p>De <strong>Wlz</strong> is bedoeld voor bijvoorbeeld ouderen met vergevorderde dementie en mensen met een ernstige verstandelijke, lichamelijke of zintuiglijke beperking. Het CIZ stelt de indicatie vast; de zorg kan in een instelling of thuis worden geleverd. De uitvoering ligt bij zorgkantoren.</p>","image_url":"","wiki_title":"","match":"wet langdurige zorg|wlz","option_only":true},"supinatie":{"title":"Supinatie","short":"Supinatie is het naar boven of voren draaien van de handpalm (onderarm) of het kantelen van de voetzool naar binnen.","definition":"<p>In de <strong>onderarm</strong> draait de radius bij supinatie parallel naast de ulna, zodat de handpalm naar voren (of boven) wijst; belangrijke supinatoren zijn de m. biceps brachii en m. supinator. Bij de <strong>voet</strong> is supinatie een gecombineerde beweging van inversie, adductie en plantairflexie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"supinatie","option_only":true},"pronatie":{"title":"Pronatie","short":"Pronatie is het naar beneden of achteren draaien van de handpalm, of het kantelen van de voetzool naar buiten.","definition":"<p>In de <strong>onderarm</strong> kruist de radius bij pronatie over de ulna; belangrijke pronatoren zijn de m. pronator teres en m. pronator quadratus. Bij de <strong>voet</strong> is pronatie een combinatie van eversie, abductie en dorsaalflexie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"pronatie","option_only":true},"eversie":{"title":"Eversie","short":"Eversie is het kantelen van de voetzool naar buiten (lateraal); de tegenovergestelde beweging is inversie.","definition":"<p><strong>Eversie</strong> vindt vooral plaats in het onderste spronggewricht en de gewrichten van de middenvoet. De belangrijkste everroren zijn de mm. fibulares (peronei) longus en brevis, geïnnerveerd door de n. fibularis superficialis.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"eversie","option_only":true},"abductie":{"title":"Abductie","short":"Abductie is een beweging van een lichaamsdeel van de middellijn af, bijvoorbeeld de arm zijwaarts heffen.","definition":"<p>Bij <strong>abductie</strong> beweegt een ledemaat in het frontale vlak weg van het lichaam (bij vingers en tenen: weg van de as van de hand of voet). Het tegenovergestelde is adductie. Voorbeelden van abductoren zijn de m. deltoideus en m. supraspinatus (schouder) en de m. gluteus medius en minimus (heup).</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"abductie","option_only":true},"exorotatie":{"title":"Exorotatie","short":"Exorotatie is draaien van een ledemaat om de lengteas naar buiten (lateraal).","definition":"<p>Bij <strong>exorotatie</strong> draait de voorzijde van bijv. de bovenarm of het bovenbeen naar buiten. In de schouder zijn de m. infraspinatus en m. teres minor de belangrijkste exorotatoren. Bij een frozen shoulder is de exorotatie vaak als eerste en het meest beperkt.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"exorotatie|externe rotatie|buitenwaartse rotatie","option_only":true},"dorsaalflexie":{"title":"Dorsaalflexie","short":"Dorsaalflexie is het optrekken van de voet (of het naar achteren buigen van de hand) richting de rugzijde.","definition":"<p>Bij de enkel betekent <strong>dorsaalflexie</strong> dat de voetrug richting het scheenbeen beweegt; de m. tibialis anterior is de belangrijkste spier (n. fibularis profundus). Uitval geeft een klapvoet. Bij de pols betekent dorsaalflexie extensie van de hand.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"dorsaalflexie|dorsiflexie","option_only":true},"plantairflexie":{"title":"Plantairflexie","short":"Plantairflexie is het naar beneden buigen van de voet, zoals bij op de tenen staan.","definition":"<p>De belangrijkste <strong>plantairflexoren</strong> zijn de m. gastrocnemius en m. soleus (samen de m. triceps surae, via de achillespees), geïnnerveerd door de n. tibialis. Bij een achillespeesruptuur is de plantairflexie verzwakt en is de test van Thompson positief.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"plantairflexie","option_only":true},"flexie":{"title":"Flexie","short":"Flexie is buigen: de hoek tussen twee lichaamsdelen wordt kleiner.","definition":"<p>Bij <strong>flexie</strong> beweegt een lichaamsdeel meestal naar voren in het sagittale vlak (bijv. de elleboog of heup buigen). Bij knie en enkel zijn er afwijkende afspraken (kniebuiging gaat naar achteren; bij de enkel spreekt men van dorsaal- en plantairflexie). Het tegenovergestelde is extensie.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"flexie|buiging","option_only":true},"extensie":{"title":"Extensie","short":"Extensie is strekken: de hoek tussen twee lichaamsdelen wordt groter.","definition":"<p><strong>Extensie</strong> is de tegenbeweging van flexie, bijvoorbeeld het strekken van elleboog of knie. Voorbij de neutrale stand spreekt men van hyperextensie (bijv. van de rug of de pols).</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"extensie|strekking","option_only":true},"a. iliaca externa":{"title":"A. iliaca externa","short":"De a. iliaca externa loopt van de splitsing van de a. iliaca communis naar het lig. inguinale, waar ze a. femoralis gaat heten.","definition":"<p>De <strong>a. iliaca externa</strong> loopt langs de m. psoas en geeft vlak boven het lig. inguinale de a. epigastrica inferior en de a. circumflexa ilium profunda af. Bij een niertransplantatie wordt de donornier vaak op deze arterie aangesloten.</p>","image_url":"","wiki_title":"External iliac artery","match":"a. iliaca externa|arteria iliaca externa","option_only":true},"a. poplitea":{"title":"A. poplitea","short":"De a. poplitea is de voortzetting van de a. femoralis in de knieholte; ze splitst in de a. tibialis anterior en de truncus tibiofibularis.","definition":"<p>De <strong>a. poplitea</strong> ligt diep in de knieholte, vlak tegen het kniekapsel, en is daardoor kwetsbaar bij een knieluxatie. De pols is moeilijk te voelen. Er kan een popliteaal aneurysma ontstaan, dat vaak dubbelzijdig is en embolieën naar het onderbeen kan geven.</p>","image_url":"","wiki_title":"Popliteal artery","match":"a. poplitea|arteria poplitea|knieholteslagader","option_only":true},"patella":{"title":"Patella (knieschijf)","short":"De patella is het grootste sesambeen van het lichaam, in de pees van de m. quadriceps.","definition":"<p>De <strong>patella</strong> vergroot de hefboomwerking van de m. quadriceps bij kniestrekking en beschermt het kniegewricht. Ze glijdt in de groeve van de femur (trochlea). Patella-luxatie gebeurt meestal naar lateraal, vooral bij jonge vrouwen met losse banden of een afwijkende stand.</p>","image_url":"","wiki_title":"Patella","match":"patella|knieschijf","option_only":true},"olecranon":{"title":"Olecranon","short":"Het olecranon is het proximale uitsteeksel van de ulna dat de punt van de elleboog vormt.","definition":"<p>Het <strong>olecranon</strong> is de aanhechting van de m. triceps brachii en past bij strekking in de fossa olecrani van de humerus. Omdat het direct onder de huid ligt, is het kwetsbaar bij direct trauma; de bursa olecrani erboven kan ontsteken.</p>","image_url":"","wiki_title":"Olecranon","match":"olecranon","option_only":true},"os pubis":{"title":"Os pubis (schaambeen)","short":"Het os pubis is het voorste deel van het heupbeen; beide schaambeenderen zijn in de symfyse met elkaar verbonden.","definition":"<p>Het <strong>os pubis</strong> vormt samen met het os ilium en os ischii het heupbeen (os coxae), dat in het acetabulum samenkomt. De ramus superior en inferior begrenzen het foramen obturatum. Fracturen van de schaambeentakken komen veel voor bij ouderen na een val.</p>","image_url":"","wiki_title":"Pubis (bone)","match":"os pubis|schaambeen","option_only":true},"os trapezoideum":{"title":"Os trapezoideum","short":"Het os trapezoideum is een klein handwortelbeentje in de distale rij, dat articuleert met het tweede middenhandsbeentje.","definition":"<p>Het <strong>os trapezoideum</strong> ligt tussen het os trapezium (aan de duimzijde) en het os capitatum. Het is het kleinste bot van de distale rij en breekt zelden.</p>","image_url":"","wiki_title":"Trapezoid bone","match":"os trapezoideum","option_only":true},"os metacarpale i":{"title":"Os metacarpale I","short":"Het os metacarpale I is het middenhandsbeentje van de duim, dat via een zadelgewricht met het os trapezium articuleert.","definition":"<p>Het <strong>eerste middenhandsbeen</strong> is korter en beweeglijker dan de andere. Bekende fracturen van de basis zijn de Bennett-fractuur (intra-articulair, met subluxatie) en de Rolando-fractuur. Artrose van het CMC-I-gewricht komt veel voor bij oudere vrouwen.</p>","image_url":"","wiki_title":"First metacarpal bone","match":"os metacarpale i|eerste middenhandsbeen","option_only":true},"articulatio humeri":{"title":"Schoudergewricht (articulatio humeri)","short":"Het schoudergewricht is een kogelgewricht tussen de humeruskop en de ondiepe cavitas glenoidalis van de scapula.","definition":"<p>De <strong>articulatio humeri</strong> is het meest beweeglijke gewricht van het lichaam, maar ook het minst stabiel. Stabiliteit komt vooral van de rotatorcuff, het labrum en het kapsel met de glenohumerale banden. Luxaties gebeuren meestal naar voren (anterieur).</p>","image_url":"","wiki_title":"Shoulder joint","match":"articulatio humeri|glenohumeraal gewricht|schoudergewricht","option_only":true},"articulationes subtalaris en talocalcaneonavicularis":{"title":"Onderste spronggewricht","short":"Het onderste spronggewricht bestaat uit de verbinding tussen talus en calcaneus en tussen talus, calcaneus en naviculare; het maakt inversie en eversie mogelijk.","definition":"<p>Het <strong>onderste spronggewricht</strong> zorgt dat de voet zich kan aanpassen aan oneffen ondergrond, door inversie en eversie. Het bovenste spronggewricht (talocrurale gewricht) daarentegen maakt vooral dorsaal- en plantairflexie mogelijk.</p>","image_url":"","wiki_title":"Subtalar joint","match":"articulationes subtalaris en talocalcaneonavicularis|onderste spronggewricht|subtalair gewricht","option_only":true},"m. gastrocnemius":{"title":"M. gastrocnemius","short":"De m. gastrocnemius is de oppervlakkige, tweekoppige kuitspier die de voet plantair flecteert en de knie helpt buigen.","definition":"<p>De <strong>m. gastrocnemius</strong> ontspringt boven de femurcondylen en hecht via de achillespees aan de calcaneus. Omdat hij over twee gewrichten loopt, is hij sterk betrokken bij lopen, rennen en springen. Een ‘tennis leg’ is een scheur in de mediale kop. Innervatie: n. tibialis.</p>","image_url":"","wiki_title":"Gastrocnemius muscle","match":"m. gastrocnemius|musculus gastrocnemius|kuitspier","option_only":true},"schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"schouderluxatie|luxatie van de schouder","option_only":true},"luxatie van het caput femoris":{"title":"Heupluxatie","short":"Bij een heupluxatie schiet de femurkop uit het acetabulum, meestal naar achteren door groot geweld (bijv. dashboardletsel).","definition":"<p>Bij een <strong>posterieure heupluxatie</strong> staat het been verkort, in flexie, adductie en endorotatie. Er is risico op letsel van de n. ischiadicus en op avasculaire necrose van de femurkop; snelle repositie is nodig. Bij een heupprothese kan luxatie al bij geringe beweging optreden.</p>","image_url":"","wiki_title":"Hip dislocation","match":"luxatie van het caput femoris|heupluxatie","option_only":true},"fibulafractuur":{"title":"Fibulafractuur","short":"Een fibulafractuur is een breuk van het kuitbeen, vaak distaal als onderdeel van een enkelfractuur.","definition":"<p>Distale <strong>fibulafracturen</strong> worden ingedeeld volgens Weber (A, B, C) op basis van de hoogte ten opzichte van de syndesmose; hoe hoger, hoe groter de kans op instabiliteit. Een hoge fibulafractuur kan samengaan met een mediaal enkelletsel (Maisonneuve). Een fractuur van het caput fibulae kan de n. fibularis communis beschadigen.</p>","image_url":"","wiki_title":"Fibula fracture","match":"fibulafractuur|kuitbeenbreuk","option_only":true},"fractuur caput fibulae":{"title":"Fractuur van het caput fibulae","short":"Een fractuur van het caput fibulae ligt vlak bij de n. fibularis communis, die daarbij beschadigd kan raken.","definition":"<p>Het <strong>caput fibulae</strong> ligt lateraal onder de knie. De n. fibularis communis loopt er direct omheen, zodat een fractuur (of druk, bijvoorbeeld van gips) een klapvoet kan veroorzaken. Het kan ook samengaan met letsel van het laterale bandapparaat van de knie.</p>","image_url":"","wiki_title":"Fibula","match":"fractuur caput fibulae|fibulakopfractuur","option_only":true},"crurisfractuur":{"title":"Crurisfractuur","short":"Een crurisfractuur is een breuk van het onderbeen waarbij tibia en fibula beide gebroken zijn.","definition":"<p>Een <strong>crurisfractuur</strong> ontstaat meestal door groot geweld (verkeer, sport). Omdat de tibia oppervlakkig ligt, zijn het relatief vaak open fracturen. Belangrijke complicaties zijn een compartimentsyndroom, infectie en vertraagde of uitblijvende genezing. Behandeling meestal met een intramedullaire pen.</p>","image_url":"","wiki_title":"Tibial fracture","match":"crurisfractuur|onderbeenfractuur","option_only":true},"arthrotomie":{"title":"Artrotomie","short":"Een artrotomie is het chirurgisch openen van een gewricht.","definition":"<p>Een <strong>artrotomie</strong> wordt o.a. gedaan om een septische artritis te spoelen, losse delen te verwijderen of een gewricht te herstellen of te vervangen. Veel ingrepen worden tegenwoordig artroscopisch (via een kijkoperatie) gedaan.</p>","image_url":"","wiki_title":"Arthrotomy","match":"arthrotomie|artrotomie","option_only":true},"diabetes type 2":{"title":"Diabetes mellitus","short":"Diabetes mellitus is een chronisch verhoogde bloedglucose door een tekort aan insuline (type 1) of verminderde insulinegevoeligheid met relatief tekort (type 2).","definition":"<p>Bij <strong>diabetes mellitus</strong> is de bloedglucose chronisch te hoog. Bij <em>type 1</em> vernietigt een auto-immuunproces de bètacellen van de pancreas (absoluut insulinetekort, vaak op jonge leeftijd, risico op ketoacidose). Bij <em>type 2</em> is er insulineresistentie (vaak met overgewicht) en een tekortschietende insulineproductie.</p><p>Klachten: dorst, veel plassen, moeheid en gewichtsverlies. Op termijn ontstaan microvasculaire (retinopathie, nefropathie, neuropathie) en macrovasculaire complicaties (hart- en vaatziekten). Diagnose o.a. nuchter glucose ≥7,0 mmol/L of HbA1c ≥48 mmol/mol.</p>","image_url":"","wiki_title":"Diabetes","match":"diabetes type 2","option_only":true},"lig. deltoideum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"lig. deltoideum|ligamentum deltoideum|mediale enkelband","option_only":true},"lig. calcaneofibulare":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"lig. calcaneofibulare|ligamentum calcaneofibulare","option_only":true},"artrose heup":{"title":"Coxartrose (heupartrose)","short":"Coxartrose is slijtage van het heupgewricht, met pijn in lies of bil en een beperkte (vooral endo)rotatie.","definition":"<p>Bij <strong>coxartrose</strong> geeft het kraakbeenverlies startpijn, pijn bij belasting en een beperking van de bewegingen, het eerst van endorotatie en flexie. De pijn wordt vaak in de lies gevoeld en kan uitstralen naar de knie. Behandeling begint met oefentherapie, gewichtsverlies en pijnstilling; bij ernstige klachten volgt een totale heupprothese.</p>","image_url":"","wiki_title":"Hip osteoarthritis","match":"artrose heup|coxartrose|heupartrose","option_only":true},"calcaneus":{"title":"Calcaneus (hielbeen)","short":"De calcaneus is het grootste voetwortelbeentje en vormt de hiel; de achillespees hecht erop aan.","definition":"<p>De <strong>calcaneus</strong> draagt het lichaamsgewicht naar de grond over en articuleert met de talus (onderste spronggewricht) en het os cuboideum. Het sustentaculum tali ondersteunt de talus. Bij een val van hoogte kan de calcaneus breken; bij hielpijn denkt men aan fasciitis plantaris of een achillespeesprobleem.</p>","image_url":"","wiki_title":"Calcaneus","match":"calcaneus|hielbeen","option_only":true},"talus":{"title":"Talus (sprongbeen)","short":"De talus is het voetwortelbeentje dat het onderbeen met de voet verbindt; er hechten geen spieren aan.","definition":"<p>De <strong>talus</strong> vormt met tibia en fibula het bovenste spronggewricht en met de calcaneus en het os naviculare het onderste spronggewricht. Het bot is grotendeels bedekt met kraakbeen en heeft een kwetsbare bloedvoorziening, waardoor een fractuur van de talushals tot avasculaire necrose kan leiden.</p>","image_url":"","wiki_title":"Talus bone","match":"talus|sprongbeen","option_only":true},"os naviculare":{"title":"Os naviculare (voet)","short":"Het os naviculare is het bootvormige voetwortelbeentje aan de mediale zijde, tussen talus en de ossa cuneiformia.","definition":"<p>Het <strong>os naviculare</strong> vormt de top van de mediale voetboog en is de aanhechting van de m. tibialis posterior. Een accessoir naviculare kan pijn geven. (In de hand wordt de term soms gebruikt voor het os scaphoideum.)</p>","image_url":"","wiki_title":"Navicular bone","match":"os naviculare|naviculare","option_only":true},"humerusfractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"humerusfractuur|proximale humerusfractuur|bovenarmbreuk","option_only":true},"radiusfractuur":{"title":"Distale radiusfractuur","short":"Een distale radiusfractuur is een breuk van het spaakbeen vlak boven de pols, meestal na een val op de uitgestrekte hand.","definition":"<p>Bij de klassieke <strong>Colles-fractuur</strong> is het distale fragment naar dorsaal gekanteld (‘vorkstand’). Bij ouderen wijst het vaak op osteoporose. Behandeling: repositie en gips of operatieve fixatie. Complicaties zijn standsafwijkingen, ruptuur van de pees van de m. extensor pollicis longus, carpaletunnelsyndroom en complex regionaal pijnsyndroom.</p>","image_url":"","wiki_title":"Distal radius fracture","match":"radiusfractuur|distale radiusfractuur|polsfractuur|colles-fractuur","option_only":true},"claviculafractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"claviculafractuur|sleutelbeenbreuk","option_only":true},"elleboogluxatie":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"elleboogluxatie","option_only":true},"reumatoide artritis":{"title":"Reumatoïde artritis","short":"Reumatoïde artritis is een chronische auto-immuunziekte met symmetrische ontsteking van vooral de kleine gewrichten van handen en voeten.","definition":"<p>Bij <strong>reumatoïde artritis</strong> leidt synovitis tot pannusvorming en erosie van kraakbeen en bot. Kenmerken: symmetrische polyartritis van MCP-, PIP- en MTP-gewrichten, ochtendstijfheid langer dan een uur, reumafactor en anti-CCP-antistoffen. Extra-articulair: reumanoduli, longaandoeningen, vasculitis. Vroege behandeling met DMARD's (zoals methotrexaat) voorkomt gewrichtsschade.</p>","image_url":"","wiki_title":"Rheumatoid arthritis","match":"reumatoide artritis","option_only":true},"ligamentum deltoideum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"ligamentum deltoideum","option_only":true},"ligamentum calcaneofibulare":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"ligamentum calcaneofibulare","option_only":true},"primaire preventie":{"title":"Primaire preventie","short":"Primaire preventie voorkomt dat een ziekte ontstaat, bijvoorbeeld door vaccinatie of stoppen met roken.","definition":"<p><strong>Primaire preventie</strong> richt zich op gezonde mensen en het wegnemen van oorzaken of risicofactoren: vaccinatie, gezondheidsvoorlichting, veilige omgeving en wetgeving (bijv. accijns op tabak). Secundaire preventie spoort ziekte vroeg op; tertiaire preventie beperkt de gevolgen.</p>","image_url":"","wiki_title":"Preventive healthcare","match":"primaire preventie","option_only":true},"zorggerelateerde preventie":{"title":"Zorggerelateerde preventie","short":"Zorggerelateerde preventie richt zich op mensen met een ziekte, om ziektelast, complicaties en verergering te beperken.","definition":"<p>Bij <strong>zorggerelateerde preventie</strong> gaat het bijvoorbeeld om leefstijlbegeleiding bij diabetes of hart- en vaatziekten, of valpreventie bij ouderen met osteoporose. Het hoort bij de indeling naar doelgroep: universeel, selectief, geïndiceerd en zorggerelateerd.</p>","image_url":"","wiki_title":"","match":"zorggerelateerde preventie","option_only":true},"de nederlandse zorgautoriteit":{"title":"Nederlandse Zorgautoriteit (NZa)","short":"De NZa is de toezichthouder op de zorgmarkten; ze stelt tarieven vast en houdt toezicht op zorgaanbieders en -verzekeraars.","definition":"<p>De <strong>NZa</strong> bewaakt de betaalbaarheid, toegankelijkheid en kwaliteit van de zorg vanuit marktperspectief: ze stelt (maximum)tarieven en prestaties vast, controleert de zorgplicht van verzekeraars en treedt op tegen onrechtmatige declaraties. De IGJ houdt toezicht op de kwaliteit en veiligheid van de zorg zelf.</p>","image_url":"","wiki_title":"","match":"de nederlandse zorgautoriteit|nederlandse zorgautoriteit|nza","option_only":true},"inspectie gezondheidszorg en jeugd":{"title":"Inspectie Gezondheidszorg en Jeugd (IGJ)","short":"De IGJ houdt namens de overheid toezicht op de kwaliteit en veiligheid van zorg, medische producten en jeugdhulp.","definition":"<p>De <strong>IGJ</strong> kan zorgaanbieders bezoeken, maatregelen opleggen en tuchtklachten indienen. Calamiteiten in de zorg moeten bij de IGJ worden gemeld.</p>","image_url":"","wiki_title":"","match":"inspectie gezondheidszorg en jeugd|igj","option_only":true},"risicoselectie":{"title":"Risicoselectie","short":"Risicoselectie is het weren of ongunstiger behandelen van verzekerden met een hoog gezondheidsrisico door verzekeraars.","definition":"<p>In de Nederlandse basisverzekering is <strong>risicoselectie</strong> verboden (acceptatieplicht, gelijke premie); de risicoverevening compenseert verzekeraars voor dure verzekerden. Bij aanvullende verzekeringen mogen verzekeraars wel selecteren.</p>","image_url":"","wiki_title":"","match":"risicoselectie","option_only":true},"assimilatie":{"title":"Assimilatie (acculturatie)","short":"Assimilatie is een acculturatiestrategie waarbij iemand de eigen cultuur loslaat en opgaat in de dominante cultuur.","definition":"<p>Het <strong>acculturatiemodel van Berry</strong> onderscheidt integratie, assimilatie, separatie en marginalisatie, op basis van het behouden van de eigen cultuur en het zoeken van contact met de nieuwe cultuur.</p>","image_url":"","wiki_title":"","match":"assimilatie","option_only":true},"plasmodium falciparum malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum malaria","option_only":true},"zorg gerelateerde preventie":{"title":"Zorggerelateerde preventie","short":"Zorggerelateerde preventie richt zich op mensen met een ziekte, om ziektelast, complicaties en verergering te beperken.","definition":"<p>Bij <strong>zorggerelateerde preventie</strong> gaat het bijvoorbeeld om leefstijlbegeleiding bij diabetes of hart- en vaatziekten, of valpreventie bij ouderen met osteoporose. Het hoort bij de indeling naar doelgroep: universeel, selectief, geïndiceerd en zorggerelateerd.</p>","image_url":"","wiki_title":"","match":"zorg gerelateerde preventie","option_only":true},"een genationaliseerd zorgstelsel":{"title":"Genationaliseerd zorgstelsel (Beveridge)","short":"Een genationaliseerd zorgstelsel wordt gefinancierd uit belastingen en de zorg wordt grotendeels door de overheid geleverd.","definition":"<p>Bij een <strong>genationaliseerd stelsel</strong> (Beveridgemodel, bijv. de NHS in het Verenigd Koninkrijk) is zorg in principe voor iedereen toegankelijk en grotendeels gratis bij gebruik. De overheid bepaalt het budget en organiseert de zorg; wachtlijsten zijn een bekend nadeel.</p>","image_url":"","wiki_title":"","match":"een genationaliseerd zorgstelsel","option_only":true},"genationaliseerd verzekeringsstelsel":{"title":"Genationaliseerd zorgstelsel (Beveridge)","short":"Een genationaliseerd zorgstelsel wordt gefinancierd uit belastingen en de zorg wordt grotendeels door de overheid geleverd.","definition":"<p>Bij een <strong>genationaliseerd stelsel</strong> (Beveridgemodel, bijv. de NHS in het Verenigd Koninkrijk) is zorg in principe voor iedereen toegankelijk en grotendeels gratis bij gebruik. De overheid bepaalt het budget en organiseert de zorg; wachtlijsten zijn een bekend nadeel.</p>","image_url":"","wiki_title":"","match":"genationaliseerd verzekeringsstelsel","option_only":true},"inspectie voor de gezondheidszorg":{"title":"Inspectie Gezondheidszorg en Jeugd (IGJ)","short":"De IGJ houdt namens de overheid toezicht op de kwaliteit en veiligheid van zorg, medische producten en jeugdhulp.","definition":"<p>De <strong>IGJ</strong> kan zorgaanbieders bezoeken, maatregelen opleggen en tuchtklachten indienen. Calamiteiten in de zorg moeten bij de IGJ worden gemeld.</p>","image_url":"","wiki_title":"","match":"inspectie voor de gezondheidszorg","option_only":true},"de nederlandse zorgautoriteit (nza)":{"title":"Nederlandse Zorgautoriteit (NZa)","short":"De NZa is de toezichthouder op de zorgmarkten; ze stelt tarieven vast en houdt toezicht op zorgaanbieders en -verzekeraars.","definition":"<p>De <strong>NZa</strong> bewaakt de betaalbaarheid, toegankelijkheid en kwaliteit van de zorg vanuit marktperspectief: ze stelt (maximum)tarieven en prestaties vast, controleert de zorgplicht van verzekeraars en treedt op tegen onrechtmatige declaraties. De IGJ houdt toezicht op de kwaliteit en veiligheid van de zorg zelf.</p>","image_url":"","wiki_title":"","match":"de nederlandse zorgautoriteit (nza)","option_only":true},"voorste schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"voorste schouderluxatie","option_only":true},"communication and persuasion theorie":{"title":"Communication-and-persuasiontheorie","short":"De communication-and-persuasiontheorie (McGuire) beschrijft hoe een boodschap via een reeks stappen tot gedragsverandering kan leiden.","definition":"<p>Volgens <strong>McGuire</strong> moet de ontvanger worden blootgesteld, aandacht hebben, de boodschap begrijpen, accepteren, onthouden en ernaar handelen. Kenmerken van zender, boodschap, kanaal en ontvanger bepalen hoe overtuigend een boodschap is.</p>","image_url":"","wiki_title":"","match":"communication and persuasion theorie|communication-persuasion model","option_only":true},"frozen shoulder":{"title":"Frozen shoulder (capsulitis adhaesiva)","short":"Bij een frozen shoulder raakt het kapsel van het schoudergewricht ontstoken en daarna geschrompeld, met pijn en verstijving.","definition":"<p>Een <strong>frozen shoulder</strong> komt vooral voor tussen 40 en 60 jaar en vaker bij diabetes. Het verloopt in fasen: pijnlijk, stijf en herstel, samen vaak 1–3 jaar. De exorotatie is meestal het eerst en het meest beperkt.</p>","image_url":"","wiki_title":"Adhesive capsulitis of the shoulder","match":"frozen shoulder|capsulitis adhaesiva","option_only":true},"chlamydia trachomatis":{"title":"Chlamydia trachomatis","short":"Chlamydia trachomatis is een obligaat intracellulaire bacterie en de meest voorkomende bacteriële soa.","definition":"<p><strong>Chlamydia</strong> geeft vaak geen klachten; soms urethritis, cervicitis met afscheiding of bloedverlies na gemeenschap. Complicaties zijn salpingitis met subfertiliteit en extra-uteriene zwangerschap, epididymitis en reactieve artritis. Bij pasgeborenen conjunctivitis en pneumonie. Behandeling met doxycycline of azitromycine.</p>","image_url":"","wiki_title":"Chlamydia","match":"chlamydia trachomatis|chlamydia","option_only":true},"een frozen shoulder":{"title":"Frozen shoulder (capsulitis adhaesiva)","short":"Bij een frozen shoulder raakt het kapsel van het schoudergewricht ontstoken en daarna geschrompeld, met pijn en verstijving.","definition":"<p>Een <strong>frozen shoulder</strong> komt vooral voor tussen 40 en 60 jaar en vaker bij diabetes. Het verloopt in fasen: pijnlijk, stijf en herstel, samen vaak 1–3 jaar. De exorotatie is meestal het eerst en het meest beperkt.</p>","image_url":"","wiki_title":"Adhesive capsulitis of the shoulder","match":"een frozen shoulder","option_only":true},"endorotatie":{"title":"Endorotatie","short":"Endorotatie is draaien van een ledemaat om de lengteas naar binnen (mediaal).","definition":"<p>Bij <strong>endorotatie</strong> draait de voorzijde van bijv. bovenarm of bovenbeen naar binnen. In de schouder zijn de m. subscapularis, m. pectoralis major en m. latissimus dorsi belangrijke endorotatoren. Bij coxartrose is de endorotatie van de heup vaak als eerste beperkt.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"endorotatie|interne rotatie|binnenwaartse rotatie","option_only":true},"adductie":{"title":"Adductie","short":"Adductie is een beweging van een lichaamsdeel naar de middellijn toe; het tegenovergestelde van abductie.","definition":"<p>Bij <strong>adductie</strong> beweegt een ledemaat in het frontale vlak naar het lichaam toe. De adductoren van de heup (m. adductor longus, brevis, magnus, m. gracilis) worden geïnnerveerd door de n. obturatorius.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"adductie","option_only":true},"circumductie":{"title":"Circumductie","short":"Circumductie is een kegelvormige rondgaande beweging van een ledemaat, een combinatie van flexie, abductie, extensie en adductie.","definition":"<p><strong>Circumductie</strong> is mogelijk in kogelgewrichten (schouder, heup) en in tweeassige gewrichten zoals de pols. Bij een ‘maaiend’ looppatroon na een beroerte zwaait het been in een boog naar buiten.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"circumductie","option_only":true},"palmairflexie":{"title":"Palmairflexie","short":"Palmairflexie is het buigen van de hand richting de handpalm in het polsgewricht.","definition":"<p>Bij <strong>palmairflexie</strong> buigt de pols naar de handpalmzijde; de tegenbeweging is dorsaalflexie (extensie). De belangrijkste polsflexoren zijn de m. flexor carpi radialis en ulnaris. De test van Phalen (maximale palmairflexie) lokt klachten uit bij het carpaletunnelsyndroom.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"palmairflexie|volairflexie","option_only":true},"ulnairabductie":{"title":"Ulnairdeviatie","short":"Ulnairdeviatie is het zijwaarts kantelen van de hand naar de pinkzijde in het polsgewricht.","definition":"<p><strong>Ulnairdeviatie</strong> gebeurt vooral in het radiocarpale gewricht; de tegenbeweging is radiaaldeviatie. Bij reumatoïde artritis ontstaat vaak een ulnaire deviatie van de vingers in de MCP-gewrichten.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"ulnairabductie|ulnairdeviatie|ulnaire deviatie","option_only":true},"anteflexie":{"title":"Anteflexie","short":"Anteflexie is het naar voren heffen of buigen van een lichaamsdeel, bijvoorbeeld de arm in het schoudergewricht.","definition":"<p>In de schouder heet flexie ook <strong>anteflexie</strong>; de tegenbeweging is retroflexie (extensie). Voor de uterus betekent anteflexie de normale knik tussen corpus en cervix naar voren.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"anteflexie","option_only":true},"retroflexie":{"title":"Retroflexie","short":"Retroflexie is het naar achteren bewegen of buigen van een lichaamsdeel, zoals de arm in de schouder.","definition":"<p>Bij de schouder is <strong>retroflexie</strong> de beweging van de arm naar achteren (extensie). Bij de uterus betekent retroflexie een naar achteren geknikt corpus, een normvariant.</p>","image_url":"","wiki_title":"Anatomical terms of motion","match":"retroflexie","option_only":true},"paternalistische model":{"title":"Paternalistisch model","short":"In het paternalistische model beslist de arts wat goed is voor de patiënt, met weinig inbreng van de patiënt.","definition":"<p>Het <strong>paternalistische model</strong> (Emanuel en Emanuel) staat tegenover het informatieve model (de patiënt beslist) en gedeelde besluitvorming. Het past soms in acute situaties, maar in de meeste keuzes wordt gedeelde besluitvorming nagestreefd.</p>","image_url":"","wiki_title":"","match":"paternalistische model|paternalistisch model|paternalisme","option_only":true},"n. thoracodorsalis":{"title":"N. thoracodorsalis","short":"De n. thoracodorsalis innerveert de m. latissimus dorsi.","definition":"<p>De <strong>n. thoracodorsalis</strong> (C6–C8) komt uit de fasciculus posterior van de plexus brachialis en loopt langs de achterwand van de oksel. Hij kan beschadigd raken bij een okselklierdissectie.</p>","image_url":"","wiki_title":"Thoracodorsal nerve","match":"n. thoracodorsalis|nervus thoracodorsalis","option_only":true},"a. circumflexa femoris lateralis":{"title":"A. circumflexa femoris lateralis","short":"De a. circumflexa femoris lateralis is een tak van de a. profunda femoris die o.a. de heupkop en de m. quadriceps voorziet.","definition":"<p>De <strong>aa. circumflexae femoris</strong> (medialis en lateralis) vormen een ring rond het collum femoris, van waaruit de femurkop wordt doorbloed. Bij een mediale collumfractuur kunnen deze vaten scheuren, met avasculaire necrose als risico.</p>","image_url":"","wiki_title":"Lateral circumflex femoral artery","match":"a. circumflexa femoris lateralis","option_only":true},"clavicula":{"title":"Clavicula (sleutelbeen)","short":"De clavicula is het S-vormige bot dat het borstbeen met het schouderblad verbindt.","definition":"<p>De <strong>clavicula</strong> houdt de schouder op afstand van de romp en draagt krachten van de arm over naar het axiale skelet. Ze is het eerste bot dat verbeent (desmaal). Onder de clavicula lopen de vasa subclavia en de plexus brachialis.</p>","image_url":"","wiki_title":"Clavicle","match":"clavicula|sleutelbeen","option_only":true},"achillespees":{"title":"Achillespees","short":"De achillespees is de sterkste pees van het lichaam; ze verbindt de kuitspieren met de calcaneus.","definition":"<p>Een <strong>achillespeesruptuur</strong> ontstaat vaak bij explosieve bewegingen bij mannen van middelbare leeftijd, soms door fluorochinolonen of corticosteroïden. Er is een knal, een palpabele delle en een positieve test van Thompson (geen plantairflexie bij knijpen in de kuit). Tendinopathie geeft pijn en zwelling enkele centimeters boven de aanhechting.</p>","image_url":"","wiki_title":"Achilles tendon","match":"achillespees|tendo calcaneus","option_only":true},"os metacarpale v":{"title":"Os metacarpale V","short":"Het os metacarpale V is het middenhandsbeentje van de pink.","definition":"<p>Een fractuur van de hals van het <strong>vijfde middenhandsbeen</strong> heet een boksersfractuur en ontstaat door slaan met een gebalde vuist. Belangrijk is te controleren op rotatiestand van de pink en op bijtwonden over de knokkel (‘fight bite’).</p>","image_url":"","wiki_title":"Fifth metacarpal bone","match":"os metacarpale v|vijfde middenhandsbeen","option_only":true},"os metatarsalis v":{"title":"Os metatarsale V","short":"Het os metatarsale V is het middenvoetsbeentje van de kleine teen; de basis (tuberositas) breekt vaak bij een inversietrauma.","definition":"<p>Bij een inversietrauma kan de pees van de m. fibularis brevis een avulsiefractuur van de <strong>basis van metatarsale V</strong> veroorzaken. Een iets distalere fractuur (Jones-fractuur) geneest slechter door een kwetsbare bloedvoorziening. De Ottawa-enkelregels helpen bepalen of een foto nodig is.</p>","image_url":"","wiki_title":"Fifth metatarsal bone","match":"os metatarsalis v|os metatarsale v|vijfde middenvoetsbeen","option_only":true},"os trapezium":{"title":"Os trapezium","short":"Het os trapezium is het handwortelbeentje aan de duimzijde van de distale rij, dat met het eerste middenhandsbeen het zadelgewricht van de duim vormt.","definition":"<p>Artrose van het <strong>CMC-I-gewricht</strong> (tussen trapezium en metacarpale I) komt veel voor bij oudere vrouwen en geeft pijn bij knijpen en draaien. Bij ernstige klachten kan het trapezium worden verwijderd (trapeziëctomie).</p>","image_url":"","wiki_title":"Trapezium (bone)","match":"os trapezium","option_only":true},"m. rectus femoris":{"title":"M. rectus femoris","short":"De m. rectus femoris is het deel van de quadriceps dat over zowel heup als knie loopt: heupflexie en kniestrekking.","definition":"<p>De <strong>m. rectus femoris</strong> ontspringt aan de spina iliaca anterior inferior en het acetabulum en hecht via de quadricepspees en patella aan de tuberositas tibiae. Bij jonge sporters kan een avulsie van de origo ontstaan. Innervatie: n. femoralis.</p>","image_url":"","wiki_title":"Rectus femoris muscle","match":"m. rectus femoris|musculus rectus femoris","option_only":true},"m. soleus":{"title":"M. soleus","short":"De m. soleus is de diepe kuitspier die samen met de m. gastrocnemius via de achillespees de voet plantair flecteert.","definition":"<p>De <strong>m. soleus</strong> loopt alleen over het enkelgewricht en is daardoor vooral actief bij staan (houdingsspier). Door contractie pompt hij veneus bloed omhoog (‘kuitspierpomp’). Innervatie: n. tibialis.</p>","image_url":"","wiki_title":"Soleus muscle","match":"m. soleus|musculus soleus","option_only":true},"voorste schuifladetest":{"title":"Voorste schuifladetest","short":"De voorste schuifladetest onderzoekt of de tibia abnormaal naar voren schuift ten opzichte van de femur, als teken van een voorste kruisbandletsel.","definition":"<p>Bij de knie is de <strong>Lachmantest</strong> (in 20–30° flexie) gevoeliger dan de klassieke schuiflade in 90° flexie. Bij de enkel test een voorste schuiflade het lig. talofibulare anterius. Een achterste schuiflade test de achterste kruisband.</p>","image_url":"","wiki_title":"Anterior drawer test","match":"voorste schuifladetest|lachmantest|schuifladetest","option_only":true},"hydropstest":{"title":"Hydropstest","short":"Met een hydropstest wordt onderzocht of er vocht (hydrops) in het kniegewricht zit.","definition":"<p>Bij de <strong>hydropstest</strong> wordt het vocht uit de recessus suprapatellaris naar beneden gestreken en daarna op de patella gedrukt (dansende patella) of een vochtgolf opgewekt. Veel vocht na een trauma kan wijzen op een kruisbandletsel of fractuur (hemartros).</p>","image_url":"","wiki_title":"","match":"hydropstest|ballotement van de patella|dansende patella","option_only":true},"impingement van de schouder":{"title":"Subacromiaal pijnsyndroom (impingement)","short":"Bij het subacromiaal pijnsyndroom ontstaat pijn bij het heffen van de arm, vaak met een pijnlijk traject tussen ongeveer 60 en 120°.","definition":"<p>Bij <strong>subacromiale klachten</strong> zijn de supraspinatuspees en de bursa subacromialis geprikkeld in de ruimte onder het acromion. Kenmerkend is een ‘painful arc’ bij abductie. Behandeling: belasting aanpassen, oefentherapie en eventueel een injectie.</p>","image_url":"","wiki_title":"Shoulder impingement syndrome","match":"impingement van de schouder|impingement|subacromiaal pijnsyndroom|painful arc syndroom|painful arc","option_only":true},"peritendinitis":{"title":"Tendinopathie (peritendinitis)","short":"Bij een tendinopathie is een pees pijnlijk en gezwollen door overbelasting; bij peritendinitis is vooral het peesomhulsel ontstoken.","definition":"<p><strong>Tendinopathieën</strong> komen veel voor bij de achillespees, patellapees, rotatorcuff en epicondylen van de elleboog. Meestal gaat het om degeneratie door herhaalde overbelasting, niet om een echte ontsteking. Behandeling met belastingsmanagement en (excentrische) oefentherapie.</p>","image_url":"","wiki_title":"Tendinopathy","match":"peritendinitis|tendinitis|tendinopathie|peesontsteking","option_only":true},"cervicaal syndroom":{"title":"Cervicaal syndroom (nekpijn)","short":"Een cervicaal syndroom is nekpijn, soms met uitstraling naar schouder of arm, meestal zonder ernstige oorzaak.","definition":"<p>Bij aspecifieke <strong>nekpijn</strong> is er pijn en bewegingsbeperking zonder neurologische uitval. Bij uitstraling met gevoelsstoornis of krachtsverlies in een dermatoom of myotoom spreekt men van een cervicaal radiculair syndroom (bijv. door een hernia of degeneratie). Rode vlaggen zijn o.a. koorts, trauma, maligniteit en myelopathie.</p>","image_url":"","wiki_title":"Neck pain","match":"een cervicaal syndroom|cervicaal syndroom","option_only":true},"acetabulumfractuur rechts":{"title":"Acetabulumfractuur","short":"Een acetabulumfractuur is een breuk van de heupkom, meestal door hoogenergetisch trauma of bij ouderen door een val.","definition":"<p>Bij een <strong>acetabulumfractuur</strong> drukt de femurkop in de kom. Het is een intra-articulaire fractuur met risico op posttraumatische artrose; verplaatste fracturen worden vaak operatief gefixeerd. Er kan letsel van de n. ischiadicus zijn.</p>","image_url":"","wiki_title":"Acetabular fracture","match":"acetabulumfractuur rechts|acetabulumfractuur","option_only":true},"open boek fractuur":{"title":"Open-boekfractuur van het bekken","short":"Bij een open-boekfractuur van het bekken klappen beide bekkenhelften vooraan open, met scheuring van de symfyse en risico op levensbedreigend bloedverlies.","definition":"<p>De <strong>open-boekfractuur</strong> ontstaat door een anteroposterieure klap. Het bekkenvolume neemt toe en veneuze plexussen kunnen hevig bloeden. Een bekkenband die de bekkenring sluit is een belangrijke eerste maatregel; daarna eventueel embolisatie of externe fixatie.</p>","image_url":"","wiki_title":"Pelvic fracture","match":"open boek fractuur|open-boekfractuur|bekkenringfractuur","option_only":true},"sternoclaviculaire luxatie":{"title":"Sternoclaviculaire luxatie","short":"Een sternoclaviculaire luxatie is een ontwrichting van het gewricht tussen sleutelbeen en borstbeen.","definition":"<p>Een <strong>anterieure</strong> luxatie komt het meest voor en is meestal onschuldig. Een <strong>posterieure</strong> luxatie is zeldzaam maar gevaarlijk, omdat de clavicula de trachea, slokdarm of grote vaten kan drukken.</p>","image_url":"","wiki_title":"Sternoclavicular dislocation","match":"sternoclaviculaire luxatie","option_only":true},"posterieure glenohumerale luxatie":{"title":"Posterieure schouderluxatie","short":"Een posterieure schouderluxatie is een ontwrichting van de humeruskop naar achteren, vaak na een epileptische aanval of elektrocutie.","definition":"<p>Bij een <strong>posterieure luxatie</strong> staat de arm in endorotatie en kan hij niet naar buiten worden gedraaid. Op een gewone voorachterwaartse foto wordt ze makkelijk gemist (‘lightbulb sign’); een axiale opname is nodig.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"posterieure glenohumerale luxatie|posterieure schouderluxatie|achterste schouderluxatie","option_only":true},"ergotherapeut":{"title":"Ergotherapeut","short":"Een ergotherapeut helpt mensen om dagelijkse activiteiten (zelfzorg, wonen, werk) weer zo zelfstandig mogelijk uit te voeren.","definition":"<p><strong>Ergotherapie</strong> richt zich op het handelen in het dagelijks leven, bijvoorbeeld met advies over hulpmiddelen, aanpassingen in huis en het aanleren van andere manieren van doen, o.a. bij reuma, CVA, dementie en na handletsel.</p>","image_url":"","wiki_title":"Occupational therapy","match":"ergotherapeut|ergotherapie","option_only":true},"logopedist":{"title":"Logopedist","short":"Een logopedist behandelt problemen met spraak, taal, stem, gehoor, slikken en ademhaling.","definition":"<p><strong>Logopedie</strong> wordt o.a. ingezet bij taalontwikkelingsachterstand, stotteren, stemklachten (bijv. stembandknobbeltjes), afasie en dysartrie na een beroerte, en slikstoornissen.</p>","image_url":"","wiki_title":"Speech–language pathology","match":"logopedist|logopedie","option_only":true},"jeugdarts":{"title":"Jeugdarts","short":"De jeugdarts werkt in de jeugdgezondheidszorg en volgt de groei en ontwikkeling van kinderen van 0 tot 18 jaar.","definition":"<p>De <strong>jeugdarts</strong> doet preventieve onderzoeken op het consultatiebureau en op school, voert het Rijksvaccinatieprogramma uit, spoort problemen vroeg op (bijv. heupdysplasie, groeiproblemen, ontwikkelingsachterstand, kindermishandeling) en geeft voorlichting.</p>","image_url":"","wiki_title":"","match":"jeugdarts|jeugdgezondheidszorg|consultatiebureau","option_only":true},"zorgverzekeringswet (zvw)":{"title":"Zorgverzekeringswet (Zvw)","short":"De Zorgverzekeringswet regelt de verplichte basisverzekering voor curatieve zorg in Nederland.","definition":"<p>Onder de <strong>Zvw</strong> moet iedere inwoner een basisverzekering afsluiten. Verzekeraars hebben een acceptatieplicht en mogen geen premieverschillen maken op basis van gezondheid; een risicovereveningssysteem compenseert hen. Er geldt een verplicht eigen risico (niet voor huisartsenzorg en zorg voor kinderen).</p>","image_url":"","wiki_title":"","match":"zorgverzekeringswet (zvw)|zorgverzekeringswet|zvw","option_only":true},"gereguleerde marktwerking zorgstelstel":{"title":"Gereguleerde marktwerking","short":"In een stelsel met gereguleerde marktwerking concurreren verzekeraars en zorgaanbieders, binnen regels die toegankelijkheid en solidariteit waarborgen.","definition":"<p>Het Nederlandse zorgstelsel (sinds 2006) combineert <strong>concurrentie</strong> tussen zorgverzekeraars en -aanbieders met overheidsregels: verplichte verzekering, acceptatieplicht, een wettelijk basispakket, risicoverevening en toezicht door de NZa.</p>","image_url":"","wiki_title":"","match":"gereguleerde marktwerking zorgstelstel|gereguleerde marktwerking","option_only":true},"inkomenssolidariteit":{"title":"Inkomenssolidariteit","short":"Bij inkomenssolidariteit betalen mensen met een hoger inkomen meer mee aan de zorg dan mensen met een laag inkomen.","definition":"<p>In Nederland gebeurt dat via de <strong>inkomensafhankelijke bijdrage</strong> voor de Zvw en de zorgtoeslag. Daarnaast bestaat risicosolidariteit (gezonden betalen mee voor zieken, via gelijke premies).</p>","image_url":"","wiki_title":"","match":"inkomenssolidariteit","option_only":true},"risicosolidariteit":{"title":"Risicosolidariteit","short":"Bij risicosolidariteit betalen gezonde mensen mee voor de zorgkosten van zieken, doordat iedereen dezelfde premie betaalt.","definition":"<p>Het verbod op premiedifferentiatie en de acceptatieplicht in de basisverzekering zorgen voor <strong>risicosolidariteit</strong>. Bij aanvullende verzekeringen is die beperkter, omdat verzekeraars daar mogen selecteren.</p>","image_url":"","wiki_title":"","match":"risicosolidariteit|risicospreiding","option_only":true},"incidentie":{"title":"Incidentie","short":"Incidentie is het aantal nieuwe gevallen van een ziekte in een populatie gedurende een bepaalde periode.","definition":"<p>De <strong>cumulatieve incidentie</strong> is het risico (nieuwe gevallen gedeeld door het aantal mensen at risk aan het begin); de <strong>incidentiedichtheid</strong> deelt door de persoonstijd. Prevalentie is het totaal aantal bestaande gevallen op een moment en hangt af van incidentie én ziekteduur.</p>","image_url":"","wiki_title":"Incidence (epidemiology)","match":"incidentie|incidentiecijfer","option_only":true},"verloren levensjaren":{"title":"Verloren levensjaren en ziektelast (DALY)","short":"De ziektelast van een aandoening wordt vaak uitgedrukt in DALY's: verloren levensjaren door vroegtijdige sterfte plus jaren geleefd met ziekte.","definition":"<p>Een <strong>DALY</strong> (disability-adjusted life year) combineert sterfte (verloren levensjaren) en beperkingen (jaren met ziekte, gewogen naar ernst). Zo kunnen ziekten die vooral sterfte geven worden vergeleken met ziekten die vooral beperkingen geven, zoals depressie.</p>","image_url":"","wiki_title":"Disability-adjusted life year","match":"verloren levensjaren|totale ziektelast|daly|ziektelast","option_only":true},"intrabeoordelaarsbetrouwbaarheid":{"title":"Intrabeoordelaarsbetrouwbaarheid","short":"Intrabeoordelaarsbetrouwbaarheid is de mate waarin dezelfde beoordelaar bij herhaling tot dezelfde uitkomst komt.","definition":"<p>Bij <strong>intrabeoordelaarsbetrouwbaarheid</strong> beoordeelt één persoon dezelfde situatie meerdere keren; bij interbeoordelaarsbetrouwbaarheid vergelijkt men verschillende beoordelaars. Voor categorische uitkomsten wordt vaak Cohens kappa gebruikt, voor continue de ICC.</p>","image_url":"","wiki_title":"Intra-rater reliability","match":"intrabeoordelaarsbetrouwbaarheid|intra-observer betrouwbaarheid","option_only":true},"bron en contactopsporing":{"title":"Bron- en contactonderzoek","short":"Bij bron- en contactonderzoek zoekt de GGD uit waar iemand een infectie heeft opgelopen en wie mogelijk besmet is geraakt.","definition":"<p><strong>Bron- en contactonderzoek</strong> wordt gedaan bij meldingsplichtige infectieziekten zoals tuberculose, mazelen en meningokokkenziekte. Contacten krijgen zo nodig onderzoek, vaccinatie of profylaxe om verdere verspreiding te voorkomen.</p>","image_url":"","wiki_title":"Contact tracing","match":"bron en contactopsporing|bron- en contactonderzoek|bron en contact onderzoek|contactonderzoek","option_only":true},"social marketing-theorie":{"title":"Social marketing","short":"Social marketing past marketingtechnieken toe om gezond gedrag te bevorderen.","definition":"<p>Bij <strong>social marketing</strong> worden de doelgroep, het ‘product’ (gewenst gedrag), de ‘prijs’ (wat het kost), de plaats en promotie bewust gekozen, net als in de commerciële marketing. Voorbeelden zijn campagnes voor de Bob en tegen roken.</p>","image_url":"","wiki_title":"Social marketing","match":"social marketing-theorie|social marketing","option_only":true},"hulp bij zelfdoding":{"title":"Hulp bij zelfdoding","short":"Bij hulp bij zelfdoding verstrekt de arts een middel dat de patiënt zelf inneemt; bij euthanasie dient de arts het middel toe.","definition":"<p>In Nederland zijn <strong>euthanasie en hulp bij zelfdoding</strong> niet strafbaar als de arts zich houdt aan de zorgvuldigheidseisen van de Wtl (o.a. vrijwillig en weloverwogen verzoek, uitzichtloos en ondraaglijk lijden, consultatie van een onafhankelijke arts) en het meldt bij de toetsingscommissie.</p>","image_url":"","wiki_title":"Assisted suicide","match":"hulp bij zelfdoding|euthanasie","option_only":true},"lig. talofibulaire posterius":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulaire posterius","option_only":true},"gereguleerde markwerking stelsel":{"title":"Gereguleerde marktwerking","short":"In een stelsel met gereguleerde marktwerking concurreren verzekeraars en zorgaanbieders, binnen regels die toegankelijkheid en solidariteit waarborgen.","definition":"<p>Het Nederlandse zorgstelsel (sinds 2006) combineert <strong>concurrentie</strong> tussen zorgverzekeraars en -aanbieders met overheidsregels: verplichte verzekering, acceptatieplicht, een wettelijk basispakket, risicoverevening en toezicht door de NZa.</p>","image_url":"","wiki_title":"","match":"gereguleerde markwerking stelsel","option_only":true},"een gereguleerde marktwerking stelsel":{"title":"Gereguleerde marktwerking","short":"In een stelsel met gereguleerde marktwerking concurreren verzekeraars en zorgaanbieders, binnen regels die toegankelijkheid en solidariteit waarborgen.","definition":"<p>Het Nederlandse zorgstelsel (sinds 2006) combineert <strong>concurrentie</strong> tussen zorgverzekeraars en -aanbieders met overheidsregels: verplichte verzekering, acceptatieplicht, een wettelijk basispakket, risicoverevening en toezicht door de NZa.</p>","image_url":"","wiki_title":"","match":"een gereguleerde marktwerking stelsel","option_only":true},"een tendinitis":{"title":"Tendinopathie (peritendinitis)","short":"Bij een tendinopathie is een pees pijnlijk en gezwollen door overbelasting; bij peritendinitis is vooral het peesomhulsel ontstoken.","definition":"<p><strong>Tendinopathieën</strong> komen veel voor bij de achillespees, patellapees, rotatorcuff en epicondylen van de elleboog. Meestal gaat het om degeneratie door herhaalde overbelasting, niet om een echte ontsteking. Behandeling met belastingsmanagement en (excentrische) oefentherapie.</p>","image_url":"","wiki_title":"Tendinopathy","match":"een tendinitis","option_only":true},"mesothelioom":{"title":"Mesothelioom","short":"Het mesothelioom is een kwaadaardige tumor van het mesotheel, meestal van de pleura, sterk geassocieerd met asbestblootstelling.","definition":"<p>Een <strong>mesothelioom</strong> ontstaat vaak 20–40 jaar na blootstelling aan asbest. Klachten: kortademigheid door pleuravocht, pijn op de borst en gewichtsverlies. De prognose is slecht. In Nederland kunnen patiënten een tegemoetkoming krijgen via het Instituut Asbestslachtoffers.</p>","image_url":"","wiki_title":"Mesothelioma","match":"mesothelioom","option_only":true},"articulatio genus":{"title":"Kniegewricht (articulatio genus)","short":"Het kniegewricht is het gewricht tussen femur, tibia en patella, gestabiliseerd door kruisbanden, collaterale banden en menisci.","definition":"<p>De <strong>knie</strong> is vooral een scharniergewricht met in gebogen stand enige rotatie. De voorste kruisband voorkomt naar voren schuiven van de tibia, de achterste naar achteren; de collaterale banden geven zijdelingse stabiliteit. Letsels ontstaan vaak bij draaibewegingen in sport.</p>","image_url":"","wiki_title":"Knee","match":"articulatio genus|kniegewricht|knie","option_only":true},"articulatio acromioclavicularis":{"title":"Acromioclaviculair gewricht","short":"Het AC-gewricht verbindt het acromion met het laterale uiteinde van de clavicula.","definition":"<p>Een <strong>AC-luxatie</strong> ontstaat bij een val op de schouder; bij ernstige vormen zijn ook de coracoclaviculaire banden gescheurd en staat de clavicula hoog (pianotoetsfenomeen). Artrose van het AC-gewricht geeft pijn bovenop de schouder, vooral bij armheffen boven het hoofd.</p>","image_url":"","wiki_title":"Acromioclavicular joint","match":"articulatio acromioclavicularis|ac-gewricht|acromioclaviculair gewricht|ac-luxatie","option_only":true},"a. femoralis profunda":{"title":"A. profunda femoris","short":"De a. profunda femoris is de diepe tak van de a. femoralis die de spieren van het bovenbeen en via de aa. circumflexae de femurkop voorziet.","definition":"<p>De <strong>a. profunda femoris</strong> geeft perforerende takken af naar de achterzijde van het bovenbeen. Ze is een belangrijke collaterale route bij afsluiting van de a. femoralis superficialis.</p>","image_url":"","wiki_title":"Deep femoral artery","match":"a. femoralis profunda|a. profunda femoris","option_only":true},"os ischium":{"title":"Os ischii (zitbeen)","short":"Het os ischii is het onderste-achterste deel van het heupbeen, met de zitknobbel (tuber ischiadicum).","definition":"<p>Aan het <strong>tuber ischiadicum</strong> hechten de hamstrings aan; bij jonge sporters kan hier een avulsiefractuur ontstaan. Bij zitten draagt het tuber het lichaamsgewicht.</p>","image_url":"","wiki_title":"Ischium","match":"os ischium|os ischii|zitbeen|tuber ischiadicum","option_only":true},"malleolus medialis":{"title":"Malleolus medialis en lateralis","short":"De malleolus medialis (binnenenkel) hoort bij de tibia, de malleolus lateralis (buitenenkel) bij de fibula; samen vormen ze de enkelvork.","definition":"<p>De <strong>malleolus lateralis</strong> reikt verder naar beneden dan de medialis. Volgens de Ottawa-enkelregels is een röntgenfoto nodig bij drukpijn op de achterrand of punt van een malleolus of als de patiënt niet kan lopen.</p>","image_url":"","wiki_title":"Malleolus","match":"malleolus medialis|malleolus lateralis|laterale malleolus|mediale malleolus|enkelknobbel","option_only":true},"polymyalgia reumatica (pmr)":{"title":"Polymyalgia reumatica","short":"Polymyalgia reumatica is een ontstekingsziekte bij ouderen met pijn en stijfheid in schouder- en heupgordel.","definition":"<p><strong>Polymyalgia reumatica</strong> treft vooral mensen boven de 50, vaker vrouwen. Kenmerkend zijn ochtendstijfheid en pijn in nek, schouders en heupen, met moeite om op te staan of de armen te heffen, en een sterk verhoogde BSE/CRP. Er is geen echte spierzwakte. De ziekte reageert snel op lage dosis prednison en gaat soms samen met reuscelarteriitis.</p>","image_url":"","wiki_title":"Polymyalgia rheumatica","match":"polymyalgia reumatica (pmr)","option_only":true},"de achillespees":{"title":"Achillespees","short":"De achillespees is de sterkste pees van het lichaam; ze verbindt de kuitspieren met de calcaneus.","definition":"<p>Een <strong>achillespeesruptuur</strong> ontstaat vaak bij explosieve bewegingen bij mannen van middelbare leeftijd, soms door fluorochinolonen of corticosteroïden. Er is een knal, een palpabele delle en een positieve test van Thompson (geen plantairflexie bij knijpen in de kuit). Tendinopathie geeft pijn en zwelling enkele centimeters boven de aanhechting.</p>","image_url":"","wiki_title":"Achilles tendon","match":"de achillespees","option_only":true},"infectieuze artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"infectieuze artritis","option_only":true},"suppuratieve artritis":{"title":"Septische artritis","short":"Septische artritis is een bacteriële infectie van een gewricht (vaak S. aureus): acuut, pijnlijk, gezwollen, warm gewricht met koorts; een spoedgeval.","definition":"<p>Bij <strong>septische artritis</strong> raakt een gewricht geïnfecteerd, meestal via de bloedbaan, soms na een punctie of operatie. De meest voorkomende verwekker is <em>Staphylococcus aureus</em>; bij seksueel actieve jongvolwassenen ook <em>Neisseria gonorrhoeae</em>.</p><p>Het geeft een acuut rood, warm, gezwollen en zeer pijnlijk gewricht (vaak de knie) met bewegingsbeperking en meestal koorts. Diagnose door punctie (troebel synoviaal vocht met veel leukocyten, kweek). Snel draineren en antibiotica zijn nodig om kraakbeenvernietiging te voorkomen.</p>","image_url":"","wiki_title":"Septic arthritis","match":"suppuratieve artritis","option_only":true},"prevalentie":{"title":"Prevalentie","short":"Prevalentie is het aantal bestaande gevallen van een ziekte in een populatie op een bepaald moment of in een periode.","definition":"<p>De <strong>prevalentie</strong> hangt af van de incidentie (nieuwe gevallen) en de ziekteduur: prevalentie ≈ incidentie × duur. Een betere behandeling die mensen langer in leven houdt zonder ze te genezen, verhoogt dus de prevalentie. De voorspellende waarde van een test hangt sterk af van de prevalentie.</p>","image_url":"","wiki_title":"Prevalence","match":"prevalentie|puntprevalentie","option_only":true},"fysiotherapeut":{"title":"Fysiotherapeut","short":"Een fysiotherapeut behandelt klachten van het bewegingsapparaat en helpt mensen beter te bewegen, met oefentherapie, advies en manuele technieken.","definition":"<p><strong>Fysiotherapie</strong> wordt o.a. ingezet bij rug- en nekklachten, na operaties en blessures, bij artrose, COPD en na een beroerte. Het is direct toegankelijk, zonder verwijzing van de huisarts.</p>","image_url":"","wiki_title":"Physical therapy","match":"fysiotherapeut|fysiotherapie","option_only":true},"artroscopie":{"title":"Artroscopie","short":"Bij een artroscopie wordt een gewricht via kleine sneetjes met een camera bekeken en zo nodig behandeld.","definition":"<p><strong>Artroscopieën</strong> worden vooral gedaan aan knie, schouder en enkel, bijv. voor meniscus- of kruisbandletsel en losse delen. Bij degeneratieve knieklachten (artrose, degeneratieve meniscusscheur) heeft een artroscopie weinig meerwaarde.</p>","image_url":"","wiki_title":"Arthroscopy","match":"artroscopie|kijkoperatie van een gewricht","option_only":true},"werkloosheidwet (ww)":{"title":"Werkloosheidswet (WW)","short":"De Werkloosheidswet geeft werknemers die hun baan verliezen tijdelijk een uitkering.","definition":"<p>De <strong>WW</strong> is een werknemersverzekering, uitgevoerd door het UWV. Bij ziekte geldt de Ziektewet of loondoorbetaling door de werkgever, en na twee jaar ziekte eventueel de WIA.</p>","image_url":"","wiki_title":"","match":"werkloosheidwet (ww)|werkloosheidswet|ww","option_only":true},"enthoven stelsel":{"title":"Enthoven-stelsel","short":"Het Einthoven-stelsel beschrijft de drie standaard-extremiteitsafleidingen (I, II, III) van het ECG, die een driehoek vormen.","definition":"<p>Met de afleidingen I, II en III (en aVR, aVL, aVF) wordt de <strong>elektrische hartas</strong> in het frontale vlak bepaald. Einthoven ontving voor de uitvinding van het ECG de Nobelprijs.</p>","image_url":"","wiki_title":"Willem Einthoven","match":"enthoven stelsel|einthoven|einthoven-driehoek","option_only":true},"radiuskop fractuur":{"title":"Radiuskopfractuur","short":"Een radiuskopfractuur ontstaat na een val op de uitgestrekte hand, met pijn aan de buitenkant van de elleboog en beperkte draaibeweging.","definition":"<p>Bij een <strong>radiuskopfractuur</strong> is soms alleen een ‘fat pad sign’ (hydrops) op de foto te zien. De meeste worden met vroeg bewegen behandeld; verplaatste fracturen operatief.</p>","image_url":"","wiki_title":"Radial head fracture","match":"radiuskop fractuur|radiuskopfractuur","option_only":true},"olecranon fractuur":{"title":"Olecranonfractuur","short":"Een olecranonfractuur is een breuk van de punt van de elleboog, door een val op de gebogen elleboog.","definition":"<p>Bij een verplaatste <strong>olecranonfractuur</strong> trekt de m. triceps het fragment omhoog en is actief strekken niet mogelijk; meestal is operatieve fixatie nodig.</p>","image_url":"","wiki_title":"Olecranon fracture","match":"olecranon fractuur|olecranonfractuur","option_only":true},"ligamentum acromioclaviculare":{"title":"Ligamentum acromioclaviculare","short":"Het ligamentum acromioclaviculare verstevigt het kapsel van het AC-gewricht.","definition":"<p>Bij een lichte AC-luxatie is alleen het <strong>lig. acromioclaviculare</strong> beschadigd; bij ernstigere vormen ook de coracoclaviculaire banden.</p>","image_url":"","wiki_title":"Acromioclavicular ligament","match":"ligamentum acromioclaviculare","option_only":true},"scapula":{"title":"Scapula (schouderblad)","short":"De scapula is het driehoekige schouderblad, dat via de clavicula met de romp verbonden is.","definition":"<p>Aan de <strong>scapula</strong> hechten 17 spieren aan. Een scapulafractuur ontstaat door groot geweld en gaat vaak samen met letsel van borstkas en long.</p>","image_url":"","wiki_title":"Scapula","match":"scapula|schouderblad|scapula fractuur","option_only":true},"synthetisch botvulmateriaal":{"title":"Botvervangers en bottransplantaten","short":"Botdefecten kunnen worden opgevuld met eigen bot (autograft), donorbot (allograft) of synthetisch materiaal (bijv. calciumfosfaat).","definition":"<p>Een <strong>autograft</strong> bevat levende cellen en groeifactoren en geneest het best, maar geeft een extra wond. Allografts en synthetische materialen dienen als steiger waarlangs nieuw bot ingroeit (osteoconductie).</p>","image_url":"","wiki_title":"Bone grafting","match":"synthetisch botvulmateriaal|botgraft|biograft","option_only":true},"autoriteit consument en markt":{"title":"Autoriteit Consument & Markt (ACM)","short":"De ACM is de markttoezichthouder die o.a. toezicht houdt op mededinging, ook tussen zorgaanbieders en -verzekeraars.","definition":"<p>De <strong>ACM</strong> beoordeelt o.a. fusies van ziekenhuizen. De NZa houdt specifiek toezicht op de zorgmarkten en tarieven.</p>","image_url":"","wiki_title":"","match":"autoriteit consument en markt|acm","option_only":true},"integratie":{"title":"Integratie (acculturatie)","short":"Integratie is de acculturatiestrategie waarbij iemand de eigen cultuur behoudt én contact zoekt met de nieuwe cultuur.","definition":"<p>In het <strong>model van Berry</strong> gaat integratie meestal samen met het beste welzijn; andere strategieën zijn assimilatie, separatie en marginalisatie.</p>","image_url":"","wiki_title":"","match":"integratie","option_only":true},"a. obturatoria":{"title":"A. obturatoria","short":"De a. obturatoria is een tak van de a. iliaca interna die met de n. obturatorius door het canalis obturatorius naar de adductoren loopt.","definition":"<p>Een variant waarbij de <strong>a. obturatoria</strong> uit de a. epigastrica inferior komt (‘corona mortis’) kan bij lies- en bekkenoperaties tot ernstige bloedingen leiden.</p>","image_url":"","wiki_title":"Obturator artery","match":"a. obturatoria","option_only":true},"ligamentum tibiofibulare":{"title":"Syndesmose (lig. tibiofibulare)","short":"De syndesmose verbindt tibia en fibula vlak boven de enkel en houdt de enkelvork stabiel.","definition":"<p>Een <strong>syndesmoseletsel</strong> (‘hoge enkelverstuiking’) ontstaat bij exorotatie van de voet en herstelt trager dan een gewone enkelverstuiking. Bij instabiliteit (Weber C-fracturen) is operatieve fixatie nodig.</p>","image_url":"","wiki_title":"Syndesmosis","match":"ligamentum tibiofibulare|syndesmose","option_only":true},"botscintigrafie":{"title":"Botscan (skeletscintigrafie)","short":"Een botscan toont met een radioactieve stof plaatsen met verhoogde botombouw, zoals metastasen, fracturen en infecties.","definition":"<p>Een <strong>botscan</strong> is gevoelig maar weinig specifiek. Hij wordt vooral gebruikt bij verdenking op botmetastasen (o.a. prostaat- en borstkanker) en occulte stressfracturen. Bij een multipel myeloom is de scan vaak negatief, omdat er weinig osteoblastactiviteit is.</p>","image_url":"","wiki_title":"Bone scintigraphy","match":"botscintigrafie|botscan","option_only":true},"wet publieke gezondheid (wpg)":{"title":"Wet publieke gezondheid (Wpg)","short":"De Wet publieke gezondheid regelt de taken van gemeenten en GGD's, o.a. infectieziektebestrijding, jeugdgezondheidszorg en ouderengezondheidszorg.","definition":"<p>Onder de <strong>Wpg</strong> vallen de meldingsplicht voor infectieziekten (groepen A, B en C), bron- en contactonderzoek en de maatregelen die de burgemeester kan nemen bij uitbraken.</p>","image_url":"","wiki_title":"","match":"wet publieke gezondheid (wpg)|wet publieke gezondheid|wpg","option_only":true},"beroepsastma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"beroepsastma|door werk verergerd astma","option_only":true},"correctie osteotomie":{"title":"Correctieosteotomie","short":"Bij een correctieosteotomie wordt een bot doorgezaagd en in een betere stand vastgezet, om een standsafwijking te corrigeren.","definition":"<p>Een <strong>osteotomie</strong> wordt o.a. gedaan bij een O- of X-beenstand met beginnende knieartrose (om de belasting naar het gezonde compartiment te verplaatsen) en bij scheef genezen fracturen.</p>","image_url":"","wiki_title":"Osteotomy","match":"correctie osteotomie|correctieosteotomie|osteotomie","option_only":true},"stress fractuur":{"title":"Stressfractuur","short":"Een stressfractuur ontstaat door herhaalde overbelasting van een bot, bijvoorbeeld bij hardlopers of rekruten.","definition":"<p><strong>Stressfracturen</strong> zitten vaak in de middenvoetsbeentjes (marsfractuur), tibia of collum femoris. Op de eerste röntgenfoto zijn ze vaak niet zichtbaar; MRI of een botscan toont ze eerder. Bij vrouwelijke sporters moet aan een energietekort met amenorroe en lage botdichtheid worden gedacht.</p>","image_url":"","wiki_title":"Stress fracture","match":"stress fractuur|stressfractuur|marsfractuur","option_only":true},"osteonecrose":{"title":"Osteonecrose (avasculaire necrose)","short":"Osteonecrose is afsterven van botweefsel door een onderbroken bloedvoorziening, vaak in de femurkop.","definition":"<p>Risicofactoren voor <strong>avasculaire necrose</strong> zijn corticosteroïden, alcohol, een mediale collumfractuur of heupluxatie, sikkelcelziekte en duikziekte. Later zakt het bot in, met secundaire artrose. Bisfosfonaten en denosumab kunnen zelden osteonecrose van de kaak geven.</p>","image_url":"","wiki_title":"Avascular necrosis","match":"osteonecrose|avasculaire necrose|osteonecrose van de kaak","option_only":true},"subchondrale sclerose":{"title":"Röntgenkenmerken van artrose","short":"De klassieke röntgenkenmerken van artrose zijn gewrichtsspleetversmalling, osteofyten, subchondrale sclerose en subchondrale cysten.","definition":"<p>Bij <strong>artrose</strong> is de gewrichtsspleet asymmetrisch versmald op de meest belaste plek. Bij ontstekingsziekten zoals reumatoïde artritis zijn er juist symmetrische versmalling, periarticulaire osteoporose en erosies, zonder osteofyten.</p>","image_url":"","wiki_title":"Osteoarthritis","match":"subchondrale sclerose|subchondrale cysten|gewrichtspleet versmalling|osteofytvorming|osteofyten","option_only":true},"zondagsarmpje":{"title":"Zondagsarmpje (pronatio dolorosa)","short":"Een zondagsarmpje is een subluxatie van de radiuskop bij jonge kinderen, na trekken aan de gestrekte arm.","definition":"<p>Het kind (meestal 1–5 jaar) houdt bij een <strong>zondagsarmpje</strong> de arm in pronatie langs het lichaam en wil hem niet gebruiken. Repositie door supinatie en flexie (of hyperpronatie) geeft direct herstel.</p>","image_url":"","wiki_title":"Pulled elbow","match":"zondagsarmpje|pronatio dolorosa|nursemaid's elbow","option_only":true},"artrolyse":{"title":"Artrolyse","short":"Bij een artrolyse worden verklevingen in een stijf gewricht chirurgisch losgemaakt om de beweeglijkheid te verbeteren.","definition":"<p>Een <strong>artrolyse</strong> wordt o.a. gedaan bij een stijve elleboog of knie na trauma of operatie, open of artroscopisch, gevolgd door intensieve oefentherapie.</p>","image_url":"","wiki_title":"","match":"artrolyse","option_only":true},"reumanoduli":{"title":"Reumanoduli","short":"Reumanoduli zijn stevige, pijnloze knobbels onder de huid, vaak aan de strekzijde van de onderarm, bij reumatoïde artritis.","definition":"<p><strong>Reumanoduli</strong> komen vooral voor bij seropositieve, ernstigere reumatoïde artritis. Ze kunnen ook in longen en andere organen voorkomen. Methotrexaat kan juist de vorming van kleine noduli bevorderen.</p>","image_url":"","wiki_title":"Rheumatoid nodule","match":"reumanoduli|reumaknobbels","option_only":true},"de test van mcmurray":{"title":"Test van McMurray","short":"De test van McMurray onderzoekt meniscusletsel door de knie onder rotatie te buigen en te strekken; een klik of pijn op de gewrichtsspleet is positief.","definition":"<p>De <strong>McMurray-test</strong> is matig betrouwbaar. Een combinatie van anamnese (draaitrauma, slotklachten) en lichamelijk onderzoek, eventueel aangevuld met MRI, geeft meer zekerheid.</p>","image_url":"","wiki_title":"McMurray test","match":"de test van mcmurray|test van mcmurray|mcmurray","option_only":true},"plasmodium ovale":{"title":"Plasmodium vivax en ovale","short":"P. vivax en P. ovale veroorzaken een mildere malaria, maar kunnen slapende vormen (hypnozoïeten) in de lever achterlaten, met recidieven.","definition":"<p>Na behandeling van <strong>vivax- of ovalemalaria</strong> wordt primaquine gegeven om de hypnozoïeten te doden (eerst G6PD-deficiëntie uitsluiten). <em>P. knowlesi</em> komt uit Zuidoost-Azië (apen) en kan ernstig verlopen.</p>","image_url":"","wiki_title":"Plasmodium vivax","match":"plasmodium ovale|plasmodium vivax|plasmodium knowlesi","option_only":true},"wet individuele gezondheidszorg":{"title":"Wet BIG","short":"De Wet BIG regelt beroepen in de individuele gezondheidszorg: registratie, titelbescherming, voorbehouden handelingen en tuchtrecht.","definition":"<p>Onder de <strong>Wet BIG</strong> mogen alleen bevoegde zorgverleners voorbehouden handelingen (bijv. operaties, injecties, voorschrijven) zelfstandig verrichten. Artsen moeten in het BIG-register staan en zich elke vijf jaar herregistreren.</p>","image_url":"","wiki_title":"","match":"wet individuele gezondheidszorg|wet big|big-register","option_only":true},"aneurysma a. poplitea":{"title":"Aneurysma van de a. poplitea","short":"Een aneurysma van de a. poplitea is een verwijding van de knieholteslagader, het meest voorkomende perifere aneurysma.","definition":"<p>Een <strong>popliteaal aneurysma</strong> is vaak dubbelzijdig en gaat vaak samen met een aneurysma van de aorta abdominalis. Het scheurt zelden, maar geeft trombose en embolieën naar het onderbeen, met acute ischemie.</p>","image_url":"","wiki_title":"Popliteal artery aneurysm","match":"aneurysma a. poplitea|popliteaal aneurysma","option_only":true},"crista iliaca":{"title":"Crista iliaca (bekkenkam)","short":"De crista iliaca is de bovenrand van het os ilium, goed voelbaar in de flank.","definition":"<p>Een lijn tussen beide <strong>cristae iliacae</strong> (lijn van Tuffier) loopt ongeveer ter hoogte van L4, een oriëntatiepunt bij lumbaalpuncties. De bekkenkam wordt gebruikt voor beenmergonderzoek en als bron van botgrafts.</p>","image_url":"","wiki_title":"Iliac crest","match":"crista iliaca|bekkenkam","option_only":true},"m. biceps brachii":{"title":"M. biceps brachii","short":"De m. biceps brachii buigt de elleboog en is een sterke supinator van de onderarm.","definition":"<p>De <strong>biceps</strong> heeft een lange kop (van boven de kom) en korte kop (van het processus coracoideus) en hecht aan de tuberositas radii. Een scheur van de lange kop geeft een ‘Popeye’-bult; een distale ruptuur verzwakt de supinatie. Bicepspeesreflex: C5–C6. Innervatie: n. musculocutaneus.</p>","image_url":"","wiki_title":"Biceps","match":"m. biceps brachii|musculus biceps brachii|biceps","option_only":true},"m. triceps brachii":{"title":"M. triceps brachii","short":"De m. triceps brachii is de strekker van de elleboog, geïnnerveerd door de n. radialis.","definition":"<p>De <strong>triceps</strong> hecht aan het olecranon. De tricepspeesreflex test C7. Bij een letsel van de n. radialis hoog in de oksel is de triceps ook zwak; bij een letsel ter hoogte van de humerusschacht meestal niet.</p>","image_url":"","wiki_title":"Triceps","match":"m. triceps brachii|musculus triceps brachii|triceps","option_only":true},"m. brachialis":{"title":"M. brachialis en m. coracobrachialis","short":"De m. brachialis is de belangrijkste buiger van de elleboog; de m. coracobrachialis helpt bij anteflexie en adductie van de arm.","definition":"<p>Beide spieren worden geïnnerveerd door de n. musculocutaneus. De <strong>m. brachialis</strong> hecht aan de ulna en buigt in elke stand van de onderarm.</p>","image_url":"","wiki_title":"Brachialis muscle","match":"m. brachialis|m. coracobrachialis","option_only":true},"m. gluteus maximus":{"title":"M. gluteus maximus","short":"De m. gluteus maximus is de grote bilspier, de belangrijkste strekker van de heup.","definition":"<p>De <strong>m. gluteus maximus</strong> is vooral actief bij opstaan, traplopen en rennen. Innervatie: n. gluteus inferior. Intramusculaire injecties in de bil worden in het bovenste-buitenste kwadrant gegeven om de n. ischiadicus te sparen.</p>","image_url":"","wiki_title":"Gluteus maximus","match":"m. gluteus maximus|musculus gluteus maximus","option_only":true},"m. semimembranosus":{"title":"Hamstrings","short":"De hamstrings (m. semimembranosus, semitendinosus en biceps femoris) strekken de heup en buigen de knie.","definition":"<p>Verrekking van de <strong>hamstrings</strong> komt veel voor bij sprinters. De pezen worden ook gebruikt als transplantaat bij een voorste kruisbandreconstructie. Innervatie: n. ischiadicus.</p>","image_url":"","wiki_title":"Hamstring","match":"m. semimembranosus|m. semitendinosus|hamstrings","option_only":true},"m. adductor longus":{"title":"M. adductor longus","short":"De m. adductor longus is een van de adductoren van de heup, geïnnerveerd door de n. obturatorius.","definition":"<p>Overbelasting van de <strong>adductoren</strong> (liesblessure) komt veel voor bij voetballers, met pijn aan de binnenkant van de lies bij adductie tegen weerstand.</p>","image_url":"","wiki_title":"Adductor longus muscle","match":"m. adductor longus","option_only":true},"m. plantaris":{"title":"M. plantaris","short":"De m. plantaris is een kleine kuitspier met een lange, dunne pees; bij een deel van de mensen ontbreekt hij.","definition":"<p>Een scheur van de <strong>m. plantaris</strong> kan plotselinge kuitpijn geven, maar is functioneel weinig belangrijk. De pees wordt soms als transplantaat gebruikt.</p>","image_url":"","wiki_title":"Plantaris muscle","match":"m. plantaris","option_only":true},"m. abductor pollicis longus":{"title":"M. abductor pollicis longus en m. extensor pollicis brevis","short":"Deze twee duimspieren lopen samen door het eerste dorsale compartiment van de pols; ontsteking van hun peesschede heet tendovaginitis van De Quervain.","definition":"<p>De <strong>m. abductor pollicis longus</strong> abduceert de duim; de <strong>m. extensor pollicis brevis</strong> strekt het basisgewricht. Samen begrenzen ze de anatomische snuifdoos aan de duimzijde. Innervatie: n. radialis (r. profundus).</p>","image_url":"","wiki_title":"Abductor pollicis longus muscle","match":"m. abductor pollicis longus|m. extensor pollicis brevis","option_only":true},"m. extensor carpi ulnaris":{"title":"Extensoren van de onderarm","short":"De extensoren van pols en vingers liggen aan de achterkant van de onderarm en worden geïnnerveerd door de n. radialis.","definition":"<p>Tot de <strong>extensoren</strong> behoren o.a. de m. extensor carpi radialis longus en brevis, m. extensor carpi ulnaris, m. extensor digitorum, m. extensor indicis en m. extensor digiti minimi. Ze ontspringen grotendeels aan de laterale epicondyl (tenniselleboog).</p>","image_url":"","wiki_title":"Extensor carpi ulnaris muscle","match":"m. extensor carpi ulnaris|m. extensor indicis|m. extensor digiti minimi","option_only":true},"lunatomalacie (ziekte van kienböck)":{"title":"Ziekte van Kienböck","short":"Bij de ziekte van Kienböck sterft het os lunatum af door een verstoorde bloedvoorziening, met polspijn en stijfheid.","definition":"<p>De <strong>ziekte van Kienböck</strong> komt vooral bij jonge mannen met zware handarbeid voor en vaker bij een relatief korte ulna. Het lunatum zakt in, met later artrose van de pols.</p>","image_url":"","wiki_title":"Kienböck's disease","match":"lunatomalacie (ziekte van kienböck)|ziekte van kienböck|lunatomalacie","option_only":true},"habituele patellaluxatie":{"title":"Patellaluxatie","short":"Bij een patellaluxatie schiet de knieschijf naar buiten uit de groeve; bij een habituele vorm gebeurt dat herhaaldelijk.","definition":"<p><strong>Patellaluxaties</strong> komen vooral voor bij jonge vrouwen, met risicofactoren als een ondiepe trochleagroeve, een hoogstaande patella en losse banden. Na de eerste luxatie is vaak het mediale patellofemorale ligament gescheurd; bij herhaling volgt soms een operatie.</p>","image_url":"","wiki_title":"Patellar dislocation","match":"habituele patellaluxatie|patellaluxatie|knieschijfluxatie","option_only":true},"totale knie prothese":{"title":"Totale knieprothese","short":"Bij een totale knieprothese worden de gewrichtsvlakken van femur en tibia (en soms patella) vervangen door metaal en kunststof.","definition":"<p>Een <strong>knieprothese</strong> wordt geplaatst bij ernstige artrose die niet meer reageert op conservatieve behandeling. Complicaties zijn infectie, trombose, stijfheid en loslating op termijn.</p>","image_url":"","wiki_title":"Knee replacement","match":"totale knie prothese|totale knieprothese|tkp|heupprothese|arthroplastiek","option_only":true},"bakerse cyste":{"title":"Bakercyste","short":"Een bakercyste is een met gewrichtsvocht gevulde zwelling in de knieholte, vaak bij artrose of meniscusletsel.","definition":"<p>Een <strong>bakercyste</strong> staat in verbinding met het kniegewricht. Als ze scheurt, loopt vocht de kuit in, met een pijnlijke, gezwollen kuit die op een trombosebeen kan lijken.</p>","image_url":"","wiki_title":"Baker's cyst","match":"bakerse cyste|bakercyste|bakerse cyste|poplitea-cyste","option_only":true},"silicose":{"title":"Silicose","short":"Silicose is een longfibrose door het langdurig inademen van kwartsstof, bijv. in de bouw, mijnbouw en steenbewerking.","definition":"<p>Bij <strong>silicose</strong> ontstaan kleine knobbeltjes in de bovenvelden en verkalkte hilusklieren (eierschaalverkalking). Er is een verhoogd risico op tuberculose en longkanker. Het is een beroepsziekte.</p>","image_url":"","wiki_title":"Silicosis","match":"silicose","option_only":true},"asbestose":{"title":"Asbestose","short":"Asbestose is longfibrose door het inademen van asbestvezels, vooral in de ondervelden.","definition":"<p>Naast <strong>asbestose</strong> geeft asbestblootstelling pleurale plaques (zonder klachten), pleuravocht, mesothelioom en longkanker (sterk versterkt door roken). De latentietijd is vaak tientallen jaren.</p>","image_url":"","wiki_title":"Asbestosis","match":"asbestose","option_only":true},"universele preventie":{"title":"Universele preventie","short":"Universele preventie richt zich op de hele bevolking of een grote groep, ongeacht risico, zoals vaccinatie of voorlichting aan alle scholieren.","definition":"<p>De indeling van preventie naar doelgroep is: <strong>universeel</strong> (iedereen), selectief (risicogroepen), geïndiceerd (mensen met beginnende klachten) en zorggerelateerd (mensen met een ziekte).</p>","image_url":"","wiki_title":"","match":"universele preventie","option_only":true},"voorste enkelbandletsel":{"title":"Enkelverstuiking (inversietrauma)","short":"Bij een enkelverstuiking door inversie scheurt meestal eerst het lig. talofibulare anterius, soms ook het lig. calcaneofibulare.","definition":"<p>Een <strong>enkeldistorsie</strong> is een van de meest voorkomende sportblessures. Met de Ottawa-enkelregels wordt bepaald of een foto nodig is. Na 4–5 dagen is het onderzoek (voorste schuiflade, drukpijn, hematoom) betrouwbaarder. Behandeling: functioneel, met een brace of tape en oefentherapie.</p>","image_url":"","wiki_title":"Sprained ankle","match":"voorste enkelbandletsel|enkelverstuiking|enkeldistorsie|inversietrauma","option_only":true},"enkeldislocatie":{"title":"Enkelluxatie","short":"Bij een enkelluxatie is de talus uit de enkelvork geschoten, meestal samen met fracturen van de malleoli.","definition":"<p>Een <strong>enkelluxatie</strong> moet snel worden gereponeerd om de huid en de doorbloeding van de voet te sparen, waarna meestal operatieve fixatie volgt.</p>","image_url":"","wiki_title":"Ankle dislocation","match":"enkeldislocatie|enkelluxatie|polsluxatie","option_only":true},"diabetische neuropathie":{"title":"Diabetische neuropathie","short":"Diabetische neuropathie is zenuwschade door langdurig hoge bloedglucose, meestal als symmetrische polyneuropathie in de voeten.","definition":"<p>Bij <strong>diabetische neuropathie</strong> ontstaat verlies van gevoel (risico op ongemerkte wondjes en voetulcera), pijn en tintelingen, en soms autonome neuropathie (orthostatische hypotensie, gastroparese, erectiestoornissen). Jaarlijkse voetcontrole met een monofilament is belangrijk.</p>","image_url":"","wiki_title":"Diabetic neuropathy","match":"diabetische neuropathie|diabetische voet","option_only":true},"valgustest":{"title":"Valgustest (knie)","short":"Met de valgustest wordt het mediale collaterale ligament van de knie onderzocht door de onderbeen naar buiten te duwen.","definition":"<p>De <strong>valgustest</strong> wordt in 0° en 30° flexie gedaan; laxiteit in volledige strekking wijst op bijkomend letsel van de kruisbanden. De varustest onderzoekt het laterale collaterale ligament.</p>","image_url":"","wiki_title":"","match":"valgustest|valgusstresstest|varustest","option_only":true},"jumper's knee":{"title":"Jumper's knee (patellapeestendinopathie)","short":"Jumper's knee is een overbelasting van de patellapees, met pijn net onder de knieschijf, vooral bij springsporten.","definition":"<p>Bij <strong>patellatendinopathie</strong> is er drukpijn op de onderpool van de patella en pijn bij springen en traplopen. Behandeling met belastingsmanagement en (excentrische) krachttraining.</p>","image_url":"","wiki_title":"Patellar tendinitis","match":"jumper's knee|patellapeestendinopathie|patellatendinopathie|voetbal knie","option_only":true},"gemeente":{"title":"Gemeente (in de zorg)","short":"De gemeente is verantwoordelijk voor o.a. de Wmo, jeugdhulp, de Participatiewet en de publieke gezondheid (via de GGD).","definition":"<p>Sinds de decentralisaties van 2015 heeft de <strong>gemeente</strong> een grote rol in ondersteuning thuis (Wmo), jeugdhulp (Jeugdwet) en werk en inkomen (Participatiewet).</p>","image_url":"","wiki_title":"","match":"gemeente","option_only":true},"centraal administratiekantoor (cak)":{"title":"CAK (Centraal Administratiekantoor)","short":"Het CAK int de eigen bijdragen voor zorg uit de Wlz en de Wmo.","definition":"<p>Het <strong>CAK</strong> berekent en int de eigen bijdrage op basis van inkomen en vermogen, en voert enkele andere regelingen uit, zoals die voor wanbetalers van de zorgverzekering.</p>","image_url":"","wiki_title":"","match":"centraal administratiekantoor (cak)|cak","option_only":true},"bedrijfsarts":{"title":"Bedrijfsarts","short":"De bedrijfsarts begeleidt werknemers bij ziekte en re-integratie en adviseert over gezond en veilig werken.","definition":"<p>De <strong>bedrijfsarts</strong> adviseert werkgever en werknemer over verzuim en re-integratie (Wet verbetering poortwachter), stelt beroepsziekten vast en meldt die, en doet preventieve onderzoeken. Medische informatie deelt de bedrijfsarts niet met de werkgever.</p>","image_url":"","wiki_title":"","match":"bedrijfsarts|bedrijfsgeneeskunde","option_only":true},"huis van werkvermogen":{"title":"Huis van werkvermogen","short":"Het huis van werkvermogen (Ilmarinen) beschrijft werkvermogen als een huis met vier verdiepingen: gezondheid, competenties, waarden en het werk zelf.","definition":"<p>Het model laat zien dat <strong>werkvermogen</strong> afhangt van de balans tussen wat iemand kan en wil, en wat het werk vraagt, met invloed van familie en omgeving.</p>","image_url":"","wiki_title":"","match":"huis van werkvermogen","option_only":true},"optometrist":{"title":"Optometrist","short":"Een optometrist meet en beoordeelt het gezichtsvermogen en kan oogaandoeningen signaleren en eenvoudige afwijkingen vervolgen.","definition":"<p>Een <strong>optometrist</strong> doet o.a. oogmetingen, fundusfoto's en oogdrukmetingen en verwijst zo nodig naar de oogarts.</p>","image_url":"","wiki_title":"","match":"optometrist","option_only":true},"gedragsintentie":{"title":"Gedragsintentie","short":"In de theorie van gepland gedrag is de intentie de belangrijkste voorspeller van gedrag; ze wordt bepaald door attitude, sociale norm en waargenomen gedragscontrole.","definition":"<p>De <strong>attitude</strong> is de eigen evaluatie van het gedrag (voor- en nadelen), de subjectieve norm wat belangrijke anderen vinden, en waargenomen gedragscontrole of iemand denkt het gedrag te kunnen uitvoeren (vergelijkbaar met eigen-effectiviteit).</p>","image_url":"","wiki_title":"Theory of planned behavior","match":"gedragsintentie|attitude","option_only":true},"test-hertestbetrouwbaarheid":{"title":"Test-hertestbetrouwbaarheid","short":"Test-hertestbetrouwbaarheid is de mate waarin een meting bij herhaling onder dezelfde omstandigheden hetzelfde resultaat geeft.","definition":"<p>Voor <strong>test-hertestbetrouwbaarheid</strong> moet de tijd tussen de metingen lang genoeg zijn om herinnering te voorkomen, maar kort genoeg dat de eigenschap niet verandert. Voor continue uitkomsten wordt vaak de ICC gebruikt.</p>","image_url":"","wiki_title":"Repeatability","match":"test-hertestbetrouwbaarheid","option_only":true},"geschillencommissie":{"title":"Geschillencommissie zorg","short":"Een geschillencommissie doet een bindende uitspraak bij een klacht over zorg die niet naar tevredenheid is opgelost, en kan een schadevergoeding toekennen.","definition":"<p>Onder de <strong>Wkkgz</strong> moet elke zorgaanbieder een klachtenfunctionaris hebben en aangesloten zijn bij een erkende geschillencommissie. Die kan een schadevergoeding tot een maximumbedrag toekennen.</p>","image_url":"","wiki_title":"","match":"geschillencommissie|klachtenfunctionaris van het ziekenhuis","option_only":true},"patiëntgerichtheid":{"title":"Patiëntgerichtheid","short":"Patiëntgerichte zorg houdt rekening met de wensen, waarden en situatie van de patiënt en betrekt hem actief bij beslissingen.","definition":"<p>Kenmerken van <strong>patiëntgerichte zorg</strong> zijn respect voor voorkeuren, goede informatie, gedeelde besluitvorming, aandacht voor lichamelijk comfort en emotionele steun, en betrokkenheid van naasten.</p>","image_url":"","wiki_title":"Patient-centered care","match":"patiëntgerichtheid|patiëntgerichte zorg|patientgerichtheid","option_only":true},"patientveiligheid":{"title":"Patiëntveiligheid","short":"Patiëntveiligheid is het voorkomen van onbedoelde schade aan patiënten door de zorg.","definition":"<p>Bij <strong>patiëntveiligheid</strong> gaat het om het melden en analyseren van incidenten (bijv. met SIRE of PRISMA), het systeemdenken van Reason en maatregelen zoals checklists, time-outs en medicatieverificatie.</p>","image_url":"","wiki_title":"Patient safety","match":"patientveiligheid|patiëntveiligheid","option_only":true},"clavicula fractuur":{"title":"Claviculafractuur","short":"Een claviculafractuur is een breuk van het sleutelbeen, meestal in het middelste derde na een val op de schouder.","definition":"<p><strong>Claviculafracturen</strong> komen veel voor bij kinderen en jongvolwassenen. Het mediale fragment wordt door de m. sternocleidomastoideus omhoog getrokken. De meeste genezen goed met een mitella; bij grote verplaatsing of verkorting kan operatie nodig zijn. Zelden raken de onderliggende vaten of plexus brachialis beschadigd.</p>","image_url":"","wiki_title":"Clavicle fracture","match":"clavicula fractuur","option_only":true},"tuberculose (mycobacterium tuberculosis)":{"title":"Tuberculose","short":"Tuberculose is een infectie met Mycobacterium tuberculosis, meestal in de longen, met langdurig hoesten, nachtzweten, gewichtsverlies en granulomen.","definition":"<p><strong>Tuberculose</strong> wordt veroorzaakt door <em>Mycobacterium tuberculosis</em> en verspreidt zich via aerosolen. Na infectie wordt de bacterie meestal ingekapseld in granulomen (latente tbc); bij verminderde afweer kan actieve ziekte ontstaan.</p><p>Longtuberculose geeft langdurig hoesten (soms met bloed), koorts, nachtzweten en gewichtsverlies; typisch zijn holtevorming in de longtoppen en granulomen met centrale <em>verkazing</em>. Behandeling met een combinatie van tuberculostatica gedurende minstens 6 maanden.</p>","image_url":"","wiki_title":"Tuberculosis","match":"tuberculose (mycobacterium tuberculosis)","option_only":true},"malaria tropica":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malaria tropica","option_only":true},"plasmodium falciparum-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium falciparum-malaria","option_only":true},"plasmodium vivax-malaria":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium vivax-malaria","option_only":true},"plasmodium spp":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"plasmodium spp","option_only":true},"malariaparasiet":{"title":"Malaria","short":"Malaria is een door muggen overgedragen parasitaire infectie (Plasmodium) van de rode bloedcellen, met koortsaanvallen; P. falciparum kan levensbedreigend zijn.","definition":"<p><strong>Malaria</strong> wordt veroorzaakt door <em>Plasmodium</em>-parasieten (o.a. <em>P. falciparum</em>, <em>P. vivax</em>) en overgebracht door de <em>Anopheles</em>-mug. De parasiet vermenigvuldigt zich eerst in de lever en daarna in rode bloedcellen.</p><p>Het uiteenvallen van geïnfecteerde erytrocyten geeft koortsaanvallen, hemolytische anemie en splenomegalie. <em>P. falciparum</em> kan cerebrale malaria en orgaanfalen geven. Diagnose met een dikke druppel/uitstrijk of sneltest; koorts na tropenreis is malaria tot het tegendeel bewezen is.</p>","image_url":"","wiki_title":"Malaria","match":"malariaparasiet","option_only":true},"astma-aanval":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-aanval","option_only":true},"astma-exacerbatie":{"title":"Astma","short":"Astma is een chronische ontsteking van de luchtwegen met wisselende, reversibele luchtwegobstructie en hyperreactiviteit; klachten zijn piepen, benauwdheid en hoesten.","definition":"<p>Bij <strong>astma</strong> zijn de luchtwegen chronisch ontstoken (vaak eosinofiel/Th2-gemedieerd) en <em>hyperreactief</em>: op prikkels zoals allergenen, inspanning, koude lucht of rook ontstaan bronchoconstrictie, slijmvliesoedeem en slijmproductie.</p><p>De obstructie is variabel en grotendeels <em>reversibel</em> (verbetering van de FEV1 na een luchtwegverwijder). Klachten: aanvallen van piepen, kortademigheid, een beklemd gevoel op de borst en hoesten, vaak ’s nachts. Behandeling met inhalatiecorticosteroïden en luchtwegverwijders.</p>","image_url":"","wiki_title":"Asthma","match":"astma-exacerbatie","option_only":true},"iliaca externa":{"title":"A. iliaca externa","short":"De a. iliaca externa loopt van de splitsing van de a. iliaca communis naar het lig. inguinale, waar ze a. femoralis gaat heten.","definition":"<p>De <strong>a. iliaca externa</strong> loopt langs de m. psoas en geeft vlak boven het lig. inguinale de a. epigastrica inferior en de a. circumflexa ilium profunda af. Bij een niertransplantatie wordt de donornier vaak op deze arterie aangesloten.</p>","image_url":"","wiki_title":"External iliac artery","match":"iliaca externa","option_only":true},"meningococcen b":{"title":"Neisseria meningitidis (meningokok)","short":"De meningokok is een gramnegatieve diplokok die meningitis en een snel fataal verlopende sepsis met petechiën kan veroorzaken.","definition":"<p><strong><em>Neisseria meningitidis</em></strong> koloniseert de nasofarynx en wordt via druppels overgedragen. Het kapsel en endotoxine (LOS) maken hem zeer virulent. Een invasieve infectie geeft meningitis en/of een fulminante sepsis met petechiën en purpura (soms met bijnierbloedingen). Er wordt gevaccineerd tegen serogroepen ACWY en B; contacten krijgen profylaxe.</p>","image_url":"","wiki_title":"Neisseria meningitidis","match":"meningococcen b","option_only":true},"anterieure schouderdislocatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"anterieure schouderdislocatie","option_only":true},"een anterieure schouderluxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"een anterieure schouderluxatie","option_only":true},"anterieure glenohumerale luxatie":{"title":"Schouderluxatie","short":"Bij een schouderluxatie schiet de humeruskop uit de kom, meestal naar voren-onder.","definition":"<p>Bij een <strong>anterieure schouderluxatie</strong> (verreweg het meest voorkomend) staat de arm in lichte abductie en exorotatie, met een afgeplatte schouderronding en een leeg gevoel onder het acromion. Controleer altijd de n. axillaris (gevoel op de schouder). Bij jongeren is recidief luxeren vaak; bij ouderen komen cuffscheuren voor. Posterieure luxaties komen voor bij epileptische aanvallen en elektrocutie.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"anterieure glenohumerale luxatie","option_only":true},"posterieure schouderdislocatie":{"title":"Posterieure schouderluxatie","short":"Een posterieure schouderluxatie is een ontwrichting van de humeruskop naar achteren, vaak na een epileptische aanval of elektrocutie.","definition":"<p>Bij een <strong>posterieure luxatie</strong> staat de arm in endorotatie en kan hij niet naar buiten worden gedraaid. Op een gewone voorachterwaartse foto wordt ze makkelijk gemist (‘lightbulb sign’); een axiale opname is nodig.</p>","image_url":"","wiki_title":"Dislocated shoulder","match":"posterieure schouderdislocatie","option_only":true},"humerus fractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"humerus fractuur","option_only":true},"subcapitale humerusfractuur":{"title":"Humerusfractuur","short":"Een humerusfractuur is een breuk van het opperarmbeen; proximaal vooral bij ouderen, in de schacht met risico op letsel van de n. radialis.","definition":"<p><strong>Proximale humerusfracturen</strong> komen vooral bij oudere vrouwen met osteoporose voor en worden vaak conservatief behandeld. Bij een fractuur van het collum chirurgicum kan de n. axillaris beschadigd raken, bij een schachtfractuur de n. radialis (dropshand) en bij een suprachondylaire fractuur bij kinderen de a. brachialis en n. medianus.</p>","image_url":"","wiki_title":"Humerus fracture","match":"subcapitale humerusfractuur","option_only":true},"elleboog luxatie":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"elleboog luxatie","option_only":true},"luxatie van het ellebooggewricht":{"title":"Elleboogluxatie","short":"Bij een elleboogluxatie schieten ulna en radius uit het gewricht met de humerus, meestal naar achteren.","definition":"<p>Een <strong>posterieure elleboogluxatie</strong> ontstaat bij een val op de uitgestrekte arm. Controleer altijd de doorbloeding (a. brachialis) en de zenuwen (n. ulnaris, n. medianus). Bij jonge kinderen komt vooral de ‘zondagsarmpje’-subluxatie van de radiuskop voor, door trekken aan de gestrekte arm.</p>","image_url":"","wiki_title":"Elbow dislocation","match":"luxatie van het ellebooggewricht","option_only":true},"open boekletsel":{"title":"Open-boekfractuur van het bekken","short":"Bij een open-boekfractuur van het bekken klappen beide bekkenhelften vooraan open, met scheuring van de symfyse en risico op levensbedreigend bloedverlies.","definition":"<p>De <strong>open-boekfractuur</strong> ontstaat door een anteroposterieure klap. Het bekkenvolume neemt toe en veneuze plexussen kunnen hevig bloeden. Een bekkenband die de bekkenring sluit is een belangrijke eerste maatregel; daarna eventueel embolisatie of externe fixatie.</p>","image_url":"","wiki_title":"Pelvic fracture","match":"open boekletsel","option_only":true},"lig. talofibulare posterior (tfp)":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulare posterior (tfp)","option_only":true},"lig. talofibulare posterior":{"title":"Ligamentum talofibulare posterius","short":"Het ligamentum talofibulare posterius is de sterkste laterale enkelband, van de malleolus lateralis naar de achterzijde van de talus.","definition":"<p>Het <strong>lig. talofibulare posterius</strong> loopt vrijwel horizontaal en raakt bij een gewoon inversietrauma zelden beschadigd; dat gebeurt pas bij ernstige letsels zoals een enkelluxatie.</p>","image_url":"","wiki_title":"Posterior talofibular ligament","match":"lig. talofibulare posterior","option_only":true},"lig. calcaneofibulare (cf)":{"title":"Ligamentum calcaneofibulare","short":"Het ligamentum calcaneofibulare is een laterale enkelband van de malleolus lateralis naar de calcaneus.","definition":"<p>Het <strong>lig. calcaneofibulare</strong> vormt met het lig. talofibulare anterius en posterius het laterale bandcomplex van de enkel en overspant zowel het bovenste als het onderste spronggewricht.</p>","image_url":"","wiki_title":"Calcaneofibular ligament","match":"lig. calcaneofibulare (cf)","option_only":true},"lig. deltoïdeum":{"title":"Ligamentum deltoideum","short":"Het ligamentum deltoideum is de sterke, waaiervormige band aan de binnenzijde van de enkel.","definition":"<p>Het <strong>lig. deltoideum</strong> loopt van de malleolus medialis naar os naviculare, talus en calcaneus en heeft een oppervlakkige en een diepe laag. Het is veel sterker dan de laterale enkelbanden en stabiliseert de enkel aan de mediale zijde.</p>","image_url":"","wiki_title":"Deltoid ligament","match":"lig. deltoïdeum","option_only":true},"lig. collaterale tibiale":{"title":"Mediaal collateraal ligament (knie)","short":"Het mediale collaterale ligament van de knie loopt van de mediale femurcondyl naar de tibia en beschermt tegen valgusbelasting.","definition":"<p>Het <strong>MCL</strong> is verbonden met het kapsel en de mediale meniscus. Letsels ontstaan bij een klap tegen de buitenkant van de knie en genezen meestal goed conservatief. Bij de ‘unhappy triad’ zijn MCL, voorste kruisband en mediale meniscus samen beschadigd.</p>","image_url":"","wiki_title":"Medial collateral ligament","match":"lig. collaterale tibiale","option_only":true},"lig. collaterale fibulare":{"title":"Lateraal collateraal ligament (knie)","short":"Het laterale collaterale ligament van de knie loopt van de femur naar de fibulakop en stabiliseert de knie tegen varusbelasting.","definition":"<p>Het <strong>LCL</strong> ligt buiten het gewrichtskapsel en is niet verbonden met de meniscus (anders dan het mediale collaterale ligament). Letsel ontstaat bij een klap aan de binnenkant van de knie en gaat soms samen met letsel van de n. fibularis.</p>","image_url":"","wiki_title":"Fibular collateral ligament","match":"lig. collaterale fibulare","option_only":true},"lig. patellae":{"title":"Ligamentum patellae (patellapees)","short":"Het ligamentum patellae verbindt de knieschijf met de tuberositas tibiae en is de voortzetting van de quadricepspees.","definition":"<p>Overbelasting van de <strong>patellapees</strong> geeft een jumper's knee; bij groeiende kinderen een Osgood-Schlatter (tuberositas) of Sinding-Larsen-Johansson (onderpool patella). De kniepeesreflex wordt opgewekt door op de patellapees te tikken (L3–L4).</p>","image_url":"","wiki_title":"Patellar ligament","match":"lig. patellae","option_only":true},"het informatieve model":{"title":"Informatief model","short":"In het informatieve model geeft de arts feitelijke informatie en kiest de patiënt zelf, zonder dat de arts een advies geeft.","definition":"<p>In het <strong>informatieve model</strong> (Emanuel en Emanuel) is de arts een technisch deskundige die alle relevante informatie geeft, terwijl de patiënt volledig autonoom beslist. Andere modellen zijn het paternalistische, het interpretatieve en het deliberatieve model; gedeelde besluitvorming ligt tussen deze uitersten.</p>","image_url":"","wiki_title":"","match":"het informatieve model","option_only":true},"paternalisme model":{"title":"Paternalistisch model","short":"In het paternalistische model beslist de arts wat goed is voor de patiënt, met weinig inbreng van de patiënt.","definition":"<p>Het <strong>paternalistische model</strong> (Emanuel en Emanuel) staat tegenover het informatieve model (de patiënt beslist) en gedeelde besluitvorming. Het past soms in acute situaties, maar in de meeste keuzes wordt gedeelde besluitvorming nagestreefd.</p>","image_url":"","wiki_title":"","match":"paternalisme model","option_only":true},"ac luxatie":{"title":"Acromioclaviculair gewricht","short":"Het AC-gewricht verbindt het acromion met het laterale uiteinde van de clavicula.","definition":"<p>Een <strong>AC-luxatie</strong> ontstaat bij een val op de schouder; bij ernstige vormen zijn ook de coracoclaviculaire banden gescheurd en staat de clavicula hoog (pianotoetsfenomeen). Artrose van het AC-gewricht geeft pijn bovenop de schouder, vooral bij armheffen boven het hoofd.</p>","image_url":"","wiki_title":"Acromioclavicular joint","match":"ac luxatie","option_only":true},"painful arc-syndroom":{"title":"Subacromiaal pijnsyndroom (impingement)","short":"Bij het subacromiaal pijnsyndroom ontstaat pijn bij het heffen van de arm, vaak met een pijnlijk traject tussen ongeveer 60 en 120°.","definition":"<p>Bij <strong>subacromiale klachten</strong> zijn de supraspinatuspees en de bursa subacromialis geprikkeld in de ruimte onder het acromion. Kenmerkend is een ‘painful arc’ bij abductie. Behandeling: belasting aanpassen, oefentherapie en eventueel een injectie.</p>","image_url":"","wiki_title":"Shoulder impingement syndrome","match":"painful arc-syndroom","option_only":true},"subacromiaal impingement syndroom":{"title":"Subacromiaal pijnsyndroom (impingement)","short":"Bij het subacromiaal pijnsyndroom ontstaat pijn bij het heffen van de arm, vaak met een pijnlijk traject tussen ongeveer 60 en 120°.","definition":"<p>Bij <strong>subacromiale klachten</strong> zijn de supraspinatuspees en de bursa subacromialis geprikkeld in de ruimte onder het acromion. Kenmerkend is een ‘painful arc’ bij abductie. Behandeling: belasting aanpassen, oefentherapie en eventueel een injectie.</p>","image_url":"","wiki_title":"Shoulder impingement syndrome","match":"subacromiaal impingement syndroom","option_only":true},"een bursitis":{"title":"Bursitis","short":"Bursitis is een ontsteking van een slijmbeurs, bijvoorbeeld bij elleboog, knie of heup.","definition":"<p>Een <strong>bursa</strong> is een met vocht gevuld zakje dat wrijving tussen pees, spier, bot en huid vermindert. <strong>Bursitis</strong> ontstaat door overbelasting, druk, trauma, jicht of infectie. Oppervlakkige bursae (bij olecranon en patella) zwellen zichtbaar op; bij een rood, warm en pijnlijk beeld moet aan een septische bursitis worden gedacht.</p>","image_url":"","wiki_title":"Bursitis","match":"een bursitis","option_only":true},"een artritis":{"title":"Artritis","short":"Artritis is een ontsteking van een gewricht, met pijn, zwelling, warmte en bewegingsbeperking.","definition":"<p><strong>Artritis</strong> wordt ingedeeld naar het aantal gewrichten (mono-, oligo-, polyartritis) en de oorzaak: infectieus (septische artritis), kristalgeïnduceerd (jicht, pseudojicht), auto-immuun (reumatoïde artritis, spondyloartritis, SLE) of reactief. Bij een acute monoartritis is een gewrichtspunctie belangrijk om infectie en kristallen aan te tonen.</p>","image_url":"","wiki_title":"Arthritis","match":"een artritis","option_only":true},"colles fractuur":{"title":"Distale radiusfractuur","short":"Een distale radiusfractuur is een breuk van het spaakbeen vlak boven de pols, meestal na een val op de uitgestrekte hand.","definition":"<p>Bij de klassieke <strong>Colles-fractuur</strong> is het distale fragment naar dorsaal gekanteld (‘vorkstand’). Bij ouderen wijst het vaak op osteoporose. Behandeling: repositie en gips of operatieve fixatie. Complicaties zijn standsafwijkingen, ruptuur van de pees van de m. extensor pollicis longus, carpaletunnelsyndroom en complex regionaal pijnsyndroom.</p>","image_url":"","wiki_title":"Distal radius fracture","match":"colles fractuur","option_only":true},"coxarthrosis duplex":{"title":"Coxartrose (heupartrose)","short":"Coxartrose is slijtage van het heupgewricht, met pijn in lies of bil en een beperkte (vooral endo)rotatie.","definition":"<p>Bij <strong>coxartrose</strong> geeft het kraakbeenverlies startpijn, pijn bij belasting en een beperking van de bewegingen, het eerst van endorotatie en flexie. De pijn wordt vaak in de lies gevoeld en kan uitstralen naar de knie. Behandeling begint met oefentherapie, gewichtsverlies en pijnstilling; bij ernstige klachten volgt een totale heupprothese.</p>","image_url":"","wiki_title":"Hip osteoarthritis","match":"coxarthrosis duplex","option_only":true},"vasculaire claudicatio intermittens":{"title":"Claudicatio intermittens","short":"Claudicatio intermittens is pijn in de kuit of bil bij lopen die bij stilstaan verdwijnt, door perifeer arterieel vaatlijden.","definition":"<p>Bij <strong>claudicatio</strong> zijn de beenarteriën vernauwd door atherosclerose. De enkel-armindex is verlaagd (&lt;0,9). Behandeling: stoppen met roken, gesuperviseerde looptraining, een plaatjesremmer en statine; bij ernstige klachten of kritieke ischemie (rustpijn, wonden) revascularisatie.</p>","image_url":"","wiki_title":"Intermittent claudication","match":"vasculaire claudicatio intermittens","option_only":true},"collumfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"collumfractuur","option_only":true},"collumfractuur links":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"collumfractuur links","option_only":true},"mediale collumfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"mediale collumfractuur","option_only":true},"pertrochantere fractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"pertrochantere fractuur","option_only":true},"proximale femurfractuur":{"title":"Femurfractuur","short":"Een femurfractuur is een breuk van het dijbeen; bij ouderen vooral in het collum (heupfractuur), bij jongeren vaak in de schacht door hoog geweld.","definition":"<p><strong>Heupfracturen</strong> bij ouderen (mediale collumfractuur of pertrochantere fractuur) ontstaan vaak na een val bij osteoporose; het been staat verkort en naar buiten gedraaid. Ze hebben een hoge sterfte en morbiditeit. Schachtfracturen kunnen veel bloedverlies geven. Behandeling is meestal operatief.</p>","image_url":"","wiki_title":"Femoral fracture","match":"proximale femurfractuur","option_only":true},"hydrops test":{"title":"Hydropstest","short":"Met een hydropstest wordt onderzocht of er vocht (hydrops) in het kniegewricht zit.","definition":"<p>Bij de <strong>hydropstest</strong> wordt het vocht uit de recessus suprapatellaris naar beneden gestreken en daarna op de patella gedrukt (dansende patella) of een vochtgolf opgewekt. Veel vocht na een trauma kan wijzen op een kruisbandletsel of fractuur (hemartros).</p>","image_url":"","wiki_title":"","match":"hydrops test","option_only":true},"intra-beoordelaarsbetrouwbaarheid":{"title":"Intrabeoordelaarsbetrouwbaarheid","short":"Intrabeoordelaarsbetrouwbaarheid is de mate waarin dezelfde beoordelaar bij herhaling tot dezelfde uitkomst komt.","definition":"<p>Bij <strong>intrabeoordelaarsbetrouwbaarheid</strong> beoordeelt één persoon dezelfde situatie meerdere keren; bij interbeoordelaarsbetrouwbaarheid vergelijkt men verschillende beoordelaars. Voor categorische uitkomsten wordt vaak Cohens kappa gebruikt, voor continue de ICC.</p>","image_url":"","wiki_title":"Intra-rater reliability","match":"intra-beoordelaarsbetrouwbaarheid","option_only":true},"inter-beoordelaarsbetrouwbaarheid":{"title":"Intrabeoordelaarsbetrouwbaarheid","short":"Intrabeoordelaarsbetrouwbaarheid is de mate waarin dezelfde beoordelaar bij herhaling tot dezelfde uitkomst komt.","definition":"<p>Bij <strong>intrabeoordelaarsbetrouwbaarheid</strong> beoordeelt één persoon dezelfde situatie meerdere keren; bij interbeoordelaarsbetrouwbaarheid vergelijkt men verschillende beoordelaars. Voor categorische uitkomsten wordt vaak Cohens kappa gebruikt, voor continue de ICC.</p>","image_url":"","wiki_title":"Intra-rater reliability","match":"inter-beoordelaarsbetrouwbaarheid","option_only":true},"zorg-gerelateerde preventie":{"title":"Zorggerelateerde preventie","short":"Zorggerelateerde preventie richt zich op mensen met een ziekte, om ziektelast, complicaties en verergering te beperken.","definition":"<p>Bij <strong>zorggerelateerde preventie</strong> gaat het bijvoorbeeld om leefstijlbegeleiding bij diabetes of hart- en vaatziekten, of valpreventie bij ouderen met osteoporose. Het hoort bij de indeling naar doelgroep: universeel, selectief, geïndiceerd en zorggerelateerd.</p>","image_url":"","wiki_title":"","match":"zorg-gerelateerde preventie","option_only":true},"ligamentum talofibulare anterius":{"title":"Lig. talofibulare anterius","short":"Het lig. talofibulare anterius loopt van de laterale malleolus naar de talus en is de enkelband die het vaakst scheurt.","definition":"<p>Het <strong>lig. talofibulare anterius</strong> is vooral gespannen in plantairflexie, de stand waarin inversietrauma's meestal optreden. Een positieve voorste schuiflade wijst op een ruptuur.</p>","image_url":"","wiki_title":"Anterior talofibular ligament","match":"ligamentum talofibulare anterius|ligamentum fibulotalare anterius|lig. talofibulare anterior (tfa)|lig. talofibulare anterior|atfl","option_only":true},"peer education theorie":{"title":"Peer education","short":"Bij peer education geven leeftijd- of lotgenoten voorlichting, omdat de doelgroep zich met hen identificeert.","definition":"<p><strong>Peer education</strong> leunt op de sociaal-cognitieve theorie (leren van rolmodellen) en de diffusietheorie. Het wordt o.a. gebruikt bij seksuele voorlichting en preventie van middelengebruik onder jongeren.</p>","image_url":"","wiki_title":"Peer education","match":"peer education theorie|peer education","option_only":true},"tendovaginitis van de quervain":{"title":"Tendovaginitis van De Quervain","short":"Bij tendovaginitis van De Quervain is de peesschede van het eerste dorsale compartiment van de pols geprikkeld, met pijn aan de duimzijde.","definition":"<p>De klachten ontstaan door overbelasting, bijv. bij jonge moeders die hun baby tillen. De <strong>test van Finkelstein</strong> (duim in de vuist en pols naar ulnair) lokt pijn uit. Behandeling: rust, een spalk, een corticosteroïdinjectie of een splijting van de peesschede.</p>","image_url":"","wiki_title":"De Quervain syndrome","match":"tendovaginitis van de quervain|de quervain tenosynovitis|ziekte van de quervain","option_only":true},"osgood schlatter":{"title":"Ziekte van Osgood-Schlatter","short":"Osgood-Schlatter is een overbelasting van de aanhechting van de patellapees aan de tuberositas tibiae bij sportende kinderen in de groeispurt.","definition":"<p>Er is pijn en zwelling onder de knie bij springen, rennen en knielen. De klachten gaan meestal vanzelf over als de groei stopt; een blijvende knobbel is mogelijk. Behandeling: belasting aanpassen.</p>","image_url":"","wiki_title":"Osgood–Schlatter disease","match":"osgood schlatter|osgood-schlatter|ziekte van osgood-schlatter","option_only":true},"tenniselleboog":{"title":"Tenniselleboog (epicondylalgie lateralis)","short":"Een tenniselleboog is pijn aan de buitenkant van de elleboog door overbelasting van de aanhechting van de polsstrekkers.","definition":"<p>Vooral de pees van de m. extensor carpi radialis brevis is betrokken. Pijn wordt uitgelokt door strekken van de pols tegen weerstand en grijpen. Het herstelt meestal vanzelf binnen een jaar; een golferselleboog zit aan de binnenkant (buigers).</p>","image_url":"","wiki_title":"Tennis elbow","match":"tenniselleboog|epicondylitis lateralis|epicondylalgie lateralis","option_only":true},"wgbo":{"title":"WGBO (Wet op de geneeskundige behandelingsovereenkomst)","short":"De WGBO regelt de rechten en plichten van patiënt en hulpverlener bij een medische behandeling.","definition":"<p>Onder de <strong>WGBO</strong> vallen o.a. het recht op informatie, toestemming (informed consent), het medisch dossier (inzage, bewaartermijn) en het beroepsgeheim. Bij wilsonbekwame patiënten beslist een vertegenwoordiger. Voor kinderen gelden leeftijdsgrenzen (12 en 16 jaar).</p>","image_url":"","wiki_title":"","match":"wgbo|wet geneeskundige behandelovereenkomst|wet op de geneeskundige behandelingsovereenkomst","option_only":true},"theorie van beredeneerd gedrag":{"title":"Theorie van beredeneerd gedrag","short":"Volgens de theorie van beredeneerd gedrag (Fishbein en Ajzen) wordt gedrag voorspeld door de intentie, die afhangt van attitude en sociale norm.","definition":"<p>De latere <strong>theorie van gepland gedrag</strong> voegt daar de waargenomen gedragscontrole aan toe, omdat niet alle gedrag volledig onder eigen controle staat.</p>","image_url":"","wiki_title":"Theory of reasoned action","match":"theorie van beredeneerd gedrag|theory of reasoned action","option_only":true},"gezondheidsbevordering":{"title":"Gezondheidsbevordering","short":"Gezondheidsbevordering is het verbeteren van gezondheid door voorlichting, gedragsverandering en het gezonder maken van de omgeving.","definition":"<p>Volgens het <strong>Ottawa Charter</strong> (WHO) gaat gezondheidsbevordering verder dan voorlichting: ook beleid, een ondersteunende omgeving, gemeenschapsactie en een heroriëntatie van de zorg horen erbij. Planmodellen zoals Intervention Mapping helpen interventies systematisch te ontwikkelen.</p>","image_url":"","wiki_title":"Health promotion","match":"gezondheidsbevordering|health promotion","option_only":true},"ligamentum fibulotalare anterius":{"title":"Lig. talofibulare anterius","short":"Het lig. talofibulare anterius loopt van de laterale malleolus naar de talus en is de enkelband die het vaakst scheurt.","definition":"<p>Het <strong>lig. talofibulare anterius</strong> is vooral gespannen in plantairflexie, de stand waarin inversietrauma's meestal optreden. Een positieve voorste schuiflade wijst op een ruptuur.</p>","image_url":"","wiki_title":"Anterior talofibular ligament","match":"ligamentum fibulotalare anterius","option_only":true},"lig. talofibulare anterior (tfa)":{"title":"Lig. talofibulare anterius","short":"Het lig. talofibulare anterius loopt van de laterale malleolus naar de talus en is de enkelband die het vaakst scheurt.","definition":"<p>Het <strong>lig. talofibulare anterius</strong> is vooral gespannen in plantairflexie, de stand waarin inversietrauma's meestal optreden. Een positieve voorste schuiflade wijst op een ruptuur.</p>","image_url":"","wiki_title":"Anterior talofibular ligament","match":"lig. talofibulare anterior (tfa)","option_only":true},"lig. talofibulare anterior":{"title":"Lig. talofibulare anterius","short":"Het lig. talofibulare anterius loopt van de laterale malleolus naar de talus en is de enkelband die het vaakst scheurt.","definition":"<p>Het <strong>lig. talofibulare anterius</strong> is vooral gespannen in plantairflexie, de stand waarin inversietrauma's meestal optreden. Een positieve voorste schuiflade wijst op een ruptuur.</p>","image_url":"","wiki_title":"Anterior talofibular ligament","match":"lig. talofibulare anterior","option_only":true},"de quervain tenosynovitis":{"title":"Tendovaginitis van De Quervain","short":"Bij tendovaginitis van De Quervain is de peesschede van het eerste dorsale compartiment van de pols geprikkeld, met pijn aan de duimzijde.","definition":"<p>De klachten ontstaan door overbelasting, bijv. bij jonge moeders die hun baby tillen. De <strong>test van Finkelstein</strong> (duim in de vuist en pols naar ulnair) lokt pijn uit. Behandeling: rust, een spalk, een corticosteroïdinjectie of een splijting van de peesschede.</p>","image_url":"","wiki_title":"De Quervain syndrome","match":"de quervain tenosynovitis","option_only":true},"wet geneeskundige behandelovereenkomst":{"title":"WGBO (Wet op de geneeskundige behandelingsovereenkomst)","short":"De WGBO regelt de rechten en plichten van patiënt en hulpverlener bij een medische behandeling.","definition":"<p>Onder de <strong>WGBO</strong> vallen o.a. het recht op informatie, toestemming (informed consent), het medisch dossier (inzage, bewaartermijn) en het beroepsgeheim. Bij wilsonbekwame patiënten beslist een vertegenwoordiger. Voor kinderen gelden leeftijdsgrenzen (12 en 16 jaar).</p>","image_url":"","wiki_title":"","match":"wet geneeskundige behandelovereenkomst","option_only":true},"mri scan":{"title":"MRI","short":"MRI maakt met een sterk magneetveld en radiogolven gedetailleerde beelden van weke delen, zonder ioniserende straling.","definition":"<p>Bij <strong>MRI</strong> worden waterstofkernen in een sterk magneetveld door radiogolven aangeslagen; het signaal bij terugkeer verschilt per weefseltype. MRI is bijzonder geschikt voor hersenen, ruggenmerg, gewrichten, weke delen en het bekken. Nadelen zijn de lange duur, kosten en beperkingen bij pacemakers en sommige metalen implantaten.</p>","image_url":"","wiki_title":"Magnetic resonance imaging","match":"mri scan","option_only":true},"peesruptuur":{"title":"Peesruptuur","short":"Een peesruptuur is een (gedeeltelijke) scheur van een pees. Fluorochinolonen kunnen het risico hierop verhogen.","definition":"<p>Een <strong>peesruptuur</strong> is een scheur van een pees, klassiek de achillespees. <em>Fluorochinolonen</em> (ciprofloxacine, moxifloxacine) verhogen het risico, vooral bij ouderen en bij gelijktijdig corticosteroïdgebruik.</p>","image_url":"","wiki_title":"","match":"peesruptuur","option_only":true},"wet arbeidsongeschiktheidsverzekering zelfstandigen (waz)":{"title":"Wet Afbreking Zwangerschap (WAZ)","short":"Wet die de voorwaarden voor zwangerschapsafbreking regelt, waaronder vergunning, noodsituatie en beraadtermijn.","definition":"<p>Onder de <strong>WAZ</strong> mag een afbreking alleen in een kliniek met vergunning; buiten de overtijdbehandeling geldt een verplichte beraadtermijn van 5 dagen.</p>","image_url":"","wiki_title":"","match":"wet arbeidsongeschiktheidsverzekering zelfstandigen (waz)","option_only":true},"screening":{"title":"Screening","short":"Het systematisch opsporen van (voorstadia van) ziekte bij mensen zonder klachten, om vroege behandeling mogelijk te maken.","definition":"<p><b>Screening</b> (bevolkingsonderzoek) is het systematisch onderzoeken van een asymptomatische populatie op (risico op) een aandoening, met als doel vroege opsporing en behandeling. Bepaalde vormen zijn in Nederland vergunningplichtig onder de Wet op het Bevolkingsonderzoek (WBO).</p>","image_url":"","wiki_title":"Screening (medicine)","match":"screening","option_only":true},"door werk verergerd astma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"door werk verergerd astma","option_only":true},"malleolus":{"title":"Malleolus","short":"De malleoli zijn de twee botknobbels aan de enkel: de mediale malleolus (tibia) en de laterale malleolus (fibula).","definition":"<p>De <strong>malleolus medialis</strong> (van de tibia) en <strong>malleolus lateralis</strong> (van de fibula) vormen de 'enkelvork' die het bovenste spronggewricht stabiliseert.</p>","image_url":"","wiki_title":"Malleolus","match":"malleolus","option_only":true},"basisverzekering":{"title":"Basisverzekering","short":"Wettelijk verplichte zorgverzekering met een door de overheid vastgesteld standaardpakket en acceptatieplicht.","definition":"<p>De <b>basisverzekering</b> is de voor iedereen verplichte zorgverzekering (Zvw) met een door de overheid vastgesteld pakket. Verzekeraars hebben acceptatieplicht en mogen voor dezelfde polis geen onderscheid in premie maken; risicoverevening compenseert hen voor dure verzekerden.</p>","image_url":"","wiki_title":"","match":"basisverzekering","option_only":true},"ggd":{"title":"GGD","short":"Gemeentelijke Gezondheidsdienst; voert publieke-gezondheidstaken uit voor gemeenten.","definition":"<p>De <b>GGD</b> (Gemeentelijke/Gemeenschappelijke Gezondheidsdienst) voert namens gemeenten taken uit de Wet publieke gezondheid uit, zoals infectieziektebestrijding, jeugdgezondheidszorg en forensische geneeskunde. Uitbraken van bv. diarree op de kinderopvang worden hier gemeld.","image_url":"","wiki_title":"","match":"ggd","option_only":true},"arbeidshygiënist":{"title":"arbeidshygiënist","short":"Deskundige die werkgerelateerde risico's (zoals de RIE) in kaart brengt en beheerst.","definition":"<p>De <b>arbeidshygiënist</b> inventariseert en beheerst blootstelling en risico's op de werkplek.</p>","image_url":"","wiki_title":"","match":"arbeidshygiënist","option_only":true},"extrinsieke allergische alveolitis (eaa)":{"title":"Extrinsieke allergische alveolitis","short":"Extrinsieke allergische alveolitis is een immuunreactie (type III/IV) in de alveoli op ingeademde organische stoffen, zoals schimmelsporen of vogeleiwitten.","definition":"<p>Bij <strong>hypersensitivity pneumonitis</strong> (extrinsieke allergische alveolitis) reageert het immuunsysteem op herhaald ingeademde organische antigenen: schimmelsporen uit hooi (boerenlong), vogeleiwitten (duivenmelkerslong) of bevochtigerwater.</p><p>Het mechanisme is een type III- (immuuncomplex) en type IV- (T-cel) reactie met lymfocytaire alveolitis en kleine granulomen. Acuut: koorts, hoesten en kortademigheid enkele uren na blootstelling; chronisch kan longfibrose ontstaan. Behandeling: blootstelling vermijden, eventueel corticosteroïden.</p>","image_url":"","wiki_title":"Hypersensitivity pneumonitis","match":"extrinsieke allergische alveolitis (eaa)","option_only":true},"bovenste spronggewricht":{"title":"Bovenste spronggewricht","short":"De articulatio talocruralis tussen tibia/fibula en talus; hier vinden dorsaal- en plantairflexie plaats.","definition":"<p>Het <b>bovenste spronggewricht</b> (art. talocruralis) ligt tussen de malleoli van tibia en fibula en de talus. De primaire bewegingen zijn dorsaalflexie en plantairflexie.</p>","image_url":"","wiki_title":"Ankle","match":"bovenste spronggewricht","option_only":true},"triangulaire fibrocartilagineuze complex (tfcc-laesie)":{"title":"TFCC-laesie","short":"Beschadiging van het triangulaire fibrocartilagineuze complex aan de ulnaire zijde van de pols.","definition":"<p>Een <b>TFCC-laesie</b> is een scheur van het triangulaire fibrocartilagineuze complex, een kraakbeen-band-structuur aan de ulnaire (pink)zijde van de pols die het distale radio-ulnaire gewricht stabiliseert. Geeft pijn aan de ulnaire polszijde bij belasting.</p>","image_url":"","wiki_title":"Triangular fibrocartilage","match":"triangulaire fibrocartilagineuze complex (tfcc-laesie)","option_only":true},"totale ziektelast":{"title":"Verloren levensjaren en ziektelast (DALY)","short":"De ziektelast van een aandoening wordt vaak uitgedrukt in DALY's: verloren levensjaren door vroegtijdige sterfte plus jaren geleefd met ziekte.","definition":"<p>Een <strong>DALY</strong> (disability-adjusted life year) combineert sterfte (verloren levensjaren) en beperkingen (jaren met ziekte, gewogen naar ernst). Zo kunnen ziekten die vooral sterfte geven worden vergeleken met ziekten die vooral beperkingen geven, zoals depressie.</p>","image_url":"","wiki_title":"Disability-adjusted life year","match":"totale ziektelast","option_only":true},"risicoperceptie":{"title":"Risicoperceptie","short":"De inschatting die iemand maakt van een gezondheidsrisico.","definition":"Patiënten neigen ertoe hun eigen <b>risicoperceptie</b> te onderschatten ('mij overkomt het niet').","image_url":"","wiki_title":"","match":"risicoperceptie","option_only":true},"bursitis olecrani":{"title":"Bursitis olecrani","short":"'Student's elbow'; ontsteking van de slijmbeurs op de elleboogpunt.","definition":"<b>Bursitis olecrani</b> is een ontsteking van de bursa over het olecranon, vaak door langdurig leunen ('student's elbow').","image_url":"","wiki_title":"Olecranon bursitis","match":"bursitis olecrani","option_only":true},"tfcc-laesie (triangulaire fibrocartilagineuze complex)":{"title":"TFCC-laesie","short":"Beschadiging van het triangulaire fibrocartilagineuze complex aan de ulnaire zijde van de pols.","definition":"<p>Een <b>TFCC-laesie</b> is een scheur van het triangulaire fibrocartilagineuze complex, een kraakbeen-band-structuur aan de ulnaire (pink)zijde van de pols die het distale radio-ulnaire gewricht stabiliseert. Geeft pijn aan de ulnaire polszijde bij belasting.</p>","image_url":"","wiki_title":"Triangular fibrocartilage","match":"tfcc-laesie (triangulaire fibrocartilagineuze complex)","option_only":true},"framing":{"title":"framing","short":"Manier waarop informatie (bijv. een risico) wordt gepresenteerd, wat de perceptie en besluitvorming beïnvloedt.","definition":"<p><b>Framing</b> is het effect van de wijze van presenteren van informatie op de beoordeling ervan.</p>","image_url":"","wiki_title":"Framing effect","match":"framing","option_only":true},"lig. capitis femoris":{"title":"Ligamentum capitis femoris","short":"Bandje in het heupgewricht met de a. lig. capitis femoris; levert bij volwassenen slechts een geringe bloedvoorziening aan de femurkop.","definition":"<p>Intra-articulair ligament dat de femurkop met het acetabulum verbindt. Bevat een kleine arterie die bij volwassenen onvoldoende is om de kop zelfstandig te voeden.</p>","image_url":"","wiki_title":"","match":"lig. capitis femoris","option_only":true},"wet kwaliteit, klachten en geschillen zorg":{"title":"Wkkgz","short":"Wet die goede zorg, klachtafhandeling en geschillenbeslechting in de zorg regelt.","definition":"<p>De <b>Wkkgz</b> verplicht zorgaanbieders tot het leveren van 'goede zorg' en regelt de klachten- en geschillenprocedure. Een patient met een schadeclaim gaat eerst naar de geschillencommissie.</p>","image_url":"","wiki_title":"","match":"wet kwaliteit, klachten en geschillen zorg","option_only":true},"os coxae":{"title":"Os coxae (heupbeen)","short":"Het heupbeen, opgebouwd uit os ilium, os ischii en os pubis, die samensmelten in het acetabulum.","definition":"<p>Het <strong>os coxae</strong> vormt samen met het os sacrum en os coccygis het benige bekken.</p>","image_url":"","wiki_title":"Hip bone","match":"os coxae","option_only":true},"effectiviteit":{"title":"Effectiviteit","short":"Mate waarin een behandeling het beoogde gezondheidsresultaat bereikt in de praktijk.","definition":"<p><b>Effectiviteit</b> is de mate waarin een interventie in de dagelijkse praktijk het gewenste effect oplevert. Het is een van de kwaliteitsdomeinen van zorg.</p>","image_url":"","wiki_title":"","match":"effectiviteit","option_only":true},"doelmatigheid":{"title":"Doelmatigheid","short":"Het beginsel dat een maatregel daadwerkelijk effectief moet zijn om het beoogde doel te bereiken.","definition":"<p>Doelmatigheid beoordeelt of de gekozen maatregel het beoogde effect heeft. Als een maatregel het doel niet bereikt of averechts werkt, is zij niet doelmatig en moet zij worden heroverwogen.</p>","image_url":"","wiki_title":"","match":"doelmatigheid","option_only":true},"risicospreiding":{"title":"Risicosolidariteit","short":"Bij risicosolidariteit betalen gezonde mensen mee voor de zorgkosten van zieken, doordat iedereen dezelfde premie betaalt.","definition":"<p>Het verbod op premiedifferentiatie en de acceptatieplicht in de basisverzekering zorgen voor <strong>risicosolidariteit</strong>. Bij aanvullende verzekeringen is die beperkter, omdat verzekeraars daar mogen selecteren.</p>","image_url":"","wiki_title":"","match":"risicospreiding","option_only":true},"informed consent":{"title":"Informed consent","short":"Toestemming voor een behandeling nadat de patiënt volledig is geïnformeerd over aard, doel, gevolgen, risico's en alternatieven.","definition":"<p><b>Informed consent</b> is de geïnformeerde toestemming van de patiënt. Volgens de WGBO moet de arts informeren over: (1) aard en doel van onderzoek/behandeling, (2) te verwachten gevolgen en risico's, (3) alternatieve methoden, en (4) de gezondheidstoestand en vooruitzichten.</p>","image_url":"","wiki_title":"Informed consent","match":"informed consent","option_only":true},"hepatitis a infectie":{"title":"Hepatitis A","short":"Hepatitis A is een fecaal-oraal overgedragen virale leverontsteking die acuut verloopt en nooit chronisch wordt.","definition":"<p><strong>Hepatitis A</strong> wordt veroorzaakt door het hepatitis A-virus, een niet-omhuld RNA-virus dat fecaal-oraal wordt overgedragen (besmet water en voedsel, reizen).</p><p>Het geeft een acute hepatitis met moeheid, misselijkheid, geelzucht en verhoogde transaminasen; bij jonge kinderen vaak zonder klachten. Hepatitis A wordt <em>niet chronisch</em> en geeft levenslange immuniteit. Er is een vaccin.</p>","image_url":"","wiki_title":"Hepatitis A","match":"hepatitis a infectie","option_only":true},"werkgerelateerd astma":{"title":"Beroepsastma","short":"Beroepsastma is astma dat door stoffen op het werk ontstaat, zoals meelstof bij bakkers of isocyanaten bij spuiters.","definition":"<p>Typisch voor <strong>beroepsastma</strong> zijn klachten die verbeteren in het weekend en de vakanties. Vroeg stoppen met blootstelling geeft de beste kans op herstel. Het is een beroepsziekte die moet worden gemeld.</p>","image_url":"","wiki_title":"Occupational asthma","match":"werkgerelateerd astma","option_only":true}};
